"use server";

import { http } from "@/lib/http";
import { protectedActionClient } from "@/lib/safe-action";
import { CartItemSchema } from "@/lib/schemas";
import { ApiResponse } from "@/types/dtos";
import { Sku } from "@/types/models";
import { revalidatePath } from "next/cache";
import { cookies } from "next/headers";
import { z } from "zod";

/**
 * =====================================================================
 * CART SERVER ACTIONS
 * =====================================================================
 */

const UpdateCartItemSchema = z.object({
  itemId: z.string(),
  quantity: z.number().int().min(1),
});

const RemoveCartItemSchema = z.object({
  itemId: z.string(),
});

const ReorderSchema = z.object({
  orderId: z.string(),
});

const MergeCartSchema = z.array(CartItemSchema);

const GuestCartDetailsSchema = z.object({ skuIds: z.array(z.string()) });

// --- SAFE ACTIONS ---

const safeAddToCart = protectedActionClient
  .schema(CartItemSchema)
  .action(async ({ parsedInput }) => {
    try {
      await http("/cart", {
        method: "POST",
        body: JSON.stringify(parsedInput),
        skipRedirectOn401: true,
      });
      revalidatePath("/cart");
      return { success: true };
    } catch (error: unknown) {
      throw error;
    }
  });

const safeUpdateCartItem = protectedActionClient
  .schema(UpdateCartItemSchema)
  .action(async ({ parsedInput }) => {
    try {
      await http(`/cart/items/${parsedInput.itemId}`, {
        method: "PATCH",
        body: JSON.stringify({ quantity: parsedInput.quantity }),
        skipRedirectOn401: true,
      });
      revalidatePath("/cart");
      return { success: true };
    } catch (error: unknown) {
      throw error;
    }
  });

const safeRemoveFromCart = protectedActionClient
  .schema(RemoveCartItemSchema)
  .action(async ({ parsedInput }) => {
    try {
      await http(`/cart/items/${parsedInput.itemId}`, {
        method: "DELETE",
        skipRedirectOn401: true,
      });
      revalidatePath("/cart");
      return { success: true };
    } catch (error) {
      throw error;
    }
  });

const safeClearCart = protectedActionClient.action(async () => {
  try {
    await http("/cart", {
      method: "DELETE",
      skipRedirectOn401: true,
    });
    revalidatePath("/cart");
    return { success: true };
  } catch (error) {
    throw error;
  }
});

const safeReorder = protectedActionClient
  .schema(ReorderSchema)
  .action(async ({ parsedInput }) => {
    // Logic from original reorderAction
    try {
      const orderRes = await http<
        ApiResponse<{ items?: { skuId: string; quantity: number }[] }>
      >(`/orders/my-orders/${parsedInput.orderId}`);
      const order = orderRes.data;
      if (!order || !order.items) {
        throw new Error("Order not found or has no items");
      }
      const promises = order.items.map(
        (item: { skuId: string; quantity: number }) =>
          http("/cart", {
            method: "POST",
            body: JSON.stringify({
              skuId: item.skuId,
              quantity: item.quantity,
            }),
          })
      );
      await Promise.allSettled(promises);
      revalidatePath("/cart");
      return { success: true };
    } catch (error) {
      throw error;
    }
  });

const safeMergeGuestCart = protectedActionClient
  .schema(MergeCartSchema)
  .action(async ({ parsedInput }) => {
    try {
      const res = await http<unknown[]>("/cart/merge", {
        method: "POST",
        body: JSON.stringify(parsedInput),
      });
      revalidatePath("/cart");
      return { success: true, results: res };
    } catch (error) {
      throw error;
    }
  });

// --- EXPORTS (WRAPPERS) ---

export async function addToCartAction(skuId: string, quantity: number = 1) {
  const result = await safeAddToCart({ skuId, quantity });
  if (result?.serverError || result?.validationErrors) {
    return { error: result.serverError || "Validation Failed" };
  }
  return { success: true };
}

export async function updateCartItemAction(itemId: string, quantity: number) {
  const result = await safeUpdateCartItem({ itemId, quantity });
  if (result?.serverError || result?.validationErrors) {
    // Need to handle that specific "availableStock" error structure from original?
    // For now, minimal compatibility.
    return { error: result.serverError || "Failed to update item" };
  }
  return { success: true };
}

export async function removeFromCartAction(itemId: string) {
  const result = await safeRemoveFromCart({ itemId });
  if (result?.serverError) return { error: "Failed to remove item" };
  return { success: true };
}

export async function clearCartAction() {
  const result = await safeClearCart();
  if (result?.serverError) return { error: "Failed to clear cart" };
  return { success: true };
}

export async function reorderAction(orderId: string) {
  const result = await safeReorder({ orderId });
  if (result?.serverError) return { error: result.serverError };
  return { success: true };
}

export async function mergeGuestCartAction(
  items: { skuId: string; quantity: number }[]
) {
  const result = await safeMergeGuestCart(items);
  if (result?.serverError) return { success: false, error: result.serverError };
  if (result?.data) return result.data; // { success: true, results: ... }
  return { success: false, error: "Merge failed" };
}

// Read-only or Public Actions (no sensitive change)
// Guest Cart details is public (skus details) but might need protection?
// Original code didn't use user token, just fetch details.
// So we keep it plain or use public safe action if we had one.
export async function getGuestCartDetailsAction(skuIds: string[]) {
  try {
    const res = await http<ApiResponse<Sku[]>>("/products/skus/details", {
      method: "POST",
      body: JSON.stringify({ skuIds }),
    });
    const items = Array.isArray(res) ? res : res.data;
    return { success: true, data: items };
  } catch (error: unknown) {
    return {
      error: error instanceof Error ? error.message : "Không thể lấy thông tin",
    };
  }
}

export async function getCartCountAction() {
  // This is a read action, can check auth but usually harmless.
  // Original checks cookies.
  await cookies();
  try {
    const response = await http<
      ApiResponse<{
        items: { quantity: number }[];
        totalItems: number;
      }>
    >("/cart", {
      next: { revalidate: 0 },
      skipRedirectOn401: true,
    });
    const cartData = response.data || response;
    const count =
      cartData.totalItems ||
      cartData.items?.reduce(
        (acc: number, item: { quantity: number }) => acc + (item.quantity || 0),
        0
      ) ||
      0;
    return { success: true, count };
  } catch {
    return { success: false, count: 0 };
  }
}

"use server";

import { http } from "@/lib/http";
import { protectedActionClient } from "@/lib/safe-action";
import { CheckoutSchema } from "@/lib/schemas";
import { ApiResponse } from "@/types/dtos";
import { Order } from "@/types/models";
import { revalidatePath } from "next/cache";
import { z } from "zod";

/**
 * =====================================================================
 * ORDER SERVER ACTIONS - Quản lý đơn hàng
 * =====================================================================
 */

const CancelOrderSchema = z.object({
  orderId: z.string(),
});

/**
 * Dữ liệu cần thiết để đặt hàng.
 */
interface PlaceOrderData {
  recipientName: string;
  phoneNumber: string;
  shippingAddress: string;
  addressId?: string;
  paymentMethod: "COD" | "CARD" | "BANKING" | "VNPAY";
  itemIds?: string[];
  couponCode?: string;
  returnUrl?: string;
}

// --- SAFE ACTIONS ---

const safePlaceOrder = protectedActionClient
  .schema(CheckoutSchema)
  .action(async ({ parsedInput }) => {
    try {
      const res = await http<
        ApiResponse<{
          id: string;
          paymentUrl?: string;
        }>
      >("/orders", {
        method: "POST",
        body: JSON.stringify(parsedInput),
      });

      const paymentUrl = res.data?.paymentUrl;
      const orderId = res.data?.id;

      revalidatePath("/cart");
      revalidatePath("/orders");

      return { success: true, paymentUrl, orderId };
    } catch (error: unknown) {
      throw error;
    }
  });

const safeCancelOrder = protectedActionClient
  .schema(CancelOrderSchema)
  .action(async ({ parsedInput }) => {
    try {
      await http(`/orders/${parsedInput.orderId}/status`, {
        method: "PATCH",
        body: JSON.stringify({ status: "CANCELLED" }),
      });
      revalidatePath("/orders");
      revalidatePath(`/orders/${parsedInput.orderId}`);
      return { success: true };
    } catch (error) {
      throw error;
    }
  });

// --- EXPORTS ---

export async function getMyOrdersAction(page = 1, limit = 10) {
  try {
    const res = await http<ApiResponse<Order[]>>(
      `/orders/my-orders?page=${page}&limit=${limit}`
    );
    return res;
  } catch (error: unknown) {
    return { error: (error as Error).message };
  }
}

export async function placeOrderAction(data: PlaceOrderData) {
  // @ts-ignore - CheckoutSchema matches PlaceOrderData roughly but Zod strictness might vary
  const result = await safePlaceOrder(data);

  if (result?.serverError || result?.validationErrors) {
    return { error: result.serverError || "Invalid order data" };
  }

  // result.data contains { success, paymentUrl, orderId }
  return result.data;
}

export async function cancelOrderAction(orderId: string) {
  const result = await safeCancelOrder({ orderId });

  if (result?.serverError) {
    return { error: result.serverError };
  }

  return { success: true };
}

/**
 * =====================================================================
 * CART CLIENT - Giao diện giỏ hàng chi tiết
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. HYBRID CART LOGIC (User & Guest):
 * - Nếu user đã đăng nhập: Dữ liệu lấy từ `cart` prop (Server Action).
 * - Nếu là khách (Guest): Dữ liệu lấy từ `localStorage` ('guest_cart').
 * - `useEffect` lắng nghe event `guest_cart_updated` để đồng bộ UI khi có thay đổi.
 *
 * 2. OPTIMISTIC UPDATES & DEBOUNCING:
 * - Khi thay đổi số lượng, UI cập nhật ngay lập tức (`localItems`).
 * - Sau đó dùng `setTimeout` (Debounce 500ms) để gọi API, tránh spam request.
 * - Nếu API lỗi, UI sẽ tự động rollback về dữ liệu cũ từ Server.
 *
 * 3. SELECTION SYSTEM:
 * - Cho phép user chọn từng món để thanh toán (`selectedItems`).
 * - Tự động tính toán lại tổng tiền dựa trên các món đã chọn.
 * =====================================================================
 */

"use client";

import {
    clearCartAction,
    getGuestCartDetailsAction,
    removeFromCartAction,
    updateCartItemAction,
} from "@/actions/cart";
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
    AlertDialogTrigger,
} from "@/components/atoms/alert-dialog";
import { Checkbox } from "@/components/atoms/checkbox";
import { GlassButton } from "@/components/atoms/glass-button";
import { GlassCard } from "@/components/atoms/glass-card";
import { Separator } from "@/components/atoms/separator";
import { useToast } from "@/hooks/use-toast";
import { Link } from "@/i18n/routing";
import { Cart, CartItem, Sku } from "@/types/models";
import { motion } from "framer-motion";
import {
    Lock,
    Minus,
    Plus,
    RefreshCcw,
    ShieldCheck,
    ShoppingBag,
    Trash2,
    Truck,
    X,
} from "lucide-react";
import { useFormatter, useTranslations } from "next-intl";
import Image from "next/image";
import { useCallback, useEffect, useRef, useState, useTransition } from "react";

// Extend shared types for stricter UI requirements (we know SKU must exist here)
interface PopulatedCartItem extends Omit<CartItem, "sku"> {
  sku: Sku & {
    product: {
      id: string;
      name: string;
      images?: string[];
    };
    optionValues?: {
      optionValueId: string;
      optionValue: {
        id: string;
        value: string;
        option: { name: string };
      };
    }[];
  };
}

// Helper interface for Guest Cart Local Storage
interface LocalGuestItem {
  skuId: string;
  quantity: number;
}

interface CartClientProps {
  cart: Cart | null;
}

export function CartClient({ cart }: CartClientProps) {
  const t = useTranslations("cart");
  const format = useFormatter();
  const [guestItems, setGuestItems] = useState<PopulatedCartItem[]>([]);
  const [totalGuest, setTotalGuest] = useState(0);
  const { toast } = useToast();
  const [isPending, startTransition] = useTransition();
  const debouncedUpdateRef = useRef<{ [key: string]: NodeJS.Timeout }>({});

  const containerVariants = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1,
      },
    },
  };

  const itemVariants = {
    hidden: { opacity: 0, x: -20 },
    visible: { opacity: 1, x: 0 },
  };

  const isGuest = !cart;
  // Cast server items to PopulatedCartItem assuming server returns valid structure
  // In a real app we might validate this, but for now we trust the server layout fetch
  const items = isGuest
    ? guestItems
    : ((cart?.items || []) as unknown as PopulatedCartItem[]);
  const total = isGuest ? totalGuest : Number(cart?.totalAmount) || 0;

  useEffect(() => {
    if (isGuest) {
      const fetchGuestCart = async () => {
        const guestCartStr = localStorage.getItem("guest_cart");
        if (guestCartStr) {
          try {
            const parsed = JSON.parse(guestCartStr) as LocalGuestItem[];
            if (Array.isArray(parsed) && parsed.length > 0) {
              const skuIds = parsed
                .map((p) => p.skuId)
                .filter((id): id is string => !!id);
              const res = await getGuestCartDetailsAction(skuIds);

              if (res.success && res.data) {
                // Check for invalid items (present in local storage but not returned by API)
                const validSkuIds = new Set(res.data.map((sku: Sku) => sku.id));
                const validLocalItems = parsed.filter((p) =>
                  validSkuIds.has(p.skuId)
                );

                if (validLocalItems.length < parsed.length) {
                  // Some items are invalid/inactive/deleted, remove them
                  localStorage.setItem(
                    "guest_cart",
                    JSON.stringify(validLocalItems)
                  );
                  window.dispatchEvent(new Event("guest_cart_updated"));
                }

                let t = 0;
                // Map API response to PopulatedCartItem
                // We use 'any' briefly here because mapping from SkuDetail to PopulatedCartItem is complex to strictly type without mapped types
                // but the result is strongly typed.
                const mappedItems: PopulatedCartItem[] = res.data.map(
                  (sku: Sku) => {
                    const q =
                      parsed.find((p) => p.skuId === sku.id)?.quantity || 1;
                    const price = Number(sku.salePrice || sku.price || 0);
                    t += price * q;

                    // Construct PopulatedCartItem structure from SkuDetail
                    return {
                      id: `guest-${sku.id}`,
                      cartId: "guest",
                      skuId: sku.id,
                      quantity: q,
                      price: price,
                      sku: {
                        ...sku,
                        price: Number(sku.price), // Ensure number
                        salePrice: sku.salePrice ? Number(sku.salePrice) : null,
                        stock: sku.stock,
                        product: sku.product,
                        // Ensure optionValues structure matches what we expect from shared types
                        // API returns: { optionValueId, optionValue: { id, value, option: { name } } }
                        optionValues: (sku.optionValues as any)?.map(
                          (ov: any) => ({
                            optionValueId:
                              ov.optionValueId ||
                              ov.optionValue?.id ||
                              "guest-opt-val",
                            optionValue: {
                              id:
                                ov.optionValue?.id || ov.id || "guest-opt-val",
                              value: ov.optionValue?.value || ov.value || "",
                              option: {
                                name:
                                  ov.optionValue?.option?.name ||
                                  ov.option?.name ||
                                  "Option",
                              },
                            },
                          })
                        ),
                      },
                    } as unknown as PopulatedCartItem;
                  }
                );
                setGuestItems(mappedItems);
                setTotalGuest(t);
              }
            } else {
              setGuestItems([]);
              setTotalGuest(0);
            }
          } catch (e) {
            console.error("Error loading guest cart", e);
          }
        } else {
          setGuestItems([]);
          setTotalGuest(0);
        }
      };

      fetchGuestCart();
      window.addEventListener("guest_cart_updated", fetchGuestCart);
      return () => {
        window.removeEventListener("guest_cart_updated", fetchGuestCart);
      };
    }
  }, [isGuest]);

  // Replace useOptimistic with local state to handle debounce stability
  const [localItems, setLocalItems] = useState<PopulatedCartItem[]>(items);

  const [selectedItems, setSelectedItems] = useState<string[]>([]);
  const [pendingUpdates, setPendingUpdates] = useState<Set<string>>(new Set());

  const isCheckoutBlocked = isPending || pendingUpdates.size > 0;

  // Sync local items with props
  useEffect(() => {
    setLocalItems((prev) => {
      const updatingIds = Object.keys(debouncedUpdateRef.current);
      if (isGuest) return [...items];

      const newItems = items.map((serverItem) => {
        if (updatingIds.includes(serverItem.id)) {
          const local = prev.find((p) => p.id === serverItem.id);
          return local
            ? { ...serverItem, quantity: local.quantity }
            : serverItem;
        }
        return serverItem;
      });
      return newItems;
    });
  }, [items, isGuest]);

  const isFirstRender = useRef(true);
  useEffect(() => {
    if (isFirstRender.current && localItems.length > 0) {
      setSelectedItems(localItems.map((item) => item.id));
      isFirstRender.current = false;
    }
  }, [localItems.length]);

  const toggleSelectItem = useCallback((id: string) => {
    setSelectedItems((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  }, []);

  const handleClearCart = () => {
    startTransition(async () => {
      if (isGuest) {
        localStorage.removeItem("guest_cart");
        setGuestItems([]);
        setTotalGuest(0);
        window.dispatchEvent(new Event("guest_cart_updated"));
      } else {
        const res = await clearCartAction();
        if (res.success) {
          toast({
            variant: "success",
            title: t("cleared"),
            description: t("clearedDesc"),
          });
        }
      }
    });
  };

  const handleRemoveItem = (id: string) => {
    setLocalItems((prev) => prev.filter((i) => i.id !== id));

    startTransition(async () => {
      if (isGuest) {
        const guestCart = JSON.parse(
          localStorage.getItem("guest_cart") || "[]"
        );
        const updatedCart = guestCart.filter(
          (i: LocalGuestItem) => i.skuId !== id.replace("guest-", "")
        );
        localStorage.setItem("guest_cart", JSON.stringify(updatedCart));
        window.dispatchEvent(new Event("guest_cart_updated"));
      } else {
        const res = await removeFromCartAction(id);
        if (res.success) {
          toast({
            variant: "success",
            title: t("removed"),
            description: t("removedDesc"),
          });
        }
      }
    });
  };

  const handleUpdateQuantity = (id: string, quantity: number) => {
    if (quantity < 1) return;

    // Find item to check stock
    const targetItem = localItems.find((i) => i.id === id);
    if (targetItem && quantity > targetItem.sku.stock) {
      toast({
        title: t("updateFailed"),
        description: t("onlyAvailable", { count: targetItem.sku.stock }),
        variant: "warning",
      });
      return;
    }

    setLocalItems((prev) =>
      prev.map((item) => (item.id === id ? { ...item, quantity } : item))
    );

    setPendingUpdates((prev) => {
      const newSet = new Set(prev);
      newSet.add(id);
      return newSet;
    });

    if (debouncedUpdateRef.current[id]) {
      clearTimeout(debouncedUpdateRef.current[id]);
    }

    debouncedUpdateRef.current[id] = setTimeout(() => {
      startTransition(async () => {
        try {
          if (isGuest) {
            const guestCart = JSON.parse(
              localStorage.getItem("guest_cart") || "[]"
            );
            const updatedCart = guestCart.map((item: LocalGuestItem) =>
              item.skuId === id.replace("guest-", "")
                ? { ...item, quantity }
                : item
            );
            localStorage.setItem("guest_cart", JSON.stringify(updatedCart));
            window.dispatchEvent(new Event("guest_cart_updated"));
          } else {
            const res = await updateCartItemAction(id, quantity);
            if (!res.success) {
              const availableStock = (res as { availableStock?: number })
                .availableStock;

              if (typeof availableStock === "number") {
                toast({
                  title: t("updateFailed"),
                  description: `Only ${availableStock} items available. Quantity updated to maximum.`,
                  variant: "warning",
                });
                setLocalItems((prev) =>
                  prev.map((item) =>
                    item.id === id
                      ? { ...item, quantity: availableStock }
                      : item
                  )
                );
                await updateCartItemAction(id, availableStock);
              } else {
                toast({
                  title: t("updateFailed"),
                  description: res.error || t("updateFailedDesc"),
                  variant: "destructive",
                });
                setLocalItems((prev) => {
                  const serverItem = items.find((i) => i.id === id);
                  return prev.map((item) =>
                    item.id === id ? serverItem || item : item
                  );
                });
              }
            }
          }
        } catch (error) {
          console.error("Failed to update cart item", error);
          setLocalItems((prev) => {
            const serverItem = items.find((i) => i.id === id);
            return prev.map((item) =>
              item.id === id ? serverItem || item : item
            );
          });
        } finally {
          setPendingUpdates((prev) => {
            const newSet = new Set(prev);
            newSet.delete(id);
            return newSet;
          });
          delete debouncedUpdateRef.current[id];
        }
      });
    }, 500);
  };

  const shippingThreshold = 2000000;
  const remainingForFreeShipping = Math.max(0, shippingThreshold - total);
  const isFreeShipping = total >= shippingThreshold;

  return (
    <div className="min-h-screen bg-background pt-28 pb-16 font-sans selection:bg-accent/30 relative overflow-hidden">
      <div className="absolute top-0 right-1/4 w-[600px] h-[600px] bg-accent/5 rounded-full blur-[200px] pointer-events-none" />
      <div className="absolute bottom-0 left-1/4 w-[600px] h-[600px] bg-secondary/30 rounded-full blur-[150px] pointer-events-none" />

      <div className="container mx-auto px-4 max-w-6xl relative z-10">
        <motion.div
          className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-10"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <div className="space-y-3">
            <span className="text-[10px] font-medium uppercase tracking-[0.2em] text-accent block">
              Your Selection
            </span>
            <h1 className="text-4xl md:text-5xl font-serif font-normal text-foreground tracking-tight">
              {t("title")}
            </h1>
            <p className="text-muted-foreground text-lg font-light">
              {localItems.length} {t("items")} {t("inCart")}
            </p>
          </div>

          {localItems.length > 0 && (
            <AlertDialog>
              <AlertDialogTrigger asChild>
                <GlassButton
                  variant="ghost"
                  className="text-destructive hover:text-destructive/90 hover:bg-destructive/10"
                >
                  <span className="flex items-center">
                    <Trash2 className="w-4 h-4 mr-2" />
                    {t("clearCart")}
                  </span>
                </GlassButton>
              </AlertDialogTrigger>
              <AlertDialogContent className="bg-background/95 backdrop-blur-xl border-border shadow-2xl">
                <AlertDialogHeader>
                  <AlertDialogTitle>{t("clearConfirmTitle")}</AlertDialogTitle>
                  <AlertDialogDescription className="text-muted-foreground">
                    {t("clearConfirmDesc")}
                  </AlertDialogDescription>
                </AlertDialogHeader>
                <AlertDialogFooter>
                  <AlertDialogCancel className="bg-transparent border border-input text-foreground hover:bg-black/5 hover:text-foreground">
                    {t("cancel")}
                  </AlertDialogCancel>
                  <AlertDialogAction
                    onClick={handleClearCart}
                    className="bg-destructive hover:bg-destructive/90 text-destructive-foreground border-none"
                  >
                    {t("clearCart")}
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>
            </AlertDialog>
          )}
        </motion.div>

        {localItems.length === 0 ? (
          <motion.div
            className="flex flex-col items-center justify-center py-24 px-4 text-center space-y-6 bg-white/5 rounded-3xl border border-white/10 backdrop-blur-sm"
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
          >
            <div className="w-24 h-24 bg-muted rounded-full flex items-center justify-center mb-4">
              <ShoppingBag className="w-12 h-12 text-muted-foreground" />
            </div>
            <div className="space-y-2">
              <h2 className="text-2xl font-bold">{t("empty")}</h2>
              <p className="text-muted-foreground max-w-md mx-auto">
                {t("emptyDesc")}
              </p>
            </div>
            <Link href="/shop">
              <GlassButton
                size="lg"
                className="bg-primary text-primary-foreground font-bold px-8"
              >
                {t("startShopping")}
              </GlassButton>
            </Link>
          </motion.div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
            <div className="lg:col-span-8 space-y-4">
              <GlassCard className="p-6 mb-6 overflow-hidden relative group">
                <div className="flex justify-between items-center mb-4">
                  <div className="flex items-center gap-3">
                    <div className="p-2 bg-success/10 rounded-lg">
                      <Truck className="w-5 h-5 text-success" />
                    </div>
                    <span className="font-medium text-sm md:text-base">
                      {isFreeShipping
                        ? t("freeShippingUnlocked")
                        : t("addForFree", {
                            amount: format.number(remainingForFreeShipping, {
                              style: "currency",
                              currency: "VND",
                            }),
                          })}
                    </span>
                  </div>
                  <span className="text-xs font-bold text-muted-foreground uppercase tracking-wider">
                    {Math.min(
                      100,
                      Math.round((total / shippingThreshold) * 100)
                    )}
                    %
                  </span>
                </div>
                <div className="h-2 bg-white/5 rounded-full overflow-hidden border border-white/5">
                  <motion.div
                    className="h-full bg-linear-to-r from-success to-info"
                    initial={{ width: 0 }}
                    animate={{
                      width: `${Math.min(
                        100,
                        (total / shippingThreshold) * 100
                      )}%`,
                    }}
                    transition={{ duration: 1, ease: "easeOut" }}
                  />
                </div>
              </GlassCard>

              <motion.div
                className="space-y-4"
                variants={containerVariants}
                initial="hidden"
                animate="visible"
              >
                <div className="flex items-center justify-between px-4 py-2 text-sm text-muted-foreground">
                  <div className="flex items-center gap-3">
                    <Checkbox
                      checked={
                        selectedItems.length === localItems.length &&
                        localItems.length > 0
                      }
                      onCheckedChange={() => {
                        if (selectedItems.length === localItems.length) {
                          setSelectedItems([]);
                        } else {
                          setSelectedItems(localItems.map((i) => i.id));
                        }
                      }}
                    />
                    <span className="text-base font-medium">
                      {t("selectAll")}
                    </span>
                  </div>
                </div>

                {localItems.map((item) => (
                  <motion.div key={item.id} variants={itemVariants}>
                    <GlassCard className="p-4 md:p-6 group hover:bg-white/10 transition-all duration-300">
                      <div className="flex gap-4 md:gap-6">
                        <div className="flex items-center">
                          <Checkbox
                            checked={selectedItems.includes(item.id)}
                            onCheckedChange={() => toggleSelectItem(item.id)}
                          />
                        </div>

                        <Link
                          href={`/products/${item.sku.product.id}`}
                          className="relative w-24 h-32 md:w-32 md:h-40 rounded-xl overflow-hidden bg-muted shrink-0 border border-white/5 block group/img"
                        >
                          {item.sku.imageUrl ? (
                            <Image
                              src={item.sku.imageUrl}
                              alt={item.sku.product.name}
                              fill
                              sizes="(max-width: 768px) 96px, 128px"
                              className="object-cover transition-transform duration-500 group-hover/img:scale-110"
                            />
                          ) : item.sku.product.images?.[0] ? (
                            <Image
                              src={item.sku.product.images[0]}
                              alt={item.sku.product.name}
                              fill
                              sizes="(max-width: 768px) 96px, 128px"
                              className="object-cover transition-transform duration-500 group-hover/img:scale-110"
                            />
                          ) : (
                            <Image
                              src={`https://picsum.photos/seed/${
                                item.sku.product.id || "fallback"
                              }/400/600`}
                              alt={item.sku.product.name}
                              fill
                              sizes="(max-width: 768px) 96px, 128px"
                              className="object-cover transition-transform duration-500 group-hover/img:scale-110"
                            />
                          )}
                        </Link>

                        <div className="flex-1 flex flex-col justify-between py-1">
                          <div className="space-y-1">
                            <div className="flex justify-between items-start gap-4">
                              <Link
                                href={`/products/${item.sku.product.id}`}
                                className="font-bold text-lg md:text-xl hover:text-primary transition-colors line-clamp-2"
                              >
                                {item.sku.product.name}
                              </Link>
                              <button
                                onClick={() => handleRemoveItem(item.id)}
                                className="text-muted-foreground hover:text-destructive transition-colors p-1"
                              >
                                <X size={20} />
                              </button>
                            </div>

                            <div className="flex flex-wrap gap-2 mt-2">
                              {item.sku.optionValues?.map((ov) => (
                                <span
                                  key={ov.optionValue.id}
                                  className="px-2 py-0.5 rounded-md bg-white/5 border border-white/10 text-[10px] md:text-xs font-medium text-muted-foreground"
                                >
                                  {ov.optionValue.option.name}:{" "}
                                  {ov.optionValue.value}
                                </span>
                              ))}
                            </div>
                          </div>

                          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mt-4">
                            <div className="flex items-center bg-black/20 rounded-full border border-white/10 p-1 w-fit">
                              <button
                                onClick={() =>
                                  handleUpdateQuantity(
                                    item.id,
                                    item.quantity - 1
                                  )
                                }
                                disabled={item.quantity <= 1 || isPending}
                                className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white/10 disabled:opacity-30 transition-colors"
                              >
                                <Minus size={14} />
                              </button>
                              <span className="w-10 text-center font-bold text-sm">
                                {item.quantity}
                              </span>
                              <button
                                onClick={() =>
                                  handleUpdateQuantity(
                                    item.id,
                                    item.quantity + 1
                                  )
                                }
                                disabled={
                                  isPending || item.quantity >= item.sku.stock
                                }
                                className="w-8 h-8 flex items-center justify-center rounded-full hover:bg-white/10 transition-colors"
                              >
                                <Plus size={14} />
                              </button>
                            </div>

                            <div className="text-right">
                              <p className="text-xl font-bold text-primary">
                                {format.number(
                                  Number(item.sku.salePrice || item.sku.price) *
                                    item.quantity,
                                  {
                                    style: "currency",
                                    currency: "VND",
                                  }
                                )}
                              </p>
                              {item.sku.salePrice && (
                                <p className="text-xs text-muted-foreground line-through">
                                  {format.number(
                                    Number(item.sku.price) * item.quantity,
                                    {
                                      style: "currency",
                                      currency: "VND",
                                    }
                                  )}
                                </p>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    </GlassCard>
                  </motion.div>
                ))}
              </motion.div>
            </div>

            <div className="lg:col-span-4 space-y-6">
              <GlassCard className="p-6 md:p-8 sticky top-24">
                <h2 className="text-2xl font-bold mb-6">{t("orderSummary")}</h2>
                <div className="space-y-4 mb-8">
                  <div className="flex justify-between text-muted-foreground">
                    <span>{t("subtotal")}</span>
                    <span className="font-medium text-foreground">
                      {format.number(total, {
                        style: "currency",
                        currency: "VND",
                      })}
                    </span>
                  </div>
                  <div className="flex justify-between text-muted-foreground">
                    <span>{t("shipping")}</span>
                    <span className="text-success font-medium">
                      {isFreeShipping ? t("free") : t("calculatedAtCheckout")}
                    </span>
                  </div>
                  <Separator className="bg-white/10" />
                  <div className="flex justify-between items-end">
                    <span className="text-lg font-bold">{t("total")}</span>
                    <div className="text-right">
                      <p className="text-3xl font-black text-primary tracking-tight">
                        {format.number(total, {
                          style: "currency",
                          currency: "VND",
                        })}
                      </p>
                    </div>
                  </div>
                </div>

                <div className="space-y-3">
                  {isGuest ? (
                    <Link
                      href={`/login?callbackUrl=${encodeURIComponent(
                        `/checkout${
                          selectedItems.length > 0
                            ? `?items=${selectedItems
                                .map((id) => id.replace("guest-", ""))
                                .join(",")}`
                            : ""
                        }`
                      )}`}
                    >
                      <GlassButton
                        className="w-full bg-primary text-primary-foreground font-bold py-6 rounded-2xl shadow-xl shadow-primary/20"
                        size="lg"
                      >
                        {t("loginToCheckout")}
                      </GlassButton>
                    </Link>
                  ) : (
                    <Link
                      href={
                        selectedItems.length > 0 && !isCheckoutBlocked
                          ? `/checkout?items=${selectedItems.join(",")}`
                          : "#"
                      }
                      onClick={(e) => isCheckoutBlocked && e.preventDefault()}
                    >
                      <GlassButton
                        className="w-full bg-primary text-primary-foreground font-bold py-6 rounded-2xl shadow-xl shadow-primary/20"
                        size="lg"
                        disabled={
                          localItems.length === 0 ||
                          selectedItems.length === 0 ||
                          isCheckoutBlocked
                        }
                      >
                        {isCheckoutBlocked ? (
                          <RefreshCcw className="w-5 h-5 mr-3 animate-spin" />
                        ) : (
                          <Lock className="w-5 h-5 mr-3" />
                        )}
                        {isCheckoutBlocked
                          ? t("checkingStock")
                          : t("secureCheckout")}
                      </GlassButton>
                    </Link>
                  )}
                  <div className="pt-4 space-y-3">
                    <div className="flex items-center gap-3 text-xs text-muted-foreground">
                      <ShieldCheck className="w-4 h-4 text-success" />
                      <span>{t("securePayments")}</span>
                    </div>
                    <div className="flex items-center gap-3 text-xs text-muted-foreground">
                      <RefreshCcw className="w-4 h-4 text-info" />
                      <span>{t("freeReturns")}</span>
                    </div>
                    <div className="flex items-center gap-3 text-xs text-muted-foreground">
                      <Truck className="w-4 h-4 text-primary" />
                      <span>{t("fastShipping")}</span>
                    </div>
                  </div>
                </div>
              </GlassCard>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { Button } from "@/components/atoms/button";
import Link from "next/link";
import { useTransition } from "react";

/**
 * =====================================================================
 * CHECKOUT BUTTON - Nút thanh toán thông minh
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. SELECTIVE CHECKOUT:
 * - User có thể chọn chỉ thanh toán một vài món trong giỏ hàng.
 * - Danh sách `itemIds` được truyền qua URL query params (`?items=id1,id2`).
 *
 * 2. DYNAMIC URL:
 * - Nếu không chọn món nào, nút sẽ bị disable.
 * - URL được sinh động dựa trên mảng `itemIds`.
 * =====================================================================
 */

export function CheckoutButton({ itemIds }: { itemIds: string[] }) {
  const [isPending] = useTransition();

  const checkoutUrl =
    itemIds.length > 0 ? `/checkout?items=${itemIds.join(",")}` : "/checkout";

  return (
    <Link href={checkoutUrl as any} className="w-full">
      <Button
        className="w-full bg-linear-to-r from-success to-success/80 hover:from-success/90 hover:to-success text-success-foreground font-semibold shadow-lg shadow-success/20"
        size="lg"
        disabled={isPending || itemIds.length === 0}
      >
        Checkout ({itemIds.length})
      </Button>
    </Link>
  );
}

/**
 * =====================================================================
 * CHECKOUT CLIENT - Giao diện thanh toán tập trung
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. COMPONENT DECOMPOSITION:
 * - Form thanh toán rất phức tạp nên được chia nhỏ thành các component:
 *   - `AddressSelector`: Chọn/Thêm địa chỉ giao hàng.
 *   - `PaymentMethodSelector`: Chọn phương thức thanh toán (COD, VNPAY...).
 *   - `CouponInput`: Nhập và kiểm tra mã giảm giá.
 *   - `OrderSummary`: Hiển thị tổng tiền và nút đặt hàng.
 *
 * 2. DYNAMIC CALCULATIONS:
 * - `shippingFee`: Tự động tính toán lại khi user thay đổi địa chỉ (gọi `calculateShippingFeeAction`).
 * - `discount`: Cập nhật khi áp dụng mã giảm giá thành công.
 * - `subtotal`: Tổng tiền hàng (có thể chỉ tính cho các món được chọn từ giỏ hàng).
 *
 * 3. ORDER FLOW:
 * - Khi nhấn đặt hàng, `placeOrderAction` được gọi.
 * - Nếu là VNPAY, sẽ redirect user sang trang thanh toán của ngân hàng.
 * =====================================================================
 */

"use client";

import { validateCouponAction } from "@/actions/coupon";
import { placeOrderAction } from "@/actions/order";
import { calculateShippingFeeAction } from "@/actions/shipping";
import { GlassButton } from "@/components/atoms/glass-button";
// import { AddAddressDialog } from "@/components/organisms/admin/add-address-dialog"; // Replaced with dynamic import
import { AddressSelector } from "@/components/organisms/checkout/address-selector";
import { CouponInput } from "@/components/organisms/checkout/coupon-input";
import { OrderSummary } from "@/components/organisms/checkout/order-summary";
import {
  PaymentMethodSelector,
  PaymentMethodType,
} from "@/components/organisms/checkout/payment-method-selector";
import { useToast } from "@/hooks/use-toast";
import { Link, useRouter } from "@/i18n/routing";
import { formatCurrency } from "@/lib/utils";
import { Address, Cart, CartItem, Coupon } from "@/types/models";
import { motion } from "framer-motion";
import { ArrowLeft, Lock, ShieldCheck } from "lucide-react";
import { useTranslations } from "next-intl";
import dynamic from "next/dynamic";
import { useSearchParams } from "next/navigation";
import { useEffect, useMemo, useState, useTransition } from "react";

const AddAddressDialog = dynamic(
  () =>
    import("@/components/organisms/admin/add-address-dialog").then(
      (m) => m.AddAddressDialog
    ),
  { ssr: false }
);

interface CheckoutClientProps {
  cart: Cart | null;
  addresses: Address[];
}

export function CheckoutClient({ cart, addresses = [] }: CheckoutClientProps) {
  const t = useTranslations("checkout");
  const tCommon = useTranslations("common");
  const router = useRouter();
  const { toast } = useToast();
  const searchParams = useSearchParams();
  const [isPending, startTransition] = useTransition();

  // State
  const [couponCode, setCouponCode] = useState("");
  const [appliedCoupon, setAppliedCoupon] = useState<{
    code: string;
    discount: number;
  } | null>(null);
  const [couponError, setCouponError] = useState("");
  const [isValidatingCoupon, setIsValidatingCoupon] = useState(false);
  const [availableCoupons, setAvailableCoupons] = useState<Coupon[]>([]);

  const [paymentMethod, setPaymentMethod] = useState<PaymentMethodType>("COD");
  const [selectedAddressId, setSelectedAddressId] = useState<string>(
    addresses.find((a) => a.isDefault)?.id || addresses[0]?.id || ""
  );
  const [shippingFee, setShippingFee] = useState(0);
  const [isCalculatingFee, setIsCalculatingFee] = useState(false);
  const [isAddAddressOpen, setIsAddAddressOpen] = useState(false);
  const [editingAddress, setEditingAddress] = useState<Address | null>(null);

  // Derived State
  const itemIdsParam = searchParams.get("items");
  const selectedItemIds = useMemo(
    () => (itemIdsParam ? itemIdsParam.split(",") : []),
    [itemIdsParam]
  );

  const selectedAddress = useMemo(
    () => addresses.find((a) => a.id === selectedAddressId),
    [addresses, selectedAddressId]
  );

  const allItems = useMemo(
    () => (cart?.items || []) as unknown as CartItem[],
    [cart]
  );

  const items = useMemo(
    () =>
      selectedItemIds.length > 0
        ? allItems.filter(
            (item) =>
              selectedItemIds.includes(item.id) ||
              (item.skuId && selectedItemIds.includes(item.skuId)) ||
              (item.sku?.id && selectedItemIds.includes(item.sku.id))
          )
        : allItems,
    [allItems, selectedItemIds]
  );

  const subtotal = useMemo(
    () =>
      items.reduce(
        (sum, item) =>
          sum +
          Number(item.sku?.salePrice || item.sku?.price || 0) * item.quantity,
        0
      ),
    [items]
  );

  const discount = appliedCoupon?.discount || 0;
  const total = useMemo(
    () => Math.max(0, subtotal + shippingFee - discount),
    [subtotal, shippingFee, discount]
  );

  // Effects
  useEffect(() => {
    const fetchCoupons = async () => {
      try {
        // Dynamically import to avoid server-side issues if any
        const { http } = await import("@/lib/http");
        const res = await http<Coupon[] | { data: Coupon[] }>(
          "/coupons/available",
          {
            skipAuth: true,
          }
        );
        const list = Array.isArray(res)
          ? res
          : res?.data && Array.isArray(res.data)
          ? res.data
          : [];
        setAvailableCoupons(list);
      } catch (e) {
        console.error("Failed to fetch coupons", e);
      }
    };
    fetchCoupons();
  }, []);

  useEffect(() => {
    const fetchFee = async () => {
      if (
        selectedAddress &&
        selectedAddress.districtId &&
        selectedAddress.wardCode
      ) {
        setIsCalculatingFee(true);
        try {
          const fee = await calculateShippingFeeAction(
            Number(selectedAddress.districtId),
            selectedAddress.wardCode
          );
          setShippingFee(fee);
        } finally {
          setIsCalculatingFee(false);
        }
      } else {
        setShippingFee(0);
        setIsCalculatingFee(false);
      }
    };
    fetchFee();
  }, [selectedAddress]);

  // Handlers
  const handleApplyCoupon = async (code?: string) => {
    const targetCode = code || couponCode;
    if (!targetCode.trim()) return;

    setIsValidatingCoupon(true);
    setCouponError("");

    try {
      const res = await validateCouponAction(targetCode, subtotal);

      if (res.success) {
        if (res.isValid) {
          setAppliedCoupon({
            code: targetCode,
            discount: res.discountAmount || 0,
          });
          toast({
            title: t("couponApplied"),
            description: tCommon("toast.success"),
            variant: "success",
          });
        } else {
          setCouponError(res.message || t("couponInvalid"));
          setAppliedCoupon(null);
        }
      } else {
        setCouponError(res.error || t("couponInvalid"));
        setAppliedCoupon(null);
      }
    } catch (error) {
      setCouponError("Failed to validate coupon");
    } finally {
      setIsValidatingCoupon(false);
    }
  };

  const handlePlaceOrder = () => {
    if (!selectedAddress) {
      toast({
        title: t("missingInfo"),
        description: t("selectAddress"),
        variant: "destructive",
      });
      return;
    }

    startTransition(async () => {
      const addressString = `${selectedAddress.street}, ${
        selectedAddress.ward || ""
      }, ${selectedAddress.district}, ${selectedAddress.city}`;

      const res = await placeOrderAction({
        recipientName: selectedAddress.recipientName,
        phoneNumber: selectedAddress.phoneNumber,
        shippingAddress: addressString, // Changed from address to shippingAddress
        addressId: selectedAddress.id,
        paymentMethod: paymentMethod,
        itemIds: items.map((i) => i.id),
        couponCode: appliedCoupon?.code,
      });

      if (res && "success" in res) {
        if (res.paymentUrl) {
          window.location.href = res.paymentUrl;
          return;
        }
        // Dispatch event to refresh cart count immediately
        window.dispatchEvent(new Event("cart_updated"));

        toast({
          title: t("success"),
          description: t("successDesc"),
          variant: "success",
        });
        router.push("/orders");
      } else {
        toast({
          title: t("failed"),
          description: res && "error" in res ? res.error : t("error"),
          variant: "destructive",
        });
      }
    });
  };

  const handleEditAddress = (address: Address) => {
    setEditingAddress(address);
    setIsAddAddressOpen(true);
  };

  const sectionVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.7 } },
  };

  return (
    <div className="min-h-screen bg-background pt-24 pb-12 font-sans selection:bg-primary/30 relative overflow-hidden">
      {/* Background Gradients */}
      <div className="absolute top-0 right-1/4 w-[600px] h-[600px] bg-success/10 rounded-full blur-[150px] pointer-events-none" />
      <div className="absolute bottom-0 left-1/4 w-[600px] h-[600px] bg-info/10 rounded-full blur-[150px] pointer-events-none" />

      <div className="container mx-auto px-4 max-w-6xl relative z-10">
        <div className="mb-6">
          <Link
            href="/cart"
            className="inline-flex items-center gap-2 text-muted-foreground hover:text-primary transition-colors font-medium"
          >
            <ArrowLeft size={20} />
            <span>{t("backToCart")}</span>
          </Link>
        </div>

        <motion.div
          className="text-center mb-10"
          initial="hidden"
          animate="visible"
          variants={sectionVariants}
        >
          <div className="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-success/10 border border-success/20 mb-4">
            <Lock className="w-4 h-4 text-success" />
            <span className="text-sm text-success font-medium">
              {t("secureCheckout")}
            </span>
          </div>
          <h1 className="text-3xl md:text-4xl font-bold text-foreground tracking-tight">
            {t("title")}
          </h1>
        </motion.div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          {/* Main Form */}
          <div className="lg:col-span-8 space-y-6">
            <AddressSelector
              addresses={addresses}
              selectedAddressId={selectedAddressId}
              onSelect={setSelectedAddressId}
              onAddNew={() => {
                setEditingAddress(null);
                setIsAddAddressOpen(true);
              }}
              onEdit={handleEditAddress}
            />

            <PaymentMethodSelector
              method={paymentMethod}
              onChange={setPaymentMethod}
            />
          </div>

          {/* Sidebar */}
          <div className="lg:col-span-4 space-y-6">
            <OrderSummary
              items={items}
              subtotal={subtotal}
              shippingFee={shippingFee}
              discount={discount}
              total={total}
              isLoadingFee={isCalculatingFee}
              couponSlot={
                <CouponInput
                  couponCode={couponCode}
                  onCodeChange={setCouponCode}
                  availableCoupons={availableCoupons}
                  appliedCoupon={appliedCoupon}
                  isValidating={isValidatingCoupon}
                  onApply={handleApplyCoupon}
                  onRemove={() => {
                    setAppliedCoupon(null);
                    setCouponCode("");
                    setCouponError("");
                  }}
                  error={couponError}
                  formatMoney={formatCurrency}
                />
              }
              actionSlot={
                <GlassButton
                  className="w-full bg-linear-to-r from-success to-success/80 font-bold text-white shadow-lg shadow-success/20"
                  size="lg"
                  onClick={handlePlaceOrder}
                  disabled={isPending || !cart || items.length === 0}
                >
                  {isPending
                    ? t("processing")
                    : t("completeOrderWithTotal", {
                        total: formatCurrency(total),
                      })}
                </GlassButton>
              }
              footerSlot={
                <div className="flex items-center gap-2 text-xs text-muted-foreground">
                  <ShieldCheck className="w-4 h-4 text-success" />
                  <span>{t("secureTransaction")}</span>
                </div>
              }
            />
          </div>
        </div>
      </div>

      <AddAddressDialog
        open={isAddAddressOpen}
        onOpenChange={(open) => {
          setIsAddAddressOpen(open);
          if (!open) setEditingAddress(null);
        }}
        onSuccess={() => {
          router.refresh();
        }}
        address={editingAddress}
      />
    </div>
  );
}

