/**
 * =====================================================================
 * WISHLIST CLIENT - Giao diện danh sách yêu thích
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. HYBRID WISHLIST LOGIC (User & Guest):
 * - Nếu user đã đăng nhập: Dữ liệu lấy từ `wishlistItems` prop (Server Action).
 * - Nếu là khách (Guest): Dữ liệu lấy từ `localStorage` thông qua `useGuestWishlist` hook.
 * - `useEffect` xử lý việc fetch chi tiết sản phẩm cho Guest từ danh sách ID trong localStorage.
 *
 * 2. COMPONENT COMPOSITION:
 * - Sử dụng `ProductCard` để hiển thị từng sản phẩm trong danh sách yêu thích.
 * - Đảm bảo truyền đúng các props như `initialIsWishlisted={true}` để icon trái tim hiển thị đúng trạng thái.
 *
 * 3. EMPTY STATE:
 * - Hiển thị thông báo khi danh sách trống để khuyến khích người dùng khám phá cửa hàng.
 * =====================================================================
 */

"use client";

import { getGuestWishlistDetailsAction } from "@/actions/wishlist";
import { GlassButton } from "@/components/atoms/glass-button";
import { ProductCard } from "@/components/organisms/product-card";
import { useGuestWishlist } from "@/hooks/use-guest-wishlist";
import { Link } from "@/i18n/routing";
import { useAuth } from "@/providers/auth-provider";
import { motion } from "framer-motion";
import { Heart } from "lucide-react";
import { useTranslations } from "next-intl";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";

import { Product } from "@/types/models";

interface WishlistItem {
  id: string;
  product: Product;
}

interface WishlistClientProps {
  wishlistItems: WishlistItem[];
}

export function WishlistClient({
  wishlistItems: initialItems,
}: WishlistClientProps) {
  const t = useTranslations("wishlist");
  const { isAuthenticated } = useAuth();
  const guestWishlist = useGuestWishlist();
  const [items, setItems] = useState<WishlistItem[]>(initialItems || []);

  const router = useRouter();

  useEffect(() => {
    const handleWishlistUpdate = () => {
      router.refresh();
    };

    window.addEventListener("wishlist_updated", handleWishlistUpdate);
    return () => {
      window.removeEventListener("wishlist_updated", handleWishlistUpdate);
    };
  }, [router]);

  useEffect(() => {
    // If authenticated, we trust server items (initialItems)
    if (isAuthenticated) {
      setItems(initialItems || []);
      return;
    }

    // If guest, we fetch from localStorage IDs
    const fetchGuestProducts = async () => {
      if (guestWishlist.wishlistIds.length === 0) {
        setItems([]);
        return;
      }

      try {
        const res = await getGuestWishlistDetailsAction(
          guestWishlist.wishlistIds
        );
        if (res.success && res.data) {
          // Map to wishlist format { id, product: ... }
          const mappedItems = res.data.map((p: Product) => ({
            id: p.id, // Wishlist item ID (virtual)
            product: p,
          }));
          setItems(mappedItems);
        }
      } catch (e) {
        console.error("Failed to fetch guest wishlist", e);
      }
    };

    fetchGuestProducts();
  }, [isAuthenticated, initialItems, guestWishlist.wishlistIds]);

  const sectionVariants = {
    hidden: { opacity: 0, y: 20 },
    visible: { opacity: 1, y: 0, transition: { duration: 0.7 } },
  };

  return (
    <div className="min-h-screen bg-background font-sans selection:bg-primary/30 pt-24 pb-24 relative overflow-hidden">
      <div className="absolute top-0 right-1/4 w-[600px] h-[600px] bg-pink-500/10 rounded-full blur-[150px] pointer-events-none" />
      <div className="absolute bottom-0 left-1/4 w-[600px] h-[600px] bg-purple-500/10 rounded-full blur-[150px] pointer-events-none" />
      <div className="container mx-auto px-4 max-w-6xl relative z-10">
        <motion.div
          className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-10"
          initial="hidden"
          animate="visible"
          variants={sectionVariants}
        >
          <div className="space-y-2">
            <h1 className="text-4xl md:text-5xl font-bold text-foreground tracking-tight">
              {t("title")}
            </h1>
            <p className="text-muted-foreground text-lg">
              {t("subtitle", { count: items.length })}
            </p>
          </div>
        </motion.div>

        <div>
          {items.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {items
                .filter((item) => item.product)
                .map((item) => {
                  const defaultSku = item.product.skus?.[0];
                  // Safeguard against missing price data
                  const price = defaultSku?.price
                    ? Number(defaultSku.price)
                    : 0;
                  const salePrice = defaultSku?.salePrice
                    ? Number(defaultSku.salePrice)
                    : undefined;

                  const reviewCount =
                    item.product._count?.reviews ||
                    item.product.reviews?.length ||
                    0;
                  const averageRating =
                    (item.product.reviews?.length ?? 0) > 0
                      ? item.product.reviews!.reduce(
                          (acc: number, r: { rating: number }) =>
                            acc + r.rating,
                          0
                        ) / item.product.reviews!.length
                      : 5;

                  return (
                    <div key={item.id} className="min-h-[400px] flex flex-col">
                      <ProductCard
                        id={item.product.id}
                        name={item.product.name}
                        price={price}
                        originalPrice={salePrice}
                        imageUrl={
                          (typeof item.product.images?.[0] === "string"
                            ? item.product.images?.[0]
                            : item.product.images?.[0]?.url) ||
                          item.product.skus?.[0]?.imageUrl ||
                          ""
                        }
                        category={item.product.category?.name}
                        skus={item.product.skus}
                        options={item.product.options}
                        rating={averageRating}
                        reviewCount={reviewCount}
                        initialIsWishlisted={true}
                      />
                    </div>
                  );
                })}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-24 px-4 text-center space-y-6 bg-white/5 rounded-3xl border border-white/10 backdrop-blur-sm">
              <div className="w-24 h-24 bg-muted rounded-full flex items-center justify-center mb-4">
                <Heart className="w-12 h-12 text-muted-foreground" />
              </div>
              <div className="space-y-2">
                <h2 className="text-2xl font-bold">{t("empty")}</h2>
                <p className="text-muted-foreground max-w-md mx-auto">
                  {t("emptyDesc")}
                </p>
              </div>
              <Link href="/shop">
                <GlassButton
                  size="lg"
                  className="bg-primary text-primary-foreground font-bold px-8"
                >
                  {t("browseShop")}
                </GlassButton>
              </Link>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

"use client";

import { Badge } from "@/components/atoms/badge";
import { Button } from "@/components/atoms/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/atoms/dialog";
import { GlassCard } from "@/components/atoms/glass-card";
import { Input } from "@/components/atoms/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/atoms/table";
import { useDebounce } from "@/hooks/use-debounce";
import { useRouter } from "@/i18n/routing";
import { useAuth } from "@/providers/auth-provider";
import { Info, Search } from "lucide-react";
import { useTranslations } from "next-intl";
import { useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";

export function AuditLogsClient({
  logs,
  total,
  page,
  limit,
}: {
  logs: Record<string, any>[];
  total: number;
  page: number;
  limit: number;
}) {
  const t = useTranslations("admin");
  const { hasPermission } = useAuth();
  const router = useRouter();
  const searchParams = useSearchParams();

  const canRead = hasPermission("audit:read");

  const [searchTerm, setSearchTerm] = useState(
    searchParams.get("search") || ""
  );
  const debouncedSearchTerm = useDebounce(searchTerm, 500);

  const [selectedLog, setSelectedLog] = useState<Record<string, any> | null>(
    null
  );

  useEffect(() => {
    const params = new URLSearchParams(searchParams.toString());
    if (debouncedSearchTerm) {
      params.set("search", debouncedSearchTerm);
    } else {
      params.delete("search");
    }
    params.set("page", "1");
    router.push(`/admin/audit-logs?${params.toString()}`);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [debouncedSearchTerm]); // Only trigger on search term change

  const totalPages = Math.ceil(total / limit);

  const getActionColor = (action: string) => {
    if (action.includes("create"))
      return "bg-green-100 text-green-700 border-green-200";
    if (action.includes("update") || action.includes("patch"))
      return "bg-blue-100 text-blue-700 border-blue-200";
    if (action.includes("delete"))
      return "bg-red-100 text-red-700 border-red-200";
    return "bg-gray-100 text-gray-700 border-gray-200";
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">{t("audit.management")}</h1>
          <p className="text-sm text-gray-400 mt-1">
            {t("showing", {
              count: logs.length,
              total,
              item: t("audit.title").toLowerCase(),
            })}
          </p>
        </div>
      </div>

      <div className="flex items-center space-x-2">
        <div className="relative max-w-sm w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-gray-500" />
          <Input
            placeholder={t("audit.searchPlaceholder")}
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10"
          />
        </div>
      </div>

      <GlassCard className="p-6">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>{t("audit.date")}</TableHead>
              <TableHead>{t("audit.user")}</TableHead>
              <TableHead>{t("audit.action")}</TableHead>
              <TableHead>{t("audit.resource")}</TableHead>
              <TableHead>{t("audit.ipAddress")}</TableHead>
              {canRead && (
                <TableHead className="text-right">{t("actions")}</TableHead>
              )}
            </TableRow>
          </TableHeader>
          <TableBody>
            {logs.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={canRead ? 6 : 5}
                  className="text-center py-8 text-muted-foreground"
                >
                  {t("audit.noFound")}
                </TableCell>
              </TableRow>
            ) : (
              logs.map((log) => (
                <TableRow key={log.id}>
                  <TableCell className="text-sm font-mono whitespace-nowrap">
                    {new Date(log.createdAt).toLocaleString()}
                  </TableCell>
                  <TableCell>
                    {log.user ? (
                      <div className="flex flex-col">
                        <span className="font-medium">
                          {log.user.firstName} {log.user.lastName}
                        </span>
                        <span className="text-xs text-gray-500">
                          {log.user.email}
                        </span>
                      </div>
                    ) : (
                      <span className="text-gray-400 italic">
                        System / Anon
                      </span>
                    )}
                  </TableCell>
                  <TableCell>
                    <Badge
                      variant="outline"
                      className={getActionColor(log.action.toLowerCase())}
                    >
                      {log.action}
                    </Badge>
                  </TableCell>
                  <TableCell className="capitalize">{log.resource}</TableCell>
                  <TableCell className="text-xs text-gray-500 font-mono">
                    {log.ipAddress || "N/A"}
                  </TableCell>
                  {canRead && (
                    <TableCell className="text-right">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setSelectedLog(log)}
                      >
                        <Info className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  )}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>

        {totalPages > 1 && (
          <div className="mt-4 flex justify-between items-center">
            <p className="text-sm text-gray-400">
              {t("pagination.page", { current: page, total: totalPages })}
            </p>
            <div className="flex space-x-2">
              <Button
                variant="outline"
                size="sm"
                disabled={page <= 1}
                onClick={() => {
                  const params = new URLSearchParams(searchParams.toString());
                  params.set("page", (page - 1).toString());
                  router.push(`/admin/audit-logs?${params.toString()}`);
                }}
              >
                {t("pagination.previous")}
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={page >= totalPages}
                onClick={() => {
                  const params = new URLSearchParams(searchParams.toString());
                  params.set("page", (page + 1).toString());
                  router.push(`/admin/audit-logs?${params.toString()}`);
                }}
              >
                {t("pagination.next")}
              </Button>
            </div>
          </div>
        )}
      </GlassCard>

      <Dialog open={!!selectedLog} onOpenChange={() => setSelectedLog(null)}>
        <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{t("audit.details")}</DialogTitle>
          </DialogHeader>
          {selectedLog && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <p className="text-gray-400">{t("audit.date")}</p>
                  <p className="font-medium">
                    {new Date(selectedLog.createdAt).toLocaleString()}
                  </p>
                </div>
                <div>
                  <p className="text-gray-400">{t("audit.user")}</p>
                  <p className="font-medium">
                    {selectedLog.user
                      ? `${selectedLog.user.firstName} ${selectedLog.user.lastName}`
                      : "System"}
                  </p>
                </div>
                <div>
                  <p className="text-gray-400">{t("audit.action")}</p>
                  <p className="font-medium">{selectedLog.action}</p>
                </div>
                <div>
                  <p className="text-gray-400">{t("audit.resource")}</p>
                  <p className="font-medium capitalize">
                    {selectedLog.resource}
                  </p>
                </div>
              </div>

              <div>
                <p className="text-gray-400 text-sm mb-2">Payload / Changes</p>
                <div className="bg-slate-950 p-4 rounded-lg overflow-x-auto">
                  <pre className="text-xs text-green-400">
                    {JSON.stringify(selectedLog.payload, null, 2)}
                  </pre>
                </div>
              </div>

              {selectedLog.userAgent && (
                <div>
                  <p className="text-gray-400 text-sm mb-1">User Agent</p>
                  <p className="text-xs font-mono text-gray-500 break-all">
                    {selectedLog.userAgent}
                  </p>
                </div>
              )}
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { getAuditLogsAction } from "@/actions/admin";
import { AuditLogsClient } from "./audit-logs-client";

export default async function AuditLogsPage({
  searchParams,
}: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  const params = await searchParams;
  const page = Number(params?.page) || 1;
  const search = (params?.search as string) || "";

  const response = await getAuditLogsAction(page, 20, search);

  if ("error" in response) {
    return (
      <div className="flex items-center justify-center h-[50vh]">
        <div className="max-w-md w-full p-6 bg-destructive/10 border border-destructive/20 rounded-lg text-center space-y-2">
          <h3 className="font-semibold text-destructive text-lg">
            Access Denied
          </h3>
          <p className="text-sm text-muted-foreground">
            {response.error === "Forbidden"
              ? "You do not have permission to view audit logs."
              : response.error}
          </p>
        </div>
      </div>
    );
  }

  const logs = response.data || [];
  const total = response.meta?.total || 0;

  return (
    <AuditLogsClient
      logs={logs as any[]}
      total={total}
      page={page}
      limit={20}
    />
  );
}

"use client";

import { getProductsAction } from "@/actions/admin";
import { createBlogAction, updateBlogAction } from "@/actions/blog";
import { Checkbox } from "@/components/atoms/checkbox";
import { FormDialog } from "@/components/atoms/form-dialog";
import { ImageUpload } from "@/components/atoms/image-upload";
import { Input } from "@/components/atoms/input";
import { Label } from "@/components/atoms/label";
import { ScrollArea } from "@/components/atoms/scroll-area";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/atoms/select";
import { Textarea } from "@/components/atoms/textarea";
import { LazyRichTextEditor as RichTextEditor } from "@/components/molecules/lazy-rich-text-editor";
import { useToast } from "@/hooks/use-toast";
import { BlogWithProducts, Category, Product } from "@/types/models";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslations } from "next-intl";
