  });

  const [imageFile, setImageFile] = useState<File | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [products, setProducts] = useState<Product[]>([]);

  useEffect(() => {
    const fetchProducts = async () => {
      const response = await getProductsAction(1, 100);
      if ("data" in response) {
        setProducts(response.data || []);
      }
    };
    if (open) {
      fetchProducts();
    }
  }, [open]);

  useEffect(() => {
    if (open) {
      if (blog) {
        setFormData({
          title: blog.title,
          slug: blog.slug,
          excerpt: blog.excerpt,
          content: blog.content,
          category: blog.category,
          author: blog.author,
          language: blog.language,
          readTime: blog.readTime ? blog.readTime.replace(/[^0-9]/g, "") : "",
          image: blog.image || "",
          productIds: blog.products?.map((p) => p.id) || [],
        });
      } else {
        setFormData({
          title: "",
          slug: "",
          excerpt: "",
          content: "",
          category: categories[0]?.name || "",
          author: "",
          language: "en",
          readTime: "",
          image: "",
          productIds: [],
        });
      }
      setImageFile(null);
      setErrors({});
    }
  }, [blog, open, categories]);

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.title)
      newErrors.title = t("titleRequired") || "Title is required";
    if (!formData.slug)
      newErrors.slug = t("slugRequired") || "Slug is required";
    if (!formData.excerpt)
      newErrors.excerpt = t("excerptRequired") || "Excerpt is required";
    if (!formData.content || formData.content === "<p></p>")
      newErrors.content = t("contentRequired") || "Content is required";
    if (!formData.category)
      newErrors.category = t("categoryRequired") || "Category is required";
    if (!formData.author)
      newErrors.author = t("authorRequired") || "Author is required";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) return;

    startTransition(async () => {
      let data: any;

      if (imageFile) {
        const formDataToSend = new FormData();
        formDataToSend.append("title", formData.title);
        formDataToSend.append("slug", formData.slug);
        formDataToSend.append("excerpt", formData.excerpt);
        formDataToSend.append("content", formData.content);
        formDataToSend.append("category", formData.category);
        formDataToSend.append("author", formData.author);
        formDataToSend.append("language", formData.language);
        formDataToSend.append(
          "readTime",
          formData.readTime ? `${formData.readTime} min read` : ""
        );
        formDataToSend.append("image", imageFile);
        formData.productIds.forEach((id) =>
          formDataToSend.append("productIds[]", id)
        );
        data = formDataToSend;
      } else {
        data = {
          ...formData,
          readTime: formData.readTime ? `${formData.readTime} min read` : "",
        };
      }

      const result = isEditing
        ? await updateBlogAction(blog.id, data)
        : await createBlogAction(data);

      if (result.success) {
        toast({
          variant: "success",
          title: t(isEditing ? "updated" : "created"),
          description: t(isEditing ? "updateSuccess" : "createSuccess"),
        });
        onOpenChange(false);
      } else {
        toast({
          title: t("error"),
          description: result.error || t("errorMessage"),
          variant: "destructive",
        });
      }
    });
  };

  const generateSlug = (title: string) => {
    return title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/(^-|-$)/g, "");
  };

  const toggleProduct = (productId: string) => {
    setFormData((prev) => ({
      ...prev,
      productIds: prev.productIds.includes(productId)
        ? prev.productIds.filter((id) => id !== productId)
        : [...prev.productIds, productId],
    }));
  };

  return (
    <FormDialog
      open={open}
      onOpenChange={onOpenChange}
      title={isEditing ? t("editPost") : t("createPost")}
      description={isEditing ? t("editDescription") : t("createDescription")}
      onSubmit={handleSubmit}
      isPending={isPending}
      submitLabel={isEditing ? t("updateBlog") : t("createBlog")}
      maxWidth="max-w-4xl"
    >
      <div className="space-y-6 pt-4">
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="title">{t("title")} *</Label>
            <Input
              id="title"
              value={formData.title}
              onChange={(e) => {
                const title = e.target.value;
                setFormData((prev) => ({
                  ...prev,
                  title,
                  slug: !isEditing ? generateSlug(title) : prev.slug,
                }));
                if (errors.title) setErrors((prev) => ({ ...prev, title: "" }));
              }}
              disabled={isPending}
              className={errors.title ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.title && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.title}
                </motion.p>
              )}
            </AnimatePresence>
          </div>

          <div className="space-y-2">
            <Label htmlFor="slug">{t("slug")} *</Label>
            <Input
              id="slug"
              value={formData.slug}
              onChange={(e) => {
                setFormData((prev) => ({ ...prev, slug: e.target.value }));
                if (errors.slug) setErrors((prev) => ({ ...prev, slug: "" }));
              }}
              disabled={isPending}
              placeholder="auto-generated-from-title"
              className={errors.slug ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.slug && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.slug}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </div>

        <div className="space-y-2">
          <Label htmlFor="excerpt">{t("excerpt")} *</Label>
          <Textarea
            id="excerpt"
            value={formData.excerpt}
            onChange={(e) => {
              setFormData((prev) => ({ ...prev, excerpt: e.target.value }));
              if (errors.excerpt)
                setErrors((prev) => ({ ...prev, excerpt: "" }));
            }}
            disabled={isPending}
            rows={2}
            placeholder={t("excerptPlaceholder")}
            className={errors.excerpt ? "border-destructive" : ""}
          />
          <AnimatePresence>
            {errors.excerpt && (
              <motion.p
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="text-xs text-destructive"
              >
                {errors.excerpt}
              </motion.p>
            )}
          </AnimatePresence>
        </div>

        <div className="space-y-2">
          <Label>{t("content")} *</Label>
          <RichTextEditor
            content={formData.content}
            onChange={(content) => {
              setFormData((prev) => ({ ...prev, content }));
              if (errors.content)
                setErrors((prev) => ({ ...prev, content: "" }));
            }}
            placeholder={t("contentPlaceholder")}
          />
          <AnimatePresence>
            {errors.content && (
              <motion.p
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="text-xs text-destructive"
              >
                {errors.content}
              </motion.p>
            )}
          </AnimatePresence>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="category">{t("category")} *</Label>
            <Select
              value={formData.category}
              onValueChange={(value) => {
                setFormData((prev) => ({ ...prev, category: value }));
                if (errors.category)
                  setErrors((prev) => ({ ...prev, category: "" }));
              }}
              disabled={isPending}
            >
              <SelectTrigger
                className={errors.category ? "border-destructive" : ""}
              >
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {categories.map((cat) => (
                  <SelectItem key={cat.id} value={cat.name}>
                    {cat.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <AnimatePresence>
              {errors.category && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.category}
                </motion.p>
              )}
            </AnimatePresence>
          </div>

          <div className="space-y-2">
            <Label htmlFor="language">{t("language")} *</Label>
            <Select
              value={formData.language}
              onValueChange={(value) =>
                setFormData((prev) => ({ ...prev, language: value }))
              }
              disabled={isPending}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="en">{t("languages.en")}</SelectItem>
                <SelectItem value="vi">{t("languages.vi")}</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="author">{t("author")} *</Label>
            <Input
              id="author"
              value={formData.author}
              onChange={(e) => {
                setFormData((prev) => ({ ...prev, author: e.target.value }));
                if (errors.author)
                  setErrors((prev) => ({ ...prev, author: "" }));
              }}
              disabled={isPending}
              placeholder="John Doe"
              className={errors.author ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.author && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.author}
                </motion.p>
              )}
            </AnimatePresence>
          </div>

          <div className="space-y-2">
            <Label htmlFor="readTime">{t("readTime")}</Label>
            <div className="flex gap-2 items-center">
              <Input
                id="readTime"
                type="number"
                min="1"
                value={formData.readTime}
                onChange={(e) =>
                  setFormData((prev) => ({
                    ...prev,
                    readTime: e.target.value,
                  }))
                }
                disabled={isPending}
                placeholder="5"
                className="w-24"
              />
              <span className="text-sm text-muted-foreground">
                {t("minutes")}
              </span>
            </div>
          </div>
        </div>

        <div className="space-y-2">
          <Label>{t("relatedProducts")}</Label>
          <ScrollArea className="h-48 border rounded-md p-4 bg-white/5">
            <div className="grid grid-cols-2 gap-4">
              {products.map((product) => (
                <div key={product.id} className="flex items-center space-x-2">
                  <Checkbox
                    id={`product-${product.id}`}
                    checked={formData.productIds.includes(product.id)}
                    onCheckedChange={() => toggleProduct(product.id)}
                    disabled={isPending}
                  />
                  <label
                    htmlFor={`product-${product.id}`}
                    className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 cursor-pointer text-foreground"
                  >
                    {product.name}
                  </label>
                </div>
              ))}
            </div>
          </ScrollArea>
        </div>

        <div className="space-y-2">
          <Label>{t("featuredImage")}</Label>
          <ImageUpload
            value={imageFile ? undefined : formData.image}
            onChange={(file) => setImageFile(file)}
            onRemove={() => {
              setImageFile(null);
              setFormData((prev) => ({ ...prev, image: "" }));
            }}
            disabled={isPending}
          />
        </div>
      </div>
    </FormDialog>
  );
}

"use client";

import { deleteBrandAction, getBrandsAction } from "@/actions/admin";
import { Button } from "@/components/atoms/button";
import { DataTableEmptyRow } from "@/components/atoms/data-table-empty-row";
import { DataTablePagination } from "@/components/atoms/data-table-pagination";
import { GlassCard } from "@/components/atoms/glass-card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/atoms/table";
import { AdminSearchInput } from "@/components/organisms/admin/admin-search-input";
import { CreateBrandDialog } from "@/components/organisms/admin/create-brand-dialog";
import { DeleteConfirmDialog } from "@/components/organisms/admin/delete-confirm-dialog";
import { EditBrandDialog } from "@/components/organisms/admin/edit-brand-dialog";
import { useDebounce } from "@/hooks/use-debounce";
import { useAdminBrands } from "@/providers/admin-metadata-provider";
import { useAuth } from "@/providers/auth-provider";
import { PaginationMeta } from "@/types/dtos";
import { Brand } from "@/types/models";
import { useTranslations } from "next-intl";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import useSWR from "swr";

export function BrandsPageClient({
  brands: initialBrands,
  meta,
}: {
  brands: Brand[];
  meta?: PaginationMeta;
}) {
  const t = useTranslations("admin");
  const { hasPermission } = useAuth();
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedBrand, setSelectedBrand] = useState<Brand | null>(null);

  const canCreate = hasPermission("brand:create");
  const canUpdate = hasPermission("brand:update");
  const canDelete = hasPermission("brand:delete");

  const router = useRouter();
  const searchParams = useSearchParams();
  const [searchTerm, setSearchTerm] = useState(
    searchParams.get("search") || ""
  );

  const debouncedSearchTerm = useDebounce(searchTerm, 500);

  const page = Number(searchParams.get("page")) || 1;
  const limit = Number(searchParams.get("limit")) || 10;

  // Hybrid Fetching: SWR for the table list
  const { data: brandsRes, mutate: mutateLocalBrands } = useSWR(
    ["admin-brands-list", page, limit, debouncedSearchTerm],
    () => getBrandsAction(page, limit, debouncedSearchTerm),
    {
      fallbackData: {
        data: initialBrands,
        meta: meta!,
        statusCode: 200,
        message: "Success",
      },
      revalidateOnFocus: false,
    }
  );

  const { mutate: mutateGlobalBrands } = useAdminBrands();

  const brands = brandsRes && "data" in brandsRes ? brandsRes.data || [] : [];

  // Helper to mutate both local and global cache
  const refreshData = () => {
    mutateLocalBrands();
    mutateGlobalBrands();
  };

  // Update URL when debounced search term changes
  useEffect(() => {
    const params = new URLSearchParams(searchParams.toString());
    const currentSearch = params.get("search") || "";

    if (currentSearch !== debouncedSearchTerm) {
      if (debouncedSearchTerm) {
        params.set("search", debouncedSearchTerm);
      } else {
        params.delete("search");
      }
      router.push(`/admin/brands?${params.toString()}`);
    }
  }, [debouncedSearchTerm, router, searchParams]);

  const openEdit = (brand: Brand) => {
    setSelectedBrand(brand);
    setEditDialogOpen(true);
  };

  const openDelete = (brand: Brand) => {
    setSelectedBrand(brand);
    setDeleteDialogOpen(true);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-3xl font-bold">{t("brands.title")}</h1>
        {canCreate && (
          <Button onClick={() => setCreateDialogOpen(true)}>
            {t("brands.createNew")}
          </Button>
        )}
      </div>

      <div className="flex items-center space-x-2">
        <AdminSearchInput
          placeholder={t("search", { item: t("brands.title").toLowerCase() })}
          value={searchTerm}
          onChange={setSearchTerm}
        />
      </div>

      <GlassCard className="p-6">
        <div className="mb-6">
          <h2 className="text-xl font-bold text-foreground">
            {t("all", { item: t("brands.title") })}
          </h2>
        </div>
        <Table>
          <TableHeader>
            <TableRow className="border-white/10 hover:bg-white/5">
              <TableHead className="text-muted-foreground uppercase tracking-wider text-xs font-bold">
                {t("brands.nameLabel")}
              </TableHead>
              <TableHead className="text-muted-foreground uppercase tracking-wider text-xs font-bold">
                {t("created")}
              </TableHead>
              {(canUpdate || canDelete) && (
                <TableHead className="text-right text-muted-foreground uppercase tracking-wider text-xs font-bold">
                  {t("actions")}
                </TableHead>
              )}
            </TableRow>
          </TableHeader>
          <TableBody>
            {brands && brands.length > 0 ? (
              brands.map((brand: any) => (
                <TableRow
                  key={brand.id}
                  className="border-white/10 hover:bg-white/5 transition-colors"
                >
                  <TableCell className="font-medium text-foreground">
                    {brand.name}
                  </TableCell>
                  <TableCell className="text-muted-foreground">
                    {brand.createdAt
                      ? new Date(brand.createdAt).toLocaleDateString()
                      : "N/A"}
                  </TableCell>
                  {(canUpdate || canDelete) && (
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        {canUpdate && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => openEdit(brand)}
                            className="text-blue-400 hover:text-blue-300 hover:bg-blue-400/10"
                          >
                            {t("edit")}
                          </Button>
                        )}
                        {canDelete && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => openDelete(brand)}
                            className="text-red-400 hover:text-red-300 hover:bg-red-400/10"
                          >
                            {t("delete")}
                          </Button>
                        )}
                      </div>
                    </TableCell>
                  )}
                </TableRow>
              ))
            ) : (
              <DataTableEmptyRow
                colSpan={canUpdate || canDelete ? 3 : 2}
                message={t("noFound", {
                  item: t("brands.title").toLowerCase(),
                })}
              />
            )}
          </TableBody>
        </Table>
      </GlassCard>

      {brandsRes && "meta" in brandsRes && brandsRes.meta && (
        <DataTablePagination
          page={brandsRes.meta.page}
          total={brandsRes.meta.total}
          limit={brandsRes.meta.limit}
        />
      )}

      <CreateBrandDialog
        open={createDialogOpen}
        onOpenChange={(open) => {
          setCreateDialogOpen(open);
          if (!open) refreshData();
        }}
      />

      {selectedBrand && (
        <>
          <EditBrandDialog
            brand={selectedBrand}
            open={editDialogOpen}
            onOpenChange={(open) => {
              setEditDialogOpen(open);
              if (!open) refreshData();
            }}
          />
          <DeleteConfirmDialog
            title={t("confirmTitle")}
            description={t("confirmDeleteDesc", { item: selectedBrand.name })}
            action={() => deleteBrandAction(selectedBrand.id)}
            open={deleteDialogOpen}
            onOpenChange={(open) => {
              setDeleteDialogOpen(open);
              if (!open) refreshData();
            }}
          />
        </>
      )}
    </div>
  );
}

"use client";

import {
  getCouponsAction,
  getOrdersAction,
  getProductsAction,
} from "@/actions/admin";
import {
  broadcastNotificationAction,
  sendNotificationToUserAction,
} from "@/actions/notifications";
import { Button } from "@/components/atoms/button";
import { Checkbox } from "@/components/atoms/checkbox";
import { Combobox, ComboboxOption } from "@/components/atoms/combobox";
import { GlassCard } from "@/components/atoms/glass-card";
import { Input } from "@/components/atoms/input";
import { Label } from "@/components/atoms/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/atoms/select";
import { Textarea } from "@/components/atoms/textarea";
import { useDebounce } from "@/hooks/use-debounce";
import { useToast } from "@/hooks/use-toast";
import { Coupon, Order, Product } from "@/types/models";
import { Bell, Mail, Send, Users } from "lucide-react";
import { useTranslations } from "next-intl";
import { useEffect, useMemo, useState } from "react";

interface User {
  id: string;
  email: string;
  firstName?: string | null;
  lastName?: string | null;
}

interface NotificationsAdminClientProps {
  users: User[];
}

const ALL_USERS_VALUE = "__ALL_USERS__";

export function NotificationsAdminClient({
  users,
}: NotificationsAdminClientProps) {
  const t = useTranslations("admin.notifications");
  const { toast } = useToast();
  const [mode, setMode] = useState<"broadcast" | "individual">("broadcast");
  const [isLoading, setIsLoading] = useState(false);

  // Link Builder State
  const [linkType, setLinkType] = useState<
    "custom" | "product" | "order" | "coupon"
  >("custom");
  const [searchQuery, setSearchQuery] = useState("");
  const debouncedSearch = useDebounce(searchQuery, 500);
  const [products, setProducts] = useState<Product[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);

  const [formData, setFormData] = useState({
    userId: "",
    type: "SYSTEM",
    title: "",
    message: "",
    link: "",
    sendEmail: false,
  });

  // Fetch products/orders/coupons when search changes
  useEffect(() => {
    const fetchData = async () => {
      if (linkType === "product") {
        const res = await getProductsAction(1, 10, debouncedSearch);
        if ("data" in res && res.data) setProducts(res.data);
      } else if (linkType === "order") {
        const res = await getOrdersAction(1, 10, debouncedSearch);
        if ("data" in res && res.data)
          setOrders(res.data as unknown as Order[]);
      } else if (linkType === "coupon") {
        const res = await getCouponsAction();
        if ("data" in res && res.data) {
          // Client-side filter for coupons as API might not support search yet
          const allCoupons = res.data as Coupon[];
          const filtered = debouncedSearch
            ? allCoupons.filter((c: Coupon) =>
                c.code.toLowerCase().includes(debouncedSearch.toLowerCase())
              )
            : allCoupons;
          setCoupons(filtered);
        }
      }
    };
    fetchData();
  }, [debouncedSearch, linkType]);

  const userOptions: ComboboxOption[] = useMemo(() => {
    const options: ComboboxOption[] = [
      {
        value: ALL_USERS_VALUE,
        label: t("form.allUsers") || "All Users",
        description: `${users.length} users`,
      },
    ];
    users.forEach((user) => {
      options.push({
        value: user.id,
        label:
          `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email,
        description: user.email,
      });
    });
    return options;
  }, [users, t]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      let result: { success?: boolean; error?: string };

      // If broadcast mode OR "All Users" selected in individual mode
      if (mode === "broadcast" || formData.userId === ALL_USERS_VALUE) {
        result = await broadcastNotificationAction({
          type: formData.type,
          title: formData.title,
          message: formData.message,
          link: formData.link || undefined,
          sendEmail: formData.sendEmail,
        });
      } else {
        const selectedUser = users.find((u) => u.id === formData.userId);
        result = await sendNotificationToUserAction({
          userId: formData.userId,
          type: formData.type,
          title: formData.title,
          message: formData.message,
          link: formData.link || undefined,
          sendEmail: formData.sendEmail,
          email: selectedUser?.email,
        });
