  /**
   * =====================================================================
   * ADMIN PERMISSIONS CLIENT - Quản lý quyền hạn
   * =====================================================================
   *
   * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
   *
   * 1. GROUPING LOGIC (`useMemo`):
   * - Permissions thường có dạng `resource:action` (vd: `user:create`, `product:delete`).
   * - Logic này tự động gom nhóm các quyền theo `resource` (User, Product...).
   * - Dùng `useMemo` để chỉ tính toán lại khi danh sách `permissions` thay đổi -> Tối ưu hiệu năng.
   *
   * 2. CLIENT-SIDE SEARCH:
   * - Search hoạt động trên cả tên Resource (nhóm) và tên Permission (chi tiết).
   * - Filter trực tiếp trên object `groupedPermissions` đã được tính toán trước đó.
   *
   * 3. UI CARD LAYOUT:
   * - Hiển thị dạng Grid Card thay vì Table để dễ nhìn hơn với cấu trúc phân nhóm.
   * =====================================================================
   */
  const t = useTranslations("admin");
  const { hasPermission } = useAuth();
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedPermission, setSelectedPermission] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState("");

  const canCreate = hasPermission("permission:create");
  const canUpdate = hasPermission("permission:update");
  const canDelete = hasPermission("permission:delete");

  const openEdit = (permission: any) => {
    setSelectedPermission(permission);
    setEditDialogOpen(true);
  };

  const openDelete = (permission: any) => {
    setSelectedPermission(permission);
    setDeleteDialogOpen(true);
  };

  // Nhóm quyền theo tài nguyên (ví dụ: "user:read" -> tài nguyên "user")
  const groupedPermissions = useMemo(() => {
    const groups: Record<string, any[]> = {};

    permissions.forEach((perm) => {
      // Thử tách bằng dấu hai chấm hoặc gạch dưới, mặc định là "Other"
      let resource = "Other";
      if (perm.name.includes(":")) {
        resource = perm.name.split(":")[0];
      } else if (perm.name.includes("_")) {
        resource = perm.name.split("_")[0];
      } else {
        resource = perm.name; // Dự phòng nếu không có dấu phân cách
      }

      // Viết hoa chữ cái đầu
      resource = resource.charAt(0).toUpperCase() + resource.slice(1);

      if (!groups[resource]) {
        groups[resource] = [];
      }
      groups[resource].push(perm);
    });

    return groups;
  }, [permissions]);

  // Lọc nhóm dựa trên tìm kiếm
  const filteredGroups = useMemo(() => {
    if (!searchTerm) return groupedPermissions;

    const lowerSearch = searchTerm.toLowerCase();
    const filtered: Record<string, any[]> = {};

    Object.entries(groupedPermissions).forEach(([resource, perms]) => {
      // Kiểm tra xem tên tài nguyên có khớp không
      if (resource.toLowerCase().includes(lowerSearch)) {
        filtered[resource] = perms;
      } else {
        // Kiểm tra xem bất kỳ quyền nào trong nhóm có khớp không
        const matchingPerms = perms.filter((p) =>
          p.name.toLowerCase().includes(lowerSearch)
        );
        if (matchingPerms.length > 0) {
          filtered[resource] = matchingPerms;
        }
      }
    });

    return filtered;
  }, [groupedPermissions, searchTerm]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold">{t("permissions.management")}</h1>
          <p className="text-sm text-gray-500 mt-1">
            {t("permissions.description")}
          </p>
        </div>
        {canCreate && (
          <Button onClick={() => setCreateDialogOpen(true)}>
            <Plus className="mr-2 h-4 w-4" /> {t("permissions.createNew")}
          </Button>
        )}
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
        <Input
          placeholder={t("permissions.searchPlaceholder")}
          className="pl-10 max-w-md"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {Object.entries(filteredGroups).length > 0 ? (
          Object.entries(filteredGroups).map(([resource, perms]) => (
            <GlassCard
              key={resource}
              className="flex flex-col h-full hover:bg-white/5 transition-colors duration-200"
            >
              <div className="p-6 pb-3 flex flex-row items-center justify-between space-y-0">
                <h3 className="text-lg font-bold text-foreground">
                  {resource}
                </h3>
                <Badge
                  variant="secondary"
                  className="rounded-full px-2.5 py-0.5 bg-primary/10 text-primary border-primary/20 font-medium"
                >
                  {perms.length}
                </Badge>
              </div>
              <div className="p-6 pt-0 flex-grow">
                <div className="flex flex-wrap gap-2.5">
                  {perms.map((perm) => (
                    <div
                      key={perm.id}
                      className="group relative inline-flex items-center"
                    >
                      <div className="flex items-center gap-2 px-3 py-1.5 rounded-full border border-white/10 bg-white/5 text-sm text-muted-foreground hover:text-foreground hover:bg-white/10 hover:border-white/20 transition-colors">
                        <span className="font-medium">{perm.name}</span>
                        {(canUpdate || canDelete) && (
                          <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200 -mr-1">
                            {canUpdate && (
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  openEdit(perm);
                                }}
                                className="p-1 text-blue-400 hover:text-blue-300 hover:bg-blue-400/10 rounded-full transition-colors"
                                title={t("edit")}
                              >
                                <Edit2 className="h-3 w-3" />
                              </button>
                            )}
                            {canDelete && (
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  openDelete(perm);
                                }}
                                className="p-1 text-red-400 hover:text-red-300 hover:bg-red-400/10 rounded-full transition-colors"
                                title={t("delete")}
                              >
                                <Trash2 className="h-3 w-3" />
                              </button>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </GlassCard>
          ))
        ) : (
          <div className="col-span-full flex flex-col items-center justify-center py-16 text-muted-foreground bg-white/5 rounded-lg border border-dashed border-white/10">
            <Search className="h-10 w-10 text-muted-foreground/50 mb-3" />
            <p className="text-lg font-medium">{t("permissions.noFound")}</p>
            <p className="text-sm text-muted-foreground/70">
              {t("permissions.adjustSearch")}
            </p>
          </div>
        )}
      </div>

      <CreatePermissionDialog
        open={createDialogOpen}
        onOpenChange={setCreateDialogOpen}
      />

      {selectedPermission && (
        <>
          <EditPermissionDialog
            permissionId={selectedPermission.id}
            currentName={selectedPermission.name}
            open={editDialogOpen}
            onOpenChange={setEditDialogOpen}
          />
          <DeleteConfirmDialog
            open={deleteDialogOpen}
            onOpenChange={setDeleteDialogOpen}
            title={t("confirmTitle")}
            description={t("confirmDeleteDesc", { item: selectedPermission.name })}
            action={() => deletePermissionAction(selectedPermission.id)}
            successMessage={t("permissions.successDelete")}
          />
        </>
      )}
    </div>
  );
}

import { getProductsAction } from "@/actions/admin";
import { getTranslations } from "next-intl/server";
import { ProductsClient } from "./products-client";

/**
 * =====================================================================
 * ADMIN PRODUCTS PAGE - Quản lý sản phẩm (Server Component)
 * =====================================================================
 */

export default async function ProductsPage({
  searchParams,
}: {
  searchParams: Promise<{ page?: string; search?: string }>;
}) {
  const t = await getTranslations("admin.products");
  const params = await searchParams;
  const page = parseInt(params.page || "1", 10);
  const limit = 12;
  const search = params.search || "";

  // Fetch products only - Brands and Categories are handled by AdminMetadataProvider in Layout
  const [productsRes] = await Promise.all([
    getProductsAction(page, limit, search),
  ]);

  if (!("data" in productsRes)) {
    return (
      <div className="p-8">
        <div className="text-red-600 bg-red-50 border border-red-200 rounded p-4">
          <h2 className="font-bold mb-2">{t("errorLoading")}</h2>
          <p>{(productsRes as any).error}</p>
        </div>
      </div>
    );
  }

  return (
    <ProductsClient
      products={productsRes.data || []}
      total={productsRes.meta?.total || 0}
      page={page}
      limit={limit}
    />
  );
}

"use client";

import {
  deleteReviewAction,
  replyToReviewAction,
  updateReviewAction,
} from "@/actions/admin";
import { Button } from "@/components/atoms/button";
import { DataTableEmptyRow } from "@/components/atoms/data-table-empty-row";
import { DataTablePagination } from "@/components/atoms/data-table-pagination";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/atoms/dialog";
import { GlassCard } from "@/components/atoms/glass-card";
import { StatusBadge } from "@/components/atoms/status-badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/atoms/table";
import { Textarea } from "@/components/atoms/textarea";
import { AdminSearchInput } from "@/components/organisms/admin/admin-search-input";
import { DeleteConfirmDialog } from "@/components/organisms/admin/delete-confirm-dialog";
import { useDebounce } from "@/hooks/use-debounce";
import { useToast } from "@/hooks/use-toast";
import { useRouter } from "@/i18n/routing";
import { formatDate } from "@/lib/utils";
import { useAuth } from "@/providers/auth-provider";
import { Eye, EyeOff, MessageSquare, Star, Trash2 } from "lucide-react";
import { useTranslations } from "next-intl";
import { useSearchParams } from "next/navigation";
import { useEffect, useState, useTransition } from "react";

export function ReviewsClient({
  reviews,
  total,
  page,
  limit,
}: {
  reviews: any[];
  total: number;
  page: number;
  limit: number;
}) {
  const t = useTranslations("admin");
  const { hasPermission } = useAuth();
  const { toast } = useToast();
  const router = useRouter();
  const searchParams = useSearchParams();
  const [isPending, startTransition] = useTransition();
  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);

  // Reply State
  const [replyId, setReplyId] = useState<string | null>(null);
  const [replyText, setReplyText] = useState("");
  const [replyDialogOpen, setReplyDialogOpen] = useState(false);
  const [isReplying, setIsReplying] = useState(false);

  const canUpdate = hasPermission("review:update");
  const canDelete = hasPermission("review:delete");

  const [searchTerm, setSearchTerm] = useState(
    searchParams.get("search") || ""
  );
  const debouncedSearchTerm = useDebounce(searchTerm, 500);

  useEffect(() => {
    const params = new URLSearchParams(searchParams.toString());
    const currentSearch = params.get("search") || "";

    if (currentSearch !== debouncedSearchTerm) {
      if (debouncedSearchTerm) {
        params.set("search", debouncedSearchTerm);
      } else {
        params.delete("search");
      }
      params.set("page", "1");
      router.push(`/admin/reviews?${params.toString()}` as any);
    }
  }, [debouncedSearchTerm, router, searchParams]);

  const togglePublish = (reviewId: string, currentStatus: boolean) => {
    startTransition(async () => {
      const result = await updateReviewAction(reviewId, {
        isPublished: !currentStatus,
      });
      if (result.success) {
        toast({
          title: t("success"),
          description: t("reviews.successUpdate"),
        });
      } else {
        toast({
          title: t("error"),
          description: result.error,
          variant: "destructive",
        });
      }
    });
  };

  const handleDelete = (reviewId: string) => {
    setDeleteId(reviewId);
    setDeleteDialogOpen(true);
  };

  const handleReply = (reviewId: string, currentReply?: string) => {
    setReplyId(reviewId);
    setReplyText(currentReply || "");
    setReplyDialogOpen(true);
  };

  const submitReply = async () => {
    if (!replyId || !replyText.trim()) return;
    setIsReplying(true);
    try {
      const result = await replyToReviewAction(replyId, replyText);
      if (result.success) {
        toast({
          title: t("success"),
          description: "Reply sent successfully",
          variant: "success",
        });
        setReplyDialogOpen(false);
        setReplyText("");
        setReplyId(null);
      } else {
        toast({
          title: t("error"),
          description: result.error,
          variant: "destructive",
        });
      }
    } catch (error) {
      toast({
        title: t("error"),
        description: "Failed to send reply",
        variant: "destructive",
      });
    } finally {
      setIsReplying(false);
    }
  };

  const renderStars = (rating: number) => {
    return (
      <div className="flex text-yellow-500">
        {[1, 2, 3, 4, 5].map((s) => (
          <Star
            key={s}
            className={`h-4 w-4 ${
              s <= rating ? "fill-current" : "text-gray-300"
            }`}
          />
        ))}
      </div>
    );
  };

  const totalPages = Math.ceil(total / limit);

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">{t("reviews.management")}</h1>
          <p className="text-sm text-gray-400 mt-1">
            {t("showing", {
              count: reviews.length,
              total,
              item: t("reviews.title").toLowerCase(),
            })}
          </p>
        </div>
      </div>

      <div className="flex items-center space-x-2">
        <AdminSearchInput
          placeholder={t("reviews.searchPlaceholder")}
          value={searchTerm}
          onChange={setSearchTerm}
        />
      </div>

      <GlassCard className="p-6">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className="w-[150px]">{t("name")}</TableHead>
              <TableHead>{t("product")}</TableHead>
              <TableHead>{t("reviews.rating")}</TableHead>
              <TableHead className="max-w-md">{t("reviews.comment")}</TableHead>
              <TableHead>{t("reviews.status")}</TableHead>
              <TableHead>{t("created")}</TableHead>
              {(canUpdate || canDelete) && (
                <TableHead className="text-right">{t("actions")}</TableHead>
              )}
            </TableRow>
          </TableHeader>
          <TableBody>
            {reviews.length === 0 ? (
              <DataTableEmptyRow
                colSpan={canUpdate || canDelete ? 7 : 6}
                message={t("reviews.noFound")}
              />
            ) : (
              reviews.map((review) => (
                <TableRow key={review.id}>
                  <TableCell className="font-medium">
                    {review.user?.firstName} {review.user?.lastName}
                  </TableCell>
                  <TableCell>
                    <div className="text-sm font-medium">
                      {review.product?.name}
                    </div>
                    <div className="text-xs text-gray-500 font-mono">
                      {review.sku?.code}
                    </div>
                  </TableCell>
                  <TableCell>{renderStars(review.rating)}</TableCell>
                  <TableCell className="max-w-md">
                    <div className="truncate" title={review.comment}>
                      {review.comment}
                    </div>
                    {review.reply && (
                      <div className="mt-2 pl-3 border-l-2 border-primary/50 text-sm text-muted-foreground">
                        <span className="font-bold text-xs uppercase text-primary">
                          Admin Reply:
                        </span>{" "}
                        {review.reply}
                      </div>
                    )}
                  </TableCell>
                  <TableCell>
                    <StatusBadge
                      status={review.isPublished ? "PUBLISHED" : "HIDDEN"}
                      label={
                        review.isPublished
                          ? t("reviews.published")
                          : t("reviews.hidden")
                      }
                    />
                  </TableCell>
                  <TableCell className="text-sm text-gray-500">
                    {formatDate(review.createdAt)}
                  </TableCell>
                  {(canUpdate || canDelete) && (
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        {canUpdate && (
                          <>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                handleReply(review.id, review.reply)
                              }
                              className="text-blue-400 hover:text-blue-300 hover:bg-blue-400/10"
                              title="Reply"
                            >
                              <MessageSquare className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() =>
                                togglePublish(review.id, review.isPublished)
                              }
                              title={
                                review.isPublished
                                  ? t("reviews.hidden")
                                  : t("reviews.published")
                              }
                            >
                              {review.isPublished ? (
                                <EyeOff className="h-4 w-4" />
                              ) : (
                                <Eye className="h-4 w-4" />
                              )}
                            </Button>
                          </>
                        )}
                        {canDelete && (
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleDelete(review.id)}
                            className="text-red-400 hover:text-red-300 hover:bg-red-400/10"
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        )}
                      </div>
                    </TableCell>
                  )}
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>

        <DataTablePagination page={page} total={total} limit={limit} />

        {deleteId && (
          <DeleteConfirmDialog
            open={deleteDialogOpen}
            onOpenChange={setDeleteDialogOpen}
            title={t("reviews.deleteConfirm")}
            description={t("reviews.deleteConfirmDesc", { id: deleteId })}
            action={() => deleteReviewAction(deleteId)}
            successMessage={t("reviews.successDelete")}
          />
        )}

        {/* Reply Dialog */}
        <Dialog open={replyDialogOpen} onOpenChange={setReplyDialogOpen}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Reply to Review</DialogTitle>
              <DialogDescription>
                Write a response to this customer review. They will be notified.
              </DialogDescription>
            </DialogHeader>
            <div className="py-4">
              <Textarea
                value={replyText}
                onChange={(e) => setReplyText(e.target.value)}
                placeholder="Type your reply here..."
                rows={4}
              />
            </div>
            <DialogFooter>
              <Button
                variant="outline"
                onClick={() => setReplyDialogOpen(false)}
                disabled={isReplying}
              >
                Cancel
              </Button>
              <Button
                onClick={submitReply}
                disabled={isReplying || !replyText.trim()}
              >
                {isReplying ? "Sending..." : "Send Reply"}
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </GlassCard>
    </div>
  );
}

"use client";
