import Image from "next/image";

/**
 * =====================================================================
 * NAV CARD - Thẻ điều hướng danh mục/thương hiệu
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. POLYMORPHIC STYLING:
 * - Sử dụng object `variantStyles` để quản lý giao diện cho các trạng thái khác nhau (default, brand, category).
 * - Giúp code gọn gàng hơn so với việc dùng nhiều câu lệnh `if/else` hoặc `cn()` quá dài.
 *
 * 2. GROUP HOVER EFFECT:
 * - `group` ở thẻ cha và `group-hover:...` ở thẻ con.
 * - Khi hover vào thẻ cha, các thẻ con sẽ thay đổi style (zoom ảnh, hiện mũi tên, đổi màu chữ).
 *
 * 3. FALLBACK UI:
 * - Nếu không có `imageUrl`, hiển thị chữ cái đầu của tên (`name.charAt(0)`).
 * - Đảm bảo UI không bị vỡ khi thiếu dữ liệu ảnh.
 */

interface NavCardProps {
  href: string;
  name: string;
  count?: number;
  imageUrl?: string;
  variant?: "default" | "brand" | "category";
  className?: string;
}

export function NavCard({
  href,
  name,
  count,
  imageUrl,
  variant = "default",
  className,
}: NavCardProps) {
  const variantStyles = {
    default: {
      ring: "group-hover:ring-primary/20",
      text: "group-hover:text-primary",
      arrow: "text-primary bg-primary/5",
      border: "hover:border-primary/20 hover:shadow-xl hover:shadow-primary/5",
    },
    brand: {
      ring: "group-hover:ring-accent/20",
      text: "group-hover:text-accent",
      arrow: "text-accent bg-accent/5",
      border: "hover:border-accent/20 hover:shadow-xl hover:shadow-accent/5",
    },
    category: {
      ring: "group-hover:ring-primary/20",
      text: "group-hover:text-primary",
      arrow: "text-primary bg-primary/5",
      border: "hover:border-primary/20 hover:shadow-xl hover:shadow-primary/5",
    },
  };

  const styles = variantStyles[variant];

  return (
    <Link
      href={href as any}
      className={cn(
        "group relative block overflow-hidden rounded-[2rem] bg-background border border-foreground/5 transition-all duration-500",
        styles.border,
        className
      )}
    >
      <div className="flex items-center p-5 gap-5">
        {/* Image with premium ring on hover */}
        <div
          className={cn(
            "relative w-20 h-20 rounded-2xl overflow-hidden shrink-0 ring-1 ring-foreground/5 transition-all duration-700 bg-foreground/[0.02] flex items-center justify-center",
            styles.ring
          )}
        >
          {imageUrl ? (
            <Image
              src={imageUrl}
              alt={name}
              fill
              sizes="80px"
              className="object-cover group-hover:scale-110 transition-transform duration-700 ease-out"
            />
          ) : (
            <span
              className={cn(
                "text-2xl font-black text-foreground/20 transition-colors uppercase",
                styles.text
              )}
            >
              {name.charAt(0)}
            </span>
          )}
        </div>

        {/* Content */}
        <div className="flex-1 min-w-0">
          <h3
            className={cn(
              "font-black text-lg tracking-tight truncate transition-colors duration-300",
              styles.text
            )}
          >
            {name}
          </h3>
          {count !== undefined && (
            <div className="flex items-center gap-2 mt-1">
              <span className="h-1 w-1 rounded-full bg-primary/40" />
              <p className="text-[11px] font-bold uppercase tracking-widest text-muted-foreground/60">
                {count} {count === 1 ? "Item" : "Items"}
              </p>
            </div>
          )}
        </div>

        {/* Arrow indicator */}
        <div
          className={cn(
            "w-10 h-10 rounded-full flex items-center justify-center opacity-0 -translate-x-4 group-hover:opacity-100 group-hover:translate-x-0 transition-all duration-500 ease-out",
            styles.arrow
          )}
        >
          <ArrowRight className="w-5 h-5" />
        </div>
      </div>
    </Link>
  );
}

/**
 * =====================================================================
 * CART BADGE - Huy hiệu hiển thị số lượng sản phẩm trong giỏ hàng
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. CART CONTEXT:
 * - Lấy số lượng sản phẩm (`count`) từ `CartProvider`.
 * - Tự động cập nhật khi user thêm/xóa sản phẩm.
 *
 * 2. CONDITIONAL RENDERING:
 * - Nếu `count === 0`, component trả về `null` (không hiển thị gì cả).
 *
 * 3. ANIMATION:
 * - Sử dụng các utility classes của Tailwind (`animate-in zoom-in`) để tạo hiệu ứng xuất hiện sinh động.
 *
 * 4. PERFORMANCE:
 * - Sử dụng React.memo để prevent unnecessary re-renders
 * =====================================================================
 */

"use client";

import { useCartContext } from "@/providers/cart-provider";
import { memo } from "react";

// Props kept for compatibility with parent component, but not used internally
interface CartBadgeProps {
