    DropdownMenuSubTrigger,
    DropdownMenuTrigger,
} from "@/components/atoms/dropdown-menu";
import { ThemeToggle } from "@/components/molecules/theme-toggle";
import { Link } from "@/i18n/routing";
import {
    Laptop,
    Loader2,
    LogOut,
    Moon,
    Palette,
    Sun,
    User,
} from "lucide-react";
import { useTranslations } from "next-intl";
import { useTheme } from "next-themes";
import { useState } from "react";

/**
 * =====================================================================
 * HEADER ACTIONS - Các hành động trên Header (User, Theme, Auth)
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. USER PROFILE HOOK (`useUserProfile`):
 * - Tự động fetch thông tin user từ API nếu đã đăng nhập.
 * - Quản lý trạng thái loading và error một cách tập trung.
 *
 * 2. DROPDOWN MENU (Radix UI):
 * - Hiển thị menu xổ xuống khi click vào Avatar.
 * - Chứa các link quan trọng: Profile, Theme, Logout.
 *
 * 3. THEME SWITCHING:
 * - Sử dụng `next-themes` để thay đổi giữa Light, Dark và System mode.
 * - `DropdownMenuSub`: Menu con lồng nhau giúp giao diện gọn gàng hơn.
 *
 * 4. LOGOUT LOGIC:
 * - Khi logout, ta cần xóa `guest_cart` trong localStorage để tránh xung đột dữ liệu cũ.
 * - Dispatch event `cart_clear` để các component khác cập nhật UI ngay lập tức.
 * =====================================================================
 */

import { LanguageSwitcher } from "@/components/molecules/language-switcher";

interface HeaderActionsProps {
  initialUser?: any;
}

export function HeaderActions({ initialUser }: HeaderActionsProps) {
  const t = useTranslations("common");
  const { setTheme } = useTheme();
  // Use initialUser directly from props (already fetched by layout)
  const user = initialUser;
  const [isLoggingOut, setIsLoggingOut] = useState(false);

  if (!user) {
    return (
      <div className="flex items-center gap-4">
        <LanguageSwitcher />
        <ThemeToggle />
        <div className="flex gap-2">
          <Link href="/login">
            <Button variant="ghost" size="sm" className="cursor-pointer">
              {t("login")}
            </Button>
          </Link>
          <Link href="/register">
            <Button size="sm" className="cursor-pointer">
              {t("register")}
            </Button>
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="flex items-center gap-4">
      <LanguageSwitcher />
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button variant="ghost" className="relative h-10 w-10 rounded-full">
            <Avatar className="h-10 w-10">
              <AvatarImage src={user.avatar} alt={user.firstName || "User"} />
              <AvatarFallback>
                {user.firstName?.[0] || ""}
                {user.lastName?.[0] || "U"}
              </AvatarFallback>
            </Avatar>
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-56">
          <DropdownMenuLabel>
            <div className="flex flex-col space-y-1">
              <p className="text-sm font-medium leading-none">
                {user.firstName} {user.lastName}
              </p>
              <p className="text-xs leading-none text-muted-foreground">
                {user.email}
              </p>
            </div>
          </DropdownMenuLabel>
          <DropdownMenuSeparator />
          <DropdownMenuItem asChild>
            <Link href="/profile" className="cursor-pointer">
              <User className="h-4 w-4" />
              <span>{t("profile") || "Profile"}</span>
            </Link>
          </DropdownMenuItem>
          <DropdownMenuSub>
            <DropdownMenuSubTrigger>
              <Palette className="h-4 w-4" />
              <span>{t("theme") || "Theme"}</span>
            </DropdownMenuSubTrigger>
            <DropdownMenuPortal>
              <DropdownMenuSubContent>
                <DropdownMenuItem onClick={() => setTheme("light")}>
                  <Sun className="h-4 w-4" />
                  <span>{t("light") || "Light"}</span>
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => setTheme("dark")}>
                  <Moon className="h-4 w-4" />
                  <span>{t("dark") || "Dark"}</span>
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => setTheme("system")}>
                  <Laptop className="h-4 w-4" />
                  <span>{t("system") || "System"}</span>
                </DropdownMenuItem>
              </DropdownMenuSubContent>
            </DropdownMenuPortal>
          </DropdownMenuSub>
          <DropdownMenuSeparator />
          <DropdownMenuItem
            disabled={isLoggingOut}
            onClick={async (e) => {
              e.preventDefault();
              if (isLoggingOut) return;

              setIsLoggingOut(true);
              try {
                // Clear guest cart to prevent stale data
                localStorage.removeItem("guest_cart");
                window.dispatchEvent(new Event("guest_cart_updated"));
                // Force clear cart badge immediately
                window.dispatchEvent(new Event("cart_clear"));
                await logoutAction();
              } finally {
                // No need to set false as we redirect
              }
            }}
          >
            {isLoggingOut ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <LogOut className="h-4 w-4" />
            )}
            <span>{t("logout") || "Log out"}</span>
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  );
}

"use client";

import { Link, usePathname } from "@/i18n/routing";
import { cn } from "@/lib/utils";
import { useAuth } from "@/providers/auth-provider";
import {
  BookOpen,
  Home,
  Info,
  Phone,
  ShieldCheck,
  ShoppingBag,
} from "lucide-react";

/**
 * =====================================================================
 * HEADER NAV - Menu điều hướng chính trên Desktop
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. ACTIVE LINK HIGHLIGHTING:
 * - Sử dụng `usePathname` để biết user đang ở trang nào.
 * - `pathname === link.href` (Exact) hoặc `pathname.startsWith(link.href)` (Prefix).
 * - Hiển thị gạch chân (`after:w-full`) cho link đang active.
 *
 * 2. CONDITIONAL LINKS (RBAC):
 * - `Orders`: Chỉ hiển thị nếu user đã đăng nhập.
 * - `Admin`: Chỉ hiển thị nếu user có quyền `admin:read`.
 *
 * 3. HYBRID REFACTOR WARNING:
 * - `hasPermission` lấy dữ liệu từ `AuthProvider`. Nếu user đăng nhập ở client, context này cần được cập nhật để hiển thị đúng các link quyền hạn.
 * =====================================================================
 */

interface HeaderNavProps {
  initialUser?: any;
  permissions?: string[];
}

import { useTranslations } from "next-intl";

export function HeaderNav({
  initialUser,
  permissions: propsPermissions,
}: HeaderNavProps) {
  const t = useTranslations("nav");
  const pathname = usePathname();
  // Use initialUser directly from props (already fetched by layout)
  const user = initialUser;
  const { hasPermission: contextHasPermission } = useAuth();

  // Use permissions from props if available (for PPR stability), otherwise fallback to context
  const hasPermission = (perm: string) => {
    if (propsPermissions) return propsPermissions.includes(perm);
    return contextHasPermission(perm);
  };

  const links = [
    { href: "/", label: t("home"), icon: Home, exact: true },
    { href: "/shop", label: t("shop"), icon: ShoppingBag, exact: false },
    { href: "/about", label: t("about"), icon: Info, exact: true },
    { href: "/blog", label: t("journal"), icon: BookOpen, exact: false },
    { href: "/contact", label: t("contact"), icon: Phone, exact: true },
  ];

  return (
    <nav className="hidden md:flex items-center gap-6 text-base font-medium">
      {links.map((link) => (
        <Link
          key={link.href}
          href={link.href as any}
          className={cn(
            "transition-colors flex items-center gap-1 relative w-fit after:absolute after:bottom-[-2px] after:left-0 after:h-[2px] after:bg-primary after:transition-all after:duration-300",
            (
              link.exact
                ? pathname === link.href
                : pathname.startsWith(link.href)
            )
              ? "text-primary font-semibold after:w-full"
              : "text-foreground/60 hover:text-foreground/80 after:w-0 hover:after:w-full"
          )}
        >
          <span className="flex items-center gap-1">
            <link.icon size={16} /> {link.label}
          </span>
        </Link>
      ))}

      {hasPermission("admin:read") && (
        <Link
          href={"/admin" as any}
          className={cn(
            "transition-colors flex items-center gap-1 font-semibold relative w-fit after:absolute after:bottom-[-2px] after:left-0 after:h-[2px] after:bg-primary after:transition-all after:duration-300",
            pathname?.startsWith("/admin")
              ? "after:w-full"
              : "hover:text-foreground/80 after:w-0 hover:after:w-full"
          )}
        >
          <span className="flex items-center gap-1">
            <ShieldCheck size={16} /> {t("admin")}
          </span>
        </Link>
      )}
    </nav>
  );
}

/**
 * =====================================================================
 * LANGUAGE SWITCHER - Component chuyển đổi ngôn ngữ
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. useLocale & usePathname:
 * - `useLocale`: Lấy ngôn ngữ hiện tại (vi hoặc en).
 * - `usePathname`: Lấy đường dẫn hiện tại (không bao gồm locale prefix).
 *
 * 2. Link component (từ @/i18n/routing):
 * - Khi chuyển ngôn ngữ, ta dùng chính `pathname` hiện tại nhưng truyền `locale` mới.
 * - Link sẽ tự động điều hướng sang /{new-locale}/{pathname}.
 * =====================================================================
 */

import { Button } from "@/components/atoms/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/atoms/dropdown-menu";
import { usePathname, useRouter } from "@/i18n/routing";
import { cn } from "@/lib/utils";
import { Languages } from "lucide-react";
import { useLocale, useTranslations } from "next-intl";
import { useState, useTransition } from "react";

export function LanguageSwitcher() {
  const t = useTranslations("common");
  const locale = useLocale();
  const pathname = usePathname();
  const router = useRouter();
  const [isPending, startTransition] = useTransition();
  const [open, setOpen] = useState(false);

  const handleLanguageChange = (newLocale: "en" | "vi") => {
    if (newLocale === locale) {
      setOpen(false);
      return;
    }

    // Close the menu immediately before starting the transition
    setOpen(false);

    startTransition(() => {
      router.replace(pathname as any, { locale: newLocale, scroll: false });
    });
  };

  return (
    <DropdownMenu open={open} onOpenChange={setOpen}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className={cn(
            "w-9 h-9 transition-all duration-200 cursor-pointer",
            isPending && "opacity-40 scale-90"
          )}
          disabled={isPending}
        >
          <Languages className="h-4 w-4" />
          <span className="sr-only">{t("sr.switchLanguage")}</span>
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent
        align="end"
        className="min-w-[120px] p-1 flex flex-col gap-1"
      >
        <DropdownMenuItem
          onClick={() => handleLanguageChange("en")}
          disabled={isPending}
          className={cn(
            "w-full cursor-pointer flex items-center px-2 py-2 rounded-md transition-colors",
            locale === "en" && "bg-accent font-medium"
          )}
        >
          {t("languages.en")}
        </DropdownMenuItem>
        <DropdownMenuItem
          onClick={() => handleLanguageChange("vi")}
          disabled={isPending}
          className={cn(
            "w-full cursor-pointer flex items-center px-2 py-2 rounded-md transition-colors",
            locale === "vi" && "bg-accent font-medium"
          )}
        >
          {t("languages.vi")}
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/**
 * =====================================================================
 * NOTIFICATION ITEM - Từng dòng thông báo cụ thể
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. DYNAMIC STYLING:
 * - `getTypeStyles`: Tự động thay đổi màu sắc và icon dựa trên loại thông báo (ORDER, PROMO, SYSTEM, v.v.).
 *
 * 2. INTERACTION:
 * - Khi click vào thông báo:
 *   a. Đánh dấu là đã đọc (`onRead`).
 *   b. Mở hộp thoại chi tiết (`Dialog`) để xem toàn bộ nội dung.
 *
 * 3. LOCALIZATION:
 * - Sử dụng `formatDistanceToNow` kết hợp với `locale` để hiển thị thời gian thân thiện (VD: "2 phút trước").
 * =====================================================================
 */

"use client";

import { Button } from "@/components/atoms/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/atoms/dialog";
import { Notification } from "@/contexts/notification-context";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";
import { enUS, vi } from "date-fns/locale";
import { ExternalLink } from "lucide-react";
import { useLocale } from "next-intl";
import { useRouter } from "next/navigation";
import { useState } from "react";

interface NotificationItemProps {
  notification: Notification;
  onRead: (id: string) => void;
}

export function NotificationItem({
  notification,
  onRead,
}: NotificationItemProps) {
  const locale = useLocale();
  const router = useRouter();
  const [showDialog, setShowDialog] = useState(false);

  const handleClick = () => {
    // Mark as read
    onRead(notification.id);
    // Show dialog
    setShowDialog(true);
  };

  const handleGoToLink = () => {
    setShowDialog(false);
    if (notification.link) {
      router.push(notification.link as any);
    }
  };

  const getTypeStyles = (type: string) => {
    switch (type?.toUpperCase()) {
      case "ORDER":
      case "ORDER_PLACED":
      case "ORDER_SHIPPED":
      case "ORDER_DELIVERED":
        return {
          bg: "bg-emerald-50/50 dark:bg-emerald-900/10",
          icon: "bg-emerald-500",
          text: "text-emerald-600 dark:text-emerald-400",
        };
      case "LOW_STOCK":
      case "ORDER_CANCELLED":
      case "ORDER_RETURNED":
        return {
          bg: "bg-amber-50/50 dark:bg-amber-900/10",
          icon: "bg-amber-500",
          text: "text-amber-600 dark:text-amber-400",
        };
      case "PROMO":
      case "PROMOTION":
        return {
          bg: "bg-primary/5 dark:bg-primary/10",
          icon: "bg-primary",
          text: "text-primary",
        };
      case "SYSTEM":
      case "INFO":
        return {
          bg: "bg-primary/5 dark:bg-primary/10",
          icon: "bg-primary",
          text: "text-primary",
        };
      default:
        return {
          bg: "bg-slate-50/50 dark:bg-slate-900/10",
          icon: "bg-slate-500",
          text: "text-slate-600 dark:text-slate-400",
        };
    }
  };

  const styles = getTypeStyles(notification.type);

  return (
    <>
      <div
        onClick={handleClick}
        className={cn(
          "flex cursor-pointer flex-col gap-1 border-b px-4 py-3 transition-colors hover:bg-muted/50 last:border-0",
          !notification.isRead && styles.bg
        )}
      >
        <div className="flex items-start justify-between gap-2">
          <div className="flex items-center gap-2">
            {!notification.isRead && (
              <span
                className={cn("h-2 w-2 shrink-0 rounded-full", styles.icon)}
              />
            )}
            <p
              className={cn(
                "text-sm font-medium",
                !notification.isRead && "font-bold"
              )}
            >
              {notification.title}
            </p>
          </div>
          <span
            className={cn(
              "text-[10px] font-bold uppercase tracking-wider",
              styles.text
            )}
          >
            {notification.type}
          </span>
        </div>
        <p className="text-xs text-muted-foreground line-clamp-2 pl-4">
          {notification.message}
        </p>
        <p className="text-[10px] text-muted-foreground pl-4">
          {formatDistanceToNow(new Date(notification.createdAt), {
            addSuffix: true,
            locale: locale === "vi" ? vi : enUS,
          })}
        </p>
      </div>

      {/* Notification Detail Dialog */}
      <Dialog open={showDialog} onOpenChange={setShowDialog}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <div className="flex items-center gap-2">
              <span
                className={cn("h-3 w-3 rounded-full shrink-0", styles.icon)}
              />
              <DialogTitle>{notification.title}</DialogTitle>
            </div>
            <div className="flex items-center gap-2 text-xs">
              <span className={cn("font-semibold", styles.text)}>
                {notification.type}
              </span>
              <span className="text-muted-foreground">•</span>
              <span className="text-muted-foreground">
                {formatDistanceToNow(new Date(notification.createdAt), {
                  addSuffix: true,
                  locale: locale === "vi" ? vi : enUS,
                })}
              </span>
            </div>
          </DialogHeader>
          <DialogDescription className="text-base leading-relaxed whitespace-pre-wrap">
            {notification.message}
          </DialogDescription>
          <DialogFooter className="flex-row gap-2 sm:justify-between">
            <Button
              variant="outline"
              onClick={() => setShowDialog(false)}
              className="flex-1"
            >
              Đóng
            </Button>
            {notification.link && (
              <Button onClick={handleGoToLink} className="flex-1 gap-2">
                <ExternalLink className="h-4 w-4" />
                Xem chi tiết
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

