/**
 * =====================================================================
 * PRODUCT VARIANT SELECTOR - Bộ chọn thuộc tính sản phẩm (Size, Color...)
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. COMPLEX STATE MANAGEMENT:
 * - Quản lý việc chọn các option (Size: M, Color: Red) và tìm ra SKU tương ứng.
 * - Nếu một kết hợp không tồn tại, nó sẽ cố gắng tìm SKU "gần giống nhất" hoặc còn hàng.
 *
 * 2. URL SYNC:
 * - Cập nhật `skuId` lên URL để khi user reload trang hoặc chia sẻ link, biến thể đã chọn vẫn được giữ nguyên.
 *
 * 3. DYNAMIC PRICING:
 * - Giá sản phẩm sẽ thay đổi ngay lập tức khi user chọn các biến thể khác nhau.
 * =====================================================================
 */

"use client";
import { Badge } from "@/components/atoms/badge";
import { GlassButton } from "@/components/atoms/glass-button";
import { cn, formatCurrency } from "@/lib/utils";
import { ProductOption, Sku } from "@/types/models";
import { useRouter, useSearchParams } from "next/navigation";
import { useEffect, useMemo, useRef, useState } from "react";

/**
 * =====================================================================
 * PRODUCT VARIANT SELECTOR - Bộ chọn thuộc tính sản phẩm (Size, Color...)
 * =====================================================================
 */

interface ProductVariantSelectorProps {
  options: ProductOption[];
  skus: Sku[];
  isLoggedIn?: boolean;
  selectedSkuId?: string | null;
  onSkuChange?: (sku: Sku | null) => void;
  onImageChange?: (imageUrl: string) => void;
  onAddToCart?: () => void;
  isAdding?: boolean;
  showBuyNow?: boolean;
}

export function ProductVariantSelector({
  options,
  skus,
  isLoggedIn = false,
  selectedSkuId,
  onSkuChange,
  onImageChange,
  onAddToCart,
  isAdding = false,
  showBuyNow = true,
}: ProductVariantSelectorProps) {
  const [selectedOptions, setSelectedOptions] = useState<
    Record<string, string>
  >({});

  const lastNotifiedSkuId = useRef<string | undefined>(undefined);
  const searchParams = useSearchParams();
  const router = useRouter();

  useEffect(() => {
    if (selectedSkuId) {
      const targetSku = skus.find((s) => s.id === selectedSkuId);
      if (targetSku && targetSku.optionValues) {
        const newSelectedOptions: Record<string, string> = {};
        targetSku.optionValues.forEach((ov) => {
          if (ov?.optionValue) {
            newSelectedOptions[ov.optionValue.optionId] = ov.optionValue.id;
          }
        });
        setSelectedOptions(newSelectedOptions);
      }
    }
  }, [selectedSkuId, skus]);

  useEffect(() => {
    if (Object.keys(selectedOptions).length > 0) return;

    const newSelectedOptions: Record<string, string> = {};
    const skuIdFromUrl = searchParams.get("skuId");

    if (skuIdFromUrl) {
      const targetSku = skus.find((s) => s.id === skuIdFromUrl);
      if (targetSku && targetSku.optionValues) {
        targetSku.optionValues.forEach((ov) => {
          if (ov?.optionValue)
            newSelectedOptions[ov.optionValue.optionId] = ov.optionValue.id;
        });
      }
    }

    if (Object.keys(newSelectedOptions).length > 0) {
      setSelectedOptions(newSelectedOptions);
      return;
    }

    if (options.length > 0) {
      const availableSku = skus.find((s) => s.stock > 0) || skus[0];
      if (availableSku && availableSku.optionValues) {
        availableSku.optionValues.forEach((ov) => {
          if (ov?.optionValue)
            newSelectedOptions[ov.optionValue.optionId] = ov.optionValue.id;
        });
        setSelectedOptions(newSelectedOptions);
      }
    }
  }, [searchParams, skus, options]);

  const handleSelect = (optionId: string, valueId: string) => {
    const nextOptions = { ...selectedOptions, [optionId]: valueId };
    let bestSku = skus.find((sku) => {
      if (!sku.optionValues || sku.optionValues.length === 0) return false;
      return sku.optionValues.every((ov) => {
        return nextOptions[ov.optionValue.optionId] === ov.optionValue.id;
      });
    });

    if (!bestSku) {
      const compatibleSkus = skus.filter(
        (s) =>
          s.optionValues &&
          s.optionValues.some(
            (ov) =>
              ov.optionValue.optionId === optionId &&
              ov.optionValue.id === valueId
          )
      );

      if (compatibleSkus.length > 0) {
        bestSku = compatibleSkus.reduce((best, current) => {
          const countMatches = (sku: Sku) => {
            if (!sku.optionValues) return 0;
            return sku.optionValues.reduce((cnt, ov) => {
              if (ov.optionValue.optionId === optionId) return cnt;
              if (
                selectedOptions[ov.optionValue.optionId] === ov.optionValue.id
              )
                return cnt + 1;
              return cnt;
            }, 0);
          };

          const currentMatches = countMatches(current);
          const bestMatches = countMatches(best);

          if (currentMatches > bestMatches) return current;
          if (currentMatches === bestMatches) {
            if (current.stock > 0 && best.stock <= 0) return current;
          }
          return best;
        }, compatibleSkus[0]);
      }
    }

    if (bestSku && bestSku.optionValues && bestSku.optionValues.length > 0) {
      const newResolvedOptions: Record<string, string> = {};
      bestSku.optionValues.forEach((ov) => {
        newResolvedOptions[ov.optionValue.optionId] = ov.optionValue.id;
      });

      setSelectedOptions(newResolvedOptions);

      if (bestSku.imageUrl && onImageChange) {
        onImageChange(bestSku.imageUrl);
      }
    }
  };

  const selectedSku = useMemo(() => {
    if (Object.keys(selectedOptions).length < options.length) return null;

    return skus.find((sku) => {
      if (!sku.optionValues) return false;
      return sku.optionValues.every((ov) => {
        return selectedOptions[ov.optionValue.optionId] === ov.optionValue.id;
      });
    });
  }, [selectedOptions, skus, options]);

  useEffect(() => {
    const currentId = selectedSku?.id;
    if (currentId !== lastNotifiedSkuId.current) {
      lastNotifiedSkuId.current = currentId;
      if (onSkuChange) {
        onSkuChange(selectedSku || null);
      }
    }
  }, [selectedSku, onSkuChange]);

  const getOptionValueStatus = (optionId: string, valueId: string) => {
    const relevantSkus = skus.filter((sku) => {
      return sku.optionValues?.some((ov) => ov.optionValue.id === valueId);
    });

    if (relevantSkus.length === 0) return "unavailable";
    if (relevantSkus.every((s) => s.stock <= 0)) return "out_of_stock";

    return "available";
  };

  const price = selectedSku ? selectedSku.price : skus[0]?.price;
  const isOutOfStock = selectedSku ? selectedSku.stock <= 0 : false;

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-3xl font-bold bg-clip-text text-transparent bg-linear-to-r from-primary to-primary/60">
          {formatCurrency(Number(price) || 0)}
        </h2>
        {selectedSku && (
          <div className="flex items-center gap-2 mt-2">
            <div
              className={cn(
                "w-2 h-2 rounded-full",
                selectedSku.stock > 0 ? "bg-emerald-500" : "bg-destructive"
              )}
            />
            <span
              className={cn(
                "text-sm font-medium",
                selectedSku.stock > 0 ? "text-emerald-600" : "text-destructive"
              )}
            >
              {selectedSku.stock > 0
                ? `Available: ${selectedSku.stock}`
                : "Out of Stock"}
            </span>
          </div>
        )}
      </div>

      <div className="space-y-3">
        {options.map((option) => (
          <div key={option.id}>
            <h3 className="text-sm font-bold mb-3 uppercase tracking-widest text-muted-foreground/80">
              {option.name}
            </h3>
            <div className="flex flex-wrap gap-3">
              {option.values.map((value) => {
                const status = getOptionValueStatus(option.id, value.id);
                const isSelected = selectedOptions[option.id] === value.id;

                return (
                  <Badge
                    key={value.id}
                    variant={isSelected ? "default" : "outline"}
                    className={cn(
                      "cursor-pointer px-5 py-2.5 text-sm border transition-all duration-300 backdrop-blur-md",
                      isSelected
                        ? "border-primary bg-primary text-primary-foreground hover:bg-primary/90 font-bold shadow-[0_0_15px_rgba(var(--primary),0.3)]"
                        : "border-gray-200 dark:border-white/10 bg-transparent hover:bg-gray-100 dark:hover:bg-white/10 text-foreground dark:text-white hover:border-primary/50 hover:text-primary",
                      status === "unavailable" &&
                        "opacity-30 cursor-not-allowed bg-transparent text-muted-foreground line-through decoration-white/20",
                      status === "out_of_stock" &&
                        "opacity-50 cursor-not-allowed border-red-500/30 text-red-400"
                    )}
                    onClick={() => {
                      handleSelect(option.id, value.id);
                    }}
                  >
                    {value.value}
                  </Badge>
                );
              })}
            </div>
          </div>
        ))}
      </div>

      <div className="flex flex-col sm:flex-row gap-4 pt-4 border-t border-white/5">
        <GlassButton
          id="add-to-cart-btn"
          className="flex-1 w-full"
          variant="primary"
          size="lg"
          disabled={!selectedSku || isOutOfStock || isAdding}
          onClick={onAddToCart}
        >
          {isAdding
            ? "Adding..."
            : isOutOfStock
            ? "Out of Stock"
            : "Add to Cart"}
        </GlassButton>
        {showBuyNow && (
          <GlassButton
            className="flex-1 w-full border-primary text-primary hover:bg-primary/5"
            variant="outline"
            size="lg"
            onClick={() => {
              if (onAddToCart) {
                onAddToCart();
                setTimeout(() => router.push("/cart"), 500);
              }
            }}
            disabled={!selectedSku || isOutOfStock}
          >
            Buy Now
          </GlassButton>
        )}
      </div>

      {selectedSku && isOutOfStock && (
        <p className="text-destructive text-sm font-medium flex items-center gap-2">
          <span className="w-2 h-2 rounded-full bg-destructive animate-pulse"></span>
          Item is currently out of stock
        </p>
      )}
    </div>
  );
}

"use client";

import { AnimatePresence, motion } from "framer-motion";
import { ShoppingBag, X } from "lucide-react";
import { useCallback, useEffect, useState } from "react";

/**
 * =====================================================================
 * SOCIAL PROOF TOAST - Thông báo mua hàng thời gian thực
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. FOMO (Fear Of Missing Out):
 * - Hiển thị các thông báo mua hàng giả lập (hoặc thật qua WebSocket) để tạo cảm giác cửa hàng đang rất nhộn nhịp.
 * - Giúp khách hàng mới cảm thấy yên tâm hơn khi thấy nhiều người khác cũng đang mua sắm.
 *
 * 2. ANIMATE PRESENCE:
 * - Sử dụng `AnimatePresence` từ Framer Motion để xử lý animation khi component bị gỡ bỏ khỏi DOM (`exit` animation).
 * - `initial`: Trạng thái bắt đầu (trượt từ trái sang).
 * - `animate`: Trạng thái hiển thị.
 * - `exit`: Trạng thái khi biến mất.
 *
 * 3. NOTIFICATION CYCLE:
 * - Sử dụng `setTimeout` lồng nhau để tạo chu kỳ: Hiện 5s -> Nghỉ 15-25s -> Hiện cái tiếp theo.
 * - Khoảng nghỉ ngẫu nhiên (`Math.random()`) giúp thông báo trông "thật" hơn, không bị máy móc.
 * =====================================================================
 */
interface PurchaseNotification {
  id: string;
  customerName: string;
  productName: string;
  location: string;
  timeAgo: string;
}

// Fake purchase data - Trong thực tế sẽ lấy từ WebSocket hoặc API
const fakePurchases: PurchaseNotification[] = [
  {
    id: "1",
    customerName: "Nguyễn V.",
    productName: "Silk Evening Dress",
    location: "Hà Nội",
    timeAgo: "2 phút trước",
  },
  {
    id: "2",
    customerName: "Trần M.",
    productName: "Premium Leather Bag",
    location: "TP.HCM",
    timeAgo: "5 phút trước",
  },
  {
    id: "3",
    customerName: "Lê H.",
    productName: "Classic White Sneakers",
    location: "Đà Nẵng",
    timeAgo: "8 phút trước",
  },
  {
    id: "4",
    customerName: "Phạm T.",
    productName: "Wool Cashmere Coat",
    location: "Hải Phòng",
    timeAgo: "12 phút trước",
  },
  {
    id: "5",
    customerName: "Hoàng A.",
    productName: "Designer Sunglasses",
    location: "Cần Thơ",
    timeAgo: "15 phút trước",
  },
];

export function SocialProofToast() {
  const [currentNotification, setCurrentNotification] =
    useState<PurchaseNotification | null>(null);
  const [isVisible, setIsVisible] = useState(false);
  const [notificationIndex, setNotificationIndex] = useState(0);

  const showNextNotification = useCallback(() => {
    setNotificationIndex((prev) => {
      const nextIndex = (prev + 1) % fakePurchases.length;
      setCurrentNotification(fakePurchases[nextIndex]);
      setIsVisible(true);
      return nextIndex;
    });
  }, []);

  useEffect(() => {
    // Delay ban đầu 10 giây trước khi hiển thị notification đầu tiên
    const initialDelay = setTimeout(() => {
      showNextNotification();
    }, 10000);

    return () => clearTimeout(initialDelay);
  }, [showNextNotification]);

  useEffect(() => {
    if (isVisible) {
      // Tự động ẩn sau 5 giây
      const hideTimer = setTimeout(() => {
        setIsVisible(false);
      }, 5000);

      // Hiển thị notification tiếp theo sau 15-25 giây
      const nextTimer = setTimeout(() => {
        showNextNotification();
      }, 15000 + Math.random() * 10000);

      return () => {
        clearTimeout(hideTimer);
        clearTimeout(nextTimer);
      };
    }
  }, [isVisible, showNextNotification]);

  const handleClose = () => {
    setIsVisible(false);
  };

  return (
    <AnimatePresence>
      {isVisible && currentNotification && (
        <motion.div
          initial={{ opacity: 0, x: -100, y: 20 }}
          animate={{ opacity: 1, x: 0, y: 0 }}
          exit={{ opacity: 0, x: -100 }}
          transition={{ type: "spring", stiffness: 300, damping: 25 }}
          className="fixed bottom-24 md:bottom-6 left-4 md:left-6 z-50 max-w-sm"
        >
          <div className="bg-white dark:bg-card rounded-xl shadow-2xl border border-neutral-200 dark:border-white/10 p-4 flex items-start gap-3">
            {/* Icon */}
            <div className="shrink-0 w-10 h-10 bg-emerald-500/10 rounded-full flex items-center justify-center">
              <ShoppingBag className="w-5 h-5 text-emerald-600" />
            </div>

            {/* Content */}
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-foreground">
                {currentNotification.customerName} từ{" "}
                {currentNotification.location}
              </p>
              <p className="text-xs text-muted-foreground mt-0.5">
                đã mua{" "}
                <span className="font-medium text-foreground">
                  {currentNotification.productName}
                </span>
              </p>
              <p className="text-xs text-emerald-600 dark:text-emerald-400 mt-1">
                {currentNotification.timeAgo}
              </p>
            </div>

            {/* Close Button */}
            <button
              onClick={handleClose}
              className="shrink-0 p-1 rounded-full hover:bg-muted transition-colors"
            >
              <X className="w-4 h-4 text-muted-foreground" />
            </button>
          </div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

"use client";

import { Star } from "lucide-react";
import Image from "next/image";

/**
 * =====================================================================
 * REVIEW PREVIEW - Hiển thị đánh giá và bằng chứng xã hội
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. SOCIAL PROOF (Bằng chứng xã hội):
 * - Rating và Review là yếu tố then chốt để tăng tỷ lệ chuyển đổi (Conversion Rate).
 * - Hiển thị tên và ảnh của người review thật giúp tăng độ tin cậy.
 *
 * 2. STAR RENDERING LOGIC:
 * - `fullStars`: Số lượng sao vàng nguyên vẹn.
 * - `hasHalfStar`: Kiểm tra nếu phần dư >= 0.5 để hiển thị nửa ngôi sao.
 * - Kỹ thuật hiển thị nửa sao: Sử dụng `relative` container và `overflow-hidden` trên một layer sao vàng đè lên sao xám.
 *
 * 3. UI OPTIMIZATION:
 * - `line-clamp-2`: Giới hạn nội dung review tối đa 2 dòng để không làm vỡ layout của Product Card.
 * - `CompactRating`: Một phiên bản rút gọn dùng cho các không gian hẹp.
 * =====================================================================
 */
interface ReviewPreviewProps {
  rating: number;
  reviewCount: number;
  previewText?: string;
  reviewerName?: string;
  reviewerImage?: string;
  className?: string;
}

export function ReviewPreview({
  rating,
  reviewCount,
  previewText,
  reviewerName,
  reviewerImage,
  className,
}: ReviewPreviewProps) {
  // Render stars
  const renderStars = () => {
    const stars = [];
    const fullStars = Math.floor(rating);
    const hasHalfStar = rating % 1 >= 0.5;

    for (let i = 0; i < 5; i++) {
      if (i < fullStars) {
        stars.push(
          <Star key={i} className="w-3.5 h-3.5 fill-amber-400 text-amber-400" />
        );
      } else if (i === fullStars && hasHalfStar) {
        stars.push(
          <div key={i} className="relative">
            <Star className="w-3.5 h-3.5 text-amber-400" />
            <div className="absolute inset-0 overflow-hidden w-1/2">
              <Star className="w-3.5 h-3.5 fill-amber-400 text-amber-400" />
            </div>
          </div>
        );
      } else {
        stars.push(
          <Star key={i} className="w-3.5 h-3.5 text-muted-foreground/30" />
        );
      }
    }
    return stars;
  };

  return (
    <div className={className}>
      {/* Rating Summary */}
      <div className="flex items-center gap-1.5">
        <div className="flex items-center gap-0.5">{renderStars()}</div>
        <span className="text-sm font-medium text-foreground">
          {rating.toFixed(1)}
        </span>
        <span className="text-xs text-muted-foreground">({reviewCount})</span>
      </div>

      {/* Review Preview */}
      {previewText && (
        <div className="mt-2 p-2.5 bg-muted/30 rounded-lg border border-white/5">
          <p className="text-xs text-muted-foreground line-clamp-2 italic">
            "{previewText}"
          </p>
          {reviewerName && (
            <div className="flex items-center gap-2 mt-2">
              {reviewerImage ? (
                <Image
                  src={reviewerImage}
                  alt={reviewerName}
                  width={20}
                  height={20}
                  className="rounded-full"
                />
              ) : (
                <div className="w-5 h-5 rounded-full bg-primary/20 flex items-center justify-center text-[10px] font-bold text-primary">
                  {reviewerName.charAt(0)}
                </div>
              )}
              <span className="text-[10px] text-muted-foreground font-medium">
                {reviewerName}
              </span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * CompactRating - Phiên bản nhỏ gọn chỉ hiển thị stars và số
 */
export function CompactRating({
  rating,
  reviewCount,
  className,
}: {
  rating: number;
  reviewCount: number;
  className?: string;
}) {
  return (
    <div className={`flex items-center gap-1 ${className}`}>
      <Star className="w-3.5 h-3.5 fill-amber-400 text-amber-400" />
      <span className="text-xs font-medium text-foreground">
        {rating.toFixed(1)}
      </span>
      <span className="text-xs text-muted-foreground">({reviewCount})</span>
    </div>
  );
}

