  );
}

"use client";

import { createCategoryAction } from "@/actions/admin";
import { FormDialog } from "@/components/atoms/form-dialog";
import { ImageUpload } from "@/components/atoms/image-upload";
import { Input } from "@/components/atoms/input";
import { Label } from "@/components/atoms/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/atoms/select";
import { useToast } from "@/hooks/use-toast";
import { Category } from "@/types/models";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslations } from "next-intl";
import { useState, useTransition } from "react";

interface CreateCategoryDialogProps {
  categories: Category[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function CreateCategoryDialog({
  categories,
  open,
  onOpenChange,
}: CreateCategoryDialogProps) {
  const t = useTranslations("admin");
  const { toast } = useToast();
  const [isPending, startTransition] = useTransition();
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const [parentId, setParentId] = useState<string>("");
  const [image, setImage] = useState<File | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleNameChange = (value: string) => {
    setName(value);
    if (errors.name) setErrors((prev) => ({ ...prev, name: "" }));
    // Tự động tạo slug từ tên
    const generatedSlug = value
      .toLowerCase()
      .replace(/\s+/g, "-")
      .replace(/[^a-z0-9-]/g, "");
    setSlug(generatedSlug);
    if (errors.slug) setErrors((prev) => ({ ...prev, slug: "" }));
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!name.trim()) {
      newErrors.name = t("categories.errorNameRequired");
    }
    if (!slug.trim()) {
      newErrors.slug = t("categories.errorNameRequired");
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) return;

    // Gọi server action
    startTransition(async () => {
      const formData = new FormData();
      formData.append("name", name.trim());
      formData.append("slug", slug.trim());
      if (parentId && parentId !== "none") {
        formData.append("parentId", parentId);
      }
      if (image) formData.append("image", image);

      const result = await createCategoryAction(formData as any);
      if (result.success) {
        toast({
          variant: "success",
          title: t("success"),
          description: t("categories.successCreate"),
        });
        // Reset form
        setName("");
        setSlug("");
        setParentId("");
        setImage(null);
        onOpenChange(false);
      } else {
        toast({
          title: t("error"),
          description: result.error,
          variant: "destructive",
        });
      }
    });
  };

  return (
    <FormDialog
      open={open}
      onOpenChange={onOpenChange}
      title={t("categories.createNew")}
      description={t("categories.description")}
      onSubmit={handleSubmit}
      isPending={isPending}
      submitLabel={t("create")}
      disabled={!name.trim() || !slug.trim()}
    >
      <div className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="name">{t("categories.nameLabel")}</Label>
          <Input
            id="name"
            placeholder={t("categories.placeholder")}
            value={name}
            onChange={(e) => handleNameChange(e.target.value)}
            disabled={isPending}
            className={errors.name ? "border-destructive" : ""}
          />
          <AnimatePresence>
            {errors.name && (
              <motion.p
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="text-xs text-destructive"
              >
                {errors.name}
              </motion.p>
            )}
          </AnimatePresence>
        </div>
        <div className="space-y-2">
          <Label htmlFor="slug">{t("categories.slugLabel")}</Label>
          <Input
            id="slug"
            placeholder={t("categories.slugPlaceholder")}
            value={slug}
            onChange={(e) => {
              setSlug(e.target.value);
              if (errors.slug) setErrors((prev) => ({ ...prev, slug: "" }));
            }}
            disabled={isPending}
            className={errors.slug ? "border-destructive" : ""}
          />
          <AnimatePresence>
            {errors.slug && (
              <motion.p
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="text-xs text-destructive"
              >
                {errors.slug}
              </motion.p>
            )}
          </AnimatePresence>
          <p className="text-sm text-gray-500">{t("categories.slugHint")}</p>
        </div>
        <div className="space-y-2">
          <Label htmlFor="parentId">{t("categories.parentLabel")}</Label>
          <Select
            value={parentId}
            onValueChange={setParentId}
            disabled={isPending}
          >
            <SelectTrigger>
              <SelectValue placeholder={t("categories.selectParent")} />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="none">{t("categories.noneRoot")}</SelectItem>
              {categories.map((cat) => (
                <SelectItem key={cat.id} value={cat.id}>
                  {cat.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>{t("categories.imageLabel")}</Label>
          <ImageUpload
            onChange={setImage}
            onRemove={() => setImage(null)}
            disabled={isPending}
          />
        </div>
      </div>
    </FormDialog>
  );
}

"use client";

import { createCouponAction } from "@/actions/admin";
import { FormDialog } from "@/components/atoms/form-dialog";
import { Input } from "@/components/atoms/input";
import { Label } from "@/components/atoms/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/atoms/select";
import { useToast } from "@/hooks/use-toast";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslations } from "next-intl";
import { useState, useTransition } from "react";

/**
 * =====================================================================
 * CREATE COUPON DIALOG - Dialog tạo mã giảm giá mới
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. COMPLEX FORM STATE:
 * - Quản lý nhiều trường dữ liệu: code, loại giảm giá (%, cố định), giá trị, hạn mức, ngày bắt đầu/kết thúc.
 * - Sử dụng một object `formData` duy nhất để quản lý tất cả các trường.
 *
 * 2. DATE HANDLING:
 * - Sử dụng `datetime-local` input để chọn thời gian chính xác.
 * - Chuyển đổi sang `ISOString` trước khi gửi về server.
 *
 * 3. VALIDATION:
 * - Kiểm tra kỹ các trường bắt buộc và định dạng dữ liệu trước khi gọi API.
 * =====================================================================
 */

interface CreateCouponDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function CreateCouponDialog({
  open,
  onOpenChange,
}: CreateCouponDialogProps) {
  const t = useTranslations("admin");
  const [isPending, startTransition] = useTransition();
  const { toast } = useToast();
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [formData, setFormData] = useState({
    code: "",
    discountType: "PERCENTAGE" as "PERCENTAGE" | "FIXED_AMOUNT",
    discountValue: "",
    minOrderAmount: "",
    maxDiscountAmount: "",
    startDate: "",
    endDate: "",
    usageLimit: "",
  });

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.code.trim()) newErrors.code = t("coupons.errorCodeRequired");
    if (!formData.discountValue)
      newErrors.discountValue = t("coupons.errorValueRequired");
    if (!formData.startDate)
      newErrors.startDate = t("coupons.errorStartDateRequired");
    if (!formData.endDate)
      newErrors.endDate = t("coupons.errorEndDateRequired");

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  async function onSubmit(event: React.FormEvent) {
    event.preventDefault();

    if (!validate()) return;

    const data = {
      code: formData.code.trim(),
      discountType: formData.discountType,
      discountValue: Number(formData.discountValue),
      minOrderAmount: formData.minOrderAmount
        ? Number(formData.minOrderAmount)
        : undefined,
      maxDiscountAmount: formData.maxDiscountAmount
        ? Number(formData.maxDiscountAmount)
        : undefined,
      startDate: new Date(formData.startDate).toISOString(),
      endDate: new Date(formData.endDate).toISOString(),
      usageLimit: formData.usageLimit ? Number(formData.usageLimit) : undefined,
    };

    startTransition(async () => {
      const result = await createCouponAction(data as any);
      if (result.success) {
        toast({ title: t("success"), description: t("coupons.successCreate") });
        // Reset form
        setFormData({
          code: "",
          discountType: "PERCENTAGE",
          discountValue: "",
          minOrderAmount: "",
          maxDiscountAmount: "",
          startDate: "",
          endDate: "",
          usageLimit: "",
        });
        onOpenChange(false);
      } else {
        toast({
          title: t("error"),
          description: result.error,
          variant: "destructive",
        });
      }
    });
  }

  return (
    <FormDialog
      open={open}
      onOpenChange={onOpenChange}
      title={t("coupons.createNew")}
      description={t("coupons.description")}
      onSubmit={onSubmit}
      isPending={isPending}
      submitLabel={t("coupons.createNew")}
      maxWidth="sm:max-w-xl"
    >
      <div className="grid gap-4 py-4">
        <div className="grid gap-2">
          <Label htmlFor="code">{t("coupons.codeLabel")}</Label>
          <Input
            id="code"
            name="code"
            placeholder={t("coupons.codePlaceholder")}
            value={formData.code}
            onChange={(e) => {
              setFormData({ ...formData, code: e.target.value });
              if (errors.code) setErrors({ ...errors, code: "" });
            }}
            className={errors.code ? "border-destructive" : ""}
          />
          <AnimatePresence>
            {errors.code && (
              <motion.p
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="text-xs text-destructive"
              >
                {errors.code}
              </motion.p>
            )}
          </AnimatePresence>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="grid gap-2">
            <Label htmlFor="discountType">{t("coupons.typeLabel")}</Label>
            <Select
              name="discountType"
              value={formData.discountType}
              onValueChange={(value) =>
                setFormData({
                  ...formData,
                  discountType: value as "PERCENTAGE" | "FIXED_AMOUNT",
                })
              }
            >
              <SelectTrigger id="discountType">
                <SelectValue placeholder={t("coupons.typeLabel")} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="PERCENTAGE">
                  {t("coupons.percentage")}
                </SelectItem>
                <SelectItem value="FIXED_AMOUNT">
                  {t("coupons.fixedAmount")}
                </SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="grid gap-2">
            <Label htmlFor="discountValue">{t("coupons.valueLabel")}</Label>
            <Input
              id="discountValue"
              name="discountValue"
              type="number"
              placeholder={t("coupons.valuePlaceholder")}
              value={formData.discountValue}
              onChange={(e) => {
                setFormData({ ...formData, discountValue: e.target.value });
                if (errors.discountValue)
                  setErrors({ ...errors, discountValue: "" });
              }}
              className={errors.discountValue ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.discountValue && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.discountValue}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="grid gap-2">
            <Label htmlFor="minOrderAmount">{t("coupons.minOrderLabel")}</Label>
            <Input
              id="minOrderAmount"
              name="minOrderAmount"
              type="number"
              placeholder={t("coupons.minOrderPlaceholder")}
              value={formData.minOrderAmount}
              onChange={(e) =>
                setFormData({ ...formData, minOrderAmount: e.target.value })
              }
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="maxDiscountAmount">
              {t("coupons.maxDiscountLabel")}
            </Label>
            <Input
              id="maxDiscountAmount"
              name="maxDiscountAmount"
              type="number"
              placeholder={t("optional")}
              value={formData.maxDiscountAmount}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  maxDiscountAmount: e.target.value,
                })
              }
            />
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="grid gap-2">
            <Label htmlFor="startDate">{t("coupons.startDateLabel")}</Label>
            <Input
              id="startDate"
              name="startDate"
              type="datetime-local"
              value={formData.startDate}
              onChange={(e) => {
                setFormData({ ...formData, startDate: e.target.value });
                if (errors.startDate) setErrors({ ...errors, startDate: "" });
              }}
              className={errors.startDate ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.startDate && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.startDate}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
          <div className="grid gap-2">
            <Label htmlFor="endDate">{t("coupons.endDateLabel")}</Label>
            <Input
              id="endDate"
              name="endDate"
              type="datetime-local"
              value={formData.endDate}
              onChange={(e) => {
                setFormData({ ...formData, endDate: e.target.value });
                if (errors.endDate) setErrors({ ...errors, endDate: "" });
              }}
              className={errors.endDate ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.endDate && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.endDate}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </div>
        <div className="grid gap-2">
          <Label htmlFor="usageLimit">{t("coupons.usageLimitLabel")}</Label>
          <Input
            id="usageLimit"
            name="usageLimit"
            type="number"
            placeholder={t("optional")}
            value={formData.usageLimit}
            onChange={(e) =>
              setFormData({ ...formData, usageLimit: e.target.value })
            }
          />
        </div>
      </div>
    </FormDialog>
  );
}

"use client";

import { createProductAction } from "@/actions/admin";
import { Button } from "@/components/atoms/button";
import { FormDialog } from "@/components/atoms/form-dialog";
import { Input } from "@/components/atoms/input";
import { Label } from "@/components/atoms/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/atoms/select";
import { Textarea } from "@/components/atoms/textarea";
import { useToast } from "@/hooks/use-toast";
import { toSlug } from "@/lib/utils";
import {
  useAdminBrands,
  useAdminCategories,
} from "@/providers/admin-metadata-provider";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslations } from "next-intl";
import { useState, useTransition } from "react";

/**
 * =====================================================================
 * CREATE PRODUCT DIALOG - Dialog tạo sản phẩm mới (Phức tạp)
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. DYNAMIC OPTIONS:
 * - Cho phép Admin thêm không giới hạn các tùy chọn sản phẩm (VD: Màu sắc, Kích thước).
 * - Mỗi tùy chọn có thể có nhiều giá trị (VD: Đỏ, Xanh, Lớn, Nhỏ).
 *
 * 2. METADATA PROVIDERS:
 * - Sử dụng `useAdminBrands` và `useAdminCategories` để lấy danh sách thương hiệu/danh mục mà không cần fetch lại nhiều lần.
 *
 * 3. SLUG PREVIEW:
 * - Hiển thị gợi ý slug dựa trên tên sản phẩm đang nhập để Admin dễ hình dung URL.
 * =====================================================================
 */

interface CreateProductDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

interface UiOption {
  name: string;
  values: string[];
}

export function CreateProductDialog({
  open,
  onOpenChange,
}: CreateProductDialogProps) {
  const t = useTranslations("admin");
  const { brands } = useAdminBrands();
  const { categories } = useAdminCategories();
  const { toast } = useToast();
  const [isPending, startTransition] = useTransition();
  const [isLoading, setIsLoading] = useState(false); // Manual loading state
  const [errors, setErrors] = useState<Record<string, string>>({});

  const [formData, setFormData] = useState({
    name: "",
    slug: "",
    description: "",
    categoryId: "",
    brandId: "",
  });

  const [options, setOptions] = useState<UiOption[]>([
    { name: t("products.optionColor"), values: [] },
    { name: t("products.optionStatus"), values: [] },
  ]);

  const handleAddOption = () => {
    setOptions([...options, { name: "", values: [] }]);
  };

  const handleRemoveOption = (index: number) => {
    const newOptions = [...options];
    newOptions.splice(index, 1);
    setOptions(newOptions);
  };

  const handleOptionNameChange = (index: number, value: string) => {
    const newOptions = [...options];
    newOptions[index].name = value;
    setOptions(newOptions);
  };

  const handleAddValue = (optionIndex: number, value: string) => {
    if (!value.trim()) return;
    const newOptions = [...options];
    newOptions[optionIndex].values.push(value);
    setOptions(newOptions);
  };

  const handleRemoveValue = (optionIndex: number, valueIndex: number) => {
    const newOptions = [...options];
    newOptions[optionIndex].values.splice(valueIndex, 1);
    setOptions(newOptions);
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) newErrors.name = t("products.errorNameRequired");
    if (!formData.categoryId)
      newErrors.categoryId = t("products.errorCategoryRequired");
    if (!formData.brandId) newErrors.brandId = t("products.errorBrandRequired");

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) return;

    // Lọc bỏ các tùy chọn trống
    const validOptions = options.filter(
      (opt) => opt.name.trim() !== "" && opt.values.length > 0
    );

    const payload = {
      ...formData,
      options: validOptions,
    };

    setIsLoading(true);
    startTransition(async () => {
      const result = await createProductAction(payload as any);
      if (result.success) {
        toast({
          variant: "success",
          title: t("success"),
          description: t("products.successCreate"),
        });
        onOpenChange(false);
        // Do NOT set isLoading(false) here to avoid flicker while closing
      } else {
        toast({
          title: t("error"),
          description: result.error,
          variant: "destructive",
        });
        setIsLoading(false);
      }
    });
  };

  return (
    <FormDialog
      open={open}
      onOpenChange={onOpenChange}
      title={t("products.createNew")}
      onSubmit={handleSubmit}
      isPending={isLoading}
      submitLabel={t("create")}
      maxWidth="max-w-2xl"
    >
      <div className="space-y-4">
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="name">{t("products.nameLabel")}</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => {
                setFormData({ ...formData, name: e.target.value });
                if (errors.name) setErrors({ ...errors, name: "" });
              }}
              disabled={isLoading}
              className={errors.name ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.name && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.name}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
          <div className="space-y-2">
            <Label htmlFor="slug">{t("products.slugLabel")}</Label>
            <Input
              id="slug"
              value={formData.slug}
              onChange={(e) =>
                setFormData({ ...formData, slug: e.target.value })
              }
              placeholder={
                formData.name
                  ? toSlug(formData.name)
                  : t("products.slugPlaceholder")
              }
              disabled={isLoading}
            />
          </div>
        </div>

        <div className="space-y-2">
          <Label htmlFor="description">{t("products.descriptionLabel")}</Label>
          <Textarea
            id="description"
            value={formData.description}
            onChange={(e) =>
              setFormData({ ...formData, description: e.target.value })
            }
            disabled={isLoading}
          />
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label htmlFor="category">{t("products.categoryLabel")}</Label>
            <Select
              value={formData.categoryId}
              onValueChange={(value) => {
                setFormData({ ...formData, categoryId: value });
                if (errors.categoryId) setErrors({ ...errors, categoryId: "" });
              }}
              disabled={isLoading}
            >
              <SelectTrigger
                className={errors.categoryId ? "border-destructive" : ""}
              >
                <SelectValue placeholder={t("products.selectCategory")} />
              </SelectTrigger>
              <SelectContent>
                {categories.map((c) => (
                  <SelectItem key={c.id} value={c.id}>
                    {c.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <AnimatePresence>
              {errors.categoryId && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.categoryId}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
          <div className="space-y-2">
            <Label htmlFor="brand">{t("products.brandLabel")}</Label>
            <Select
              value={formData.brandId}
              onValueChange={(value) => {
                setFormData({ ...formData, brandId: value });
                if (errors.brandId) setErrors({ ...errors, brandId: "" });
              }}
              disabled={isLoading}
            >
              <SelectTrigger
                className={errors.brandId ? "border-destructive" : ""}
              >
                <SelectValue placeholder={t("products.selectBrand")} />
              </SelectTrigger>
              <SelectContent>
                {brands.map((b) => (
                  <SelectItem key={b.id} value={b.id}>
                    {b.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <AnimatePresence>
              {errors.brandId && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.brandId}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </div>

        <div className="space-y-4 border-t pt-4">
          <div className="flex justify-between items-center">
            <Label className="text-base font-semibold">
              {t("products.optionsLabel")}
            </Label>
            <Button
              type="button"
              variant="outline"
              size="sm"
              onClick={handleAddOption}
              disabled={isLoading}
            >
              {t("products.addOption")}
            </Button>
          </div>

          {options.map((option, optIndex) => (
            <div
              key={optIndex}
              className="p-4 border rounded-md space-y-3 bg-gray-50"
