  category: Category;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function EditCategoryDialog({
  categories,
  category,
  open,
  onOpenChange,
}: EditCategoryDialogProps) {
  const t = useTranslations("admin");
  const { toast } = useToast();
