  const [slug, setSlug] = useState(category.slug);
  const [parentId, setParentId] = useState<string>(category.parentId || "none");
  const [image, setImage] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [isImageRemoved, setIsImageRemoved] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    setName(category.name);
    setSlug(category.slug);
    setParentId(category.parentId || "none");
    setImage(null);
    setImagePreview(null);
    setIsImageRemoved(false);
    setIsLoading(false);
  }, [category]);

  // Cleanup image preview URL when unmount or image changes
  useEffect(() => {
    return () => {
      if (imagePreview) URL.revokeObjectURL(imagePreview);
    };
  }, [imagePreview]);

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!name.trim()) {
      newErrors.name = t("categories.errorNameRequired");
    }
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const isDirty = useMemo(() => {
    return (
      name !== category.name ||
      slug !== category.slug ||
      parentId !== (category.parentId || "none") ||
      image !== null ||
      isImageRemoved
    );
  }, [
    name,
    category.name,
    slug,
    category.slug,
    parentId,
    category.parentId,
    image,
    isImageRemoved,
  ]);

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    if (!validate()) return;

    setIsLoading(true);
    startTransition(async () => {
      const formData = new FormData();
      formData.append("name", name);
      formData.append("slug", slug);
      if (parentId !== "none") {
        formData.append("parentId", parentId);
      }

      if (image) {
        formData.append("image", image);
      } else if (isImageRemoved) {
        formData.append("deleteImage", "true");
      }

      const result = await updateCategoryAction(category.id, formData as any);

      if (result.success) {
        toast({
          variant: "success",
          title: t("success"),
          description: t("categories.successUpdate"),
        });
        onOpenChange(false);
      } else {
        toast({
          title: t("error"),
          description: result.error,
          variant: "destructive",
        });
        setIsLoading(false);
      }
    });
  };

  return (
    <FormDialog
      open={open}
      onOpenChange={onOpenChange}
      title={t("categories.edit")}
      description={t("categories.editDescription")}
      onSubmit={onSubmit}
      isPending={isLoading}
      submitLabel={t("save")}
      maxWidth="sm:max-w-md"
      disabled={!name.trim() || !slug.trim() || !isDirty}
    >
      <div className="space-y-4 py-4">
        <div className="space-y-2">
          <Label htmlFor="name">{t("categories.nameLabel")}</Label>
          <Input
            id="name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              if (errors.name) setErrors((prev) => ({ ...prev, name: "" }));
            }}
            disabled={isLoading}
            className={errors.name ? "border-destructive" : ""}
          />
          <AnimatePresence>
            {errors.name && (
              <motion.p
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="text-xs text-destructive"
              >
                {errors.name}
              </motion.p>
            )}
          </AnimatePresence>
        </div>
        <div className="space-y-2">
          <Label htmlFor="slug">{t("categories.slugLabel")}</Label>
          <Input
            id="slug"
            value={slug}
            onChange={(e) => {
              setSlug(e.target.value);
              if (errors.slug) setErrors((prev) => ({ ...prev, slug: "" }));
            }}
            disabled={isLoading}
            className={errors.slug ? "border-destructive" : ""}
          />
          <AnimatePresence>
            {errors.slug && (
              <motion.p
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="text-xs text-destructive"
              >
                {errors.slug}
              </motion.p>
            )}
          </AnimatePresence>
        </div>
        <div className="space-y-2">
          <Label htmlFor="parentId">{t("categories.parentLabel")}</Label>
          <Select
            value={parentId}
            onValueChange={setParentId}
            disabled={isLoading}
          >
            <SelectTrigger>
              <SelectValue placeholder={t("categories.selectParent")} />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="none">{t("categories.noneRoot")}</SelectItem>
              {categories
                .filter((cat) => cat.id !== category.id)
                .map((cat) => (
                  <SelectItem key={cat.id} value={cat.id}>
                    {cat.name}
                  </SelectItem>
                ))}
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label>{t("categories.imageLabel")}</Label>
          <ImageUpload
            value={
              imagePreview ||
              (isImageRemoved ? undefined : category.imageUrl) ||
              undefined
            }
            onChange={(file) => {
              if (file) {
                setImage(file);
                const url = URL.createObjectURL(file);
                setImagePreview(url);
                setIsImageRemoved(false);
              }
            }}
            onRemove={() => {
              setImage(null);
              if (imagePreview) URL.revokeObjectURL(imagePreview);
              setImagePreview(null);
              setIsImageRemoved(true);
            }}
            disabled={isLoading}
          />
        </div>
      </div>
    </FormDialog>
  );
}

"use client";

import { updateCouponAction } from "@/actions/admin";
import { Checkbox } from "@/components/atoms/checkbox";
import { FormDialog } from "@/components/atoms/form-dialog";
import { Input } from "@/components/atoms/input";
import { Label } from "@/components/atoms/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/atoms/select";
import { useToast } from "@/hooks/use-toast";
import { Coupon } from "@/types/models";
import { AnimatePresence, motion } from "framer-motion";
import { useTranslations } from "next-intl";
import { useMemo, useState, useTransition } from "react";

/**
 * =====================================================================
 * EDIT COUPON DIALOG - Dialog chỉnh sửa mã giảm giá
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. DATE FORMATTING:
 * - `formatDate` giúp chuyển đổi format ngày từ server về định dạng mà input `datetime-local` có thể hiểu được (`YYYY-MM-DDTHH:mm`).
 *
 * 2. STATUS TOGGLE:
 * - Cho phép bật/tắt (Active/Inactive) mã giảm giá nhanh chóng thông qua Checkbox.
 * =====================================================================
 */

interface EditCouponDialogProps {
  coupon: Coupon;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function EditCouponDialog({
  coupon,
  open,
  onOpenChange,
}: EditCouponDialogProps) {
  const t = useTranslations("admin");
  const [isPending, startTransition] = useTransition();
  const { toast } = useToast();
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Format date for datetime-local input
  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    return new Date(date.getTime() - date.getTimezoneOffset() * 60000)
      .toISOString()
      .slice(0, 16);
  };

  const [formData, setFormData] = useState({
    code: coupon.code,
    discountType: coupon.discountType as "PERCENTAGE" | "FIXED_AMOUNT",
    discountValue: String(coupon.discountValue),
    minOrderAmount: String(coupon.minOrderAmount || ""),
    maxDiscountAmount: String(coupon.maxDiscountAmount || ""),
    startDate: formatDate(coupon.startDate),
    endDate: formatDate(coupon.endDate),
    usageLimit: String(coupon.usageLimit || ""),
    isActive: coupon.isActive,
  });

  // Reset form data when coupon changes
  useMemo(() => {
    setFormData({
      code: coupon.code,
      discountType: coupon.discountType as "PERCENTAGE" | "FIXED_AMOUNT",
      discountValue: String(coupon.discountValue),
      minOrderAmount: String(coupon.minOrderAmount || ""),
      maxDiscountAmount: String(coupon.maxDiscountAmount || ""),
      startDate: formatDate(coupon.startDate),
      endDate: formatDate(coupon.endDate),
      usageLimit: String(coupon.usageLimit || ""),
      isActive: coupon.isActive,
    });
  }, [coupon]);

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.code.trim()) newErrors.code = t("coupons.errorCodeRequired");
    if (!formData.discountValue)
      newErrors.discountValue = t("coupons.errorValueRequired");
    if (!formData.startDate)
      newErrors.startDate = t("coupons.errorStartDateRequired");
    if (!formData.endDate)
      newErrors.endDate = t("coupons.errorEndDateRequired");

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const isDirty = useMemo(() => {
    return (
      formData.code !== coupon.code ||
      formData.discountType !== coupon.discountType ||
      formData.discountValue !== String(coupon.discountValue) ||
      formData.minOrderAmount !== String(coupon.minOrderAmount || "") ||
      formData.maxDiscountAmount !== String(coupon.maxDiscountAmount || "") ||
      formData.startDate !== formatDate(coupon.startDate) ||
      formData.endDate !== formatDate(coupon.endDate) ||
      formData.usageLimit !== String(coupon.usageLimit || "") ||
      formData.isActive !== coupon.isActive
    );
  }, [formData, coupon]);

  async function onSubmit(event: React.FormEvent) {
    event.preventDefault();

    if (!validate()) return;

    const data = {
      code: formData.code.trim(),
      discountType: formData.discountType,
      discountValue: Number(formData.discountValue),
      minOrderAmount: formData.minOrderAmount
        ? Number(formData.minOrderAmount)
        : undefined,
      maxDiscountAmount: formData.maxDiscountAmount
        ? Number(formData.maxDiscountAmount)
        : undefined,
      startDate: new Date(formData.startDate).toISOString(),
      endDate: new Date(formData.endDate).toISOString(),
      usageLimit: formData.usageLimit ? Number(formData.usageLimit) : undefined,
      isActive: formData.isActive,
    };

    startTransition(async () => {
      const result = await updateCouponAction(coupon.id, data as any);
      if (result.success) {
        toast({ title: t("success"), description: t("coupons.successUpdate") });
        onOpenChange(false);
      } else {
        toast({
          title: t("error"),
          description: result.error,
          variant: "destructive",
        });
      }
    });
  }

  return (
    <FormDialog
      open={open}
      onOpenChange={onOpenChange}
      title={t("coupons.edit")}
      description={t("coupons.editDescription")}
      onSubmit={onSubmit}
      isPending={isPending}
      submitLabel={t("save")}
      maxWidth="sm:max-w-xl"
    >
      <div className="grid gap-4 py-4">
        <div className="grid gap-2">
          <Label htmlFor="code">{t("coupons.codeLabel")}</Label>
          <Input
            id="code"
            name="code"
            placeholder={t("coupons.codePlaceholder")}
            value={formData.code}
            onChange={(e) => {
              setFormData({ ...formData, code: e.target.value });
              if (errors.code) setErrors({ ...errors, code: "" });
            }}
            className={errors.code ? "border-destructive" : ""}
          />
          <AnimatePresence>
            {errors.code && (
              <motion.p
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                className="text-xs text-destructive"
              >
                {errors.code}
              </motion.p>
            )}
          </AnimatePresence>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="grid gap-2">
            <Label htmlFor="discountType">{t("coupons.typeLabel")}</Label>
            <Select
              name="discountType"
              value={formData.discountType}
              onValueChange={(value) =>
                setFormData({
                  ...formData,
                  discountType: value as "PERCENTAGE" | "FIXED_AMOUNT",
                })
              }
            >
              <SelectTrigger id="discountType">
                <SelectValue placeholder={t("coupons.typeLabel")} />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="PERCENTAGE">
                  {t("coupons.percentage")}
                </SelectItem>
                <SelectItem value="FIXED_AMOUNT">
                  {t("coupons.fixedAmount")}
                </SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="grid gap-2">
            <Label htmlFor="discountValue">{t("coupons.valueLabel")}</Label>
            <Input
              id="discountValue"
              name="discountValue"
              type="number"
              placeholder={t("coupons.valuePlaceholder")}
              value={formData.discountValue}
              onChange={(e) => {
                setFormData({ ...formData, discountValue: e.target.value });
                if (errors.discountValue)
                  setErrors({ ...errors, discountValue: "" });
              }}
              className={errors.discountValue ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.discountValue && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.discountValue}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="grid gap-2">
            <Label htmlFor="minOrderAmount">{t("coupons.minOrderLabel")}</Label>
            <Input
              id="minOrderAmount"
              name="minOrderAmount"
              type="number"
              placeholder={t("coupons.minOrderPlaceholder")}
              value={formData.minOrderAmount}
              onChange={(e) =>
                setFormData({ ...formData, minOrderAmount: e.target.value })
              }
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="maxDiscountAmount">
              {t("coupons.maxDiscountLabel")}
            </Label>
            <Input
              id="maxDiscountAmount"
              name="maxDiscountAmount"
              type="number"
              placeholder={t("optional")}
              value={formData.maxDiscountAmount}
              onChange={(e) =>
                setFormData({
                  ...formData,
                  maxDiscountAmount: e.target.value,
                })
              }
            />
          </div>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <div className="grid gap-2">
            <Label htmlFor="startDate">{t("coupons.startDateLabel")}</Label>
            <Input
              id="startDate"
              name="startDate"
              type="datetime-local"
              value={formData.startDate}
              onChange={(e) => {
                setFormData({ ...formData, startDate: e.target.value });
                if (errors.startDate) setErrors({ ...errors, startDate: "" });
              }}
              className={errors.startDate ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.startDate && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.startDate}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
          <div className="grid gap-2">
            <Label htmlFor="endDate">{t("coupons.endDateLabel")}</Label>
            <Input
              id="endDate"
              name="endDate"
              type="datetime-local"
              value={formData.endDate}
              onChange={(e) => {
                setFormData({ ...formData, endDate: e.target.value });
                if (errors.endDate) setErrors({ ...errors, endDate: "" });
              }}
              className={errors.endDate ? "border-destructive" : ""}
            />
            <AnimatePresence>
              {errors.endDate && (
                <motion.p
                  initial={{ opacity: 0, height: 0 }}
                  animate={{ opacity: 1, height: "auto" }}
                  exit={{ opacity: 0, height: 0 }}
                  className="text-xs text-destructive"
                >
                  {errors.endDate}
                </motion.p>
              )}
            </AnimatePresence>
          </div>
        </div>
        <div className="grid gap-2">
          <Label htmlFor="usageLimit">{t("coupons.usageLimitLabel")}</Label>
          <Input
            id="usageLimit"
            name="usageLimit"
            type="number"
            placeholder={t("optional")}
            value={formData.usageLimit}
            onChange={(e) =>
              setFormData({ ...formData, usageLimit: e.target.value })
            }
          />
        </div>
        <div className="flex items-center space-x-2">
          <Checkbox
            id="isActive"
            name="isActive"
            checked={formData.isActive}
            onCheckedChange={(checked) =>
              setFormData({ ...formData, isActive: !!checked })
            }
          />
          <Label htmlFor="isActive">{t("coupons.activeLabel")}</Label>
        </div>
      </div>
    </FormDialog>
  );
}

