"use client";

import { Badge } from "@/components/atoms/badge";
import { Button } from "@/components/atoms/button";
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuGroup,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/atoms/dropdown-menu";
import { useRouter } from "@/i18n/routing";
import { cn } from "@/lib/utils";
import {
    AlertTriangle,
    Bell,
    Check,
    Package,
    ShoppingCart,
} from "lucide-react";
import { useTranslations } from "next-intl";
import { useState } from "react";

interface Notification {
  id: string;
  type: "NEW_ORDER" | "LOW_STOCK" | "REVIEW" | "SYSTEM";
  title: string;
  message: string;
  isRead: boolean;
  link?: string;
  createdAt: string;
}

interface NotificationCenterProps {
  notifications: Notification[];
  onMarkRead?: (id: string) => void;
  onMarkAllRead?: () => void;
  onClear?: (id: string) => void;
}

/**
 * =====================================================================
 * NOTIFICATION CENTER - Trung tâm thông báo Admin
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. NOTIFICATION TYPES:
 * - NEW_ORDER: Có đơn hàng mới cần xử lý.
 * - LOW_STOCK: Sản phẩm sắp hết hàng (< 5 món).
 * - REVIEW: Có đánh giá mới từ khách hàng.
 * - SYSTEM: Thông báo hệ thống (cập nhật, bảo trì).
 *
 * 2. UNREAD BADGE:
 * - Hiển thị số lượng thông báo chưa đọc bằng badge đỏ.
 *
 * 3. QUICK ACTIONS:
 * - Mark as Read: Đánh dấu đã đọc từng thông báo.
 * - Mark All Read: Đánh dấu tất cả đã đọc.
 * - Navigate: Click vào thông báo để đi đến trang liên quan.
 * =====================================================================
 */

export function NotificationCenter({
  notifications,
  onMarkRead,
  onMarkAllRead,
  onClear,
}: NotificationCenterProps) {
  const t = useTranslations("admin");
  const tCommon = useTranslations("common");
  const router = useRouter();
  const [open, setOpen] = useState(false);

  const unreadCount = notifications.filter((n) => !n.isRead).length;

  const getIcon = (type: Notification["type"]) => {
    switch (type) {
      case "NEW_ORDER":
        return <ShoppingCart className="h-4 w-4 text-primary" />;
      case "LOW_STOCK":
        return <AlertTriangle className="h-4 w-4 text-amber-500" />;
      case "REVIEW":
        return <Package className="h-4 w-4 text-primary" />;
      default:
        return <Bell className="h-4 w-4 text-muted-foreground" />;
    }
  };

  const handleNotificationClick = (notification: Notification) => {
    if (notification.link) {
      router.push(notification.link as any);
    }
    if (!notification.isRead && onMarkRead) {
      onMarkRead(notification.id);
    }
    setOpen(false);
  };

  const formatTime = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return tCommon("justNow");
    if (diffMins < 60) return tCommon("mAgo", { count: diffMins });
    if (diffHours < 24) return tCommon("hAgo", { count: diffHours });
    return tCommon("dAgo", { count: diffDays });
  };

  return (
    <DropdownMenu open={open} onOpenChange={setOpen}>
      <DropdownMenuTrigger asChild>
        <Button
          variant="ghost"
          size="icon"
          className="relative"
          aria-label={t("notifications")}
        >
          <Bell className="h-5 w-5" />
          {unreadCount > 0 && (
            <Badge
              variant="destructive"
              className="absolute -top-1 -right-1 h-5 w-5 p-0 flex items-center justify-center text-xs"
            >
              {unreadCount > 9 ? "9+" : unreadCount}
            </Badge>
          )}
        </Button>
      </DropdownMenuTrigger>

      <DropdownMenuContent align="end" className="w-80">
        <DropdownMenuLabel className="flex items-center justify-between">
          <span>{t("notifications")}</span>
          {unreadCount > 0 && onMarkAllRead && (
            <Button
              variant="ghost"
              size="sm"
              className="h-auto p-1 text-xs text-muted-foreground hover:text-primary"
              onClick={() => onMarkAllRead()}
            >
              <Check className="h-3 w-3 mr-1" />
              {t("markAllRead")}
            </Button>
          )}
        </DropdownMenuLabel>
        <DropdownMenuSeparator />

        <DropdownMenuGroup className="max-h-[400px] overflow-auto">
          {notifications.length === 0 ? (
            <div className="p-4 text-center text-muted-foreground text-sm">
              {t("noNotifications")}
            </div>
          ) : (
            notifications.slice(0, 10).map((notification) => (
              <DropdownMenuItem
                key={notification.id}
                className={cn(
                  "flex items-start gap-3 p-3 cursor-pointer",
                  !notification.isRead && "bg-primary/5"
                )}
                onClick={() => handleNotificationClick(notification)}
              >
                <div className="flex-shrink-0 mt-0.5">
                  {getIcon(notification.type)}
                </div>
                <div className="flex-1 min-w-0">
                  <p
                    className={cn(
                      "text-sm truncate",
                      !notification.isRead && "font-medium"
                    )}
                  >
                    {notification.title}
                  </p>
                  <p className="text-xs text-muted-foreground line-clamp-2">
                    {notification.message}
                  </p>
                  <p className="text-xs text-muted-foreground mt-1">
                    {formatTime(notification.createdAt)}
                  </p>
                </div>
                {!notification.isRead && (
                  <div className="h-2 w-2 bg-primary rounded-full flex-shrink-0 mt-1.5" />
                )}
              </DropdownMenuItem>
            ))
          )}
        </DropdownMenuGroup>

        {notifications.length > 10 && (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuItem
              className="justify-center text-sm text-primary"
              onClick={() => {
                router.push("/admin/notifications" as any);
                setOpen(false);
              }}
            >
              {t("viewAllNotifications")}
            </DropdownMenuItem>
          </>
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { getOrderDetailsAction } from "@/actions/admin";
import { Badge } from "@/components/atoms/badge";
import { Button } from "@/components/atoms/button";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from "@/components/atoms/dialog";
import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from "@/components/atoms/table";
import { formatCurrency } from "@/lib/utils";
import { Order, OrderItem } from "@/types/models";
import { useTranslations } from "next-intl";
import Link from "next/link";
import { useEffect, useState } from "react";

/**
 * =====================================================================
 * ORDER DETAILS DIALOG - Xem chi tiết đơn hàng
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. COMPREHENSIVE DATA:
 * - Hiển thị 3 nhóm thông tin chính: Thông tin đơn hàng (ID, Ngày, Trạng thái), Thông tin khách hàng (Tên, SĐT, Địa chỉ) và Danh sách sản phẩm đã mua.
 *
 * 2. PRICE AT PURCHASE:
 * - Quan trọng: Hiển thị `priceAtPurchase` thay vì giá hiện tại của sản phẩm. Vì giá sản phẩm có thể thay đổi theo thời gian, nhưng hóa đơn phải giữ nguyên giá tại thời điểm khách đặt hàng.
 *
 * 3. UI COMPONENTS:
 * - Sử dụng `Table` để hiển thị danh sách sản phẩm một cách ngăn nắp.
 * - `Badge` giúp làm nổi bật trạng thái đơn hàng.
 * =====================================================================
 */

export function OrderDetailsDialog({
  orderId,
  open,
  onOpenChange,
}: {
  orderId: string | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}) {
  const t = useTranslations("admin");

  if (!open) return null;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="!max-w-5xl max-h-[85vh] flex flex-col p-0 gap-0">
        <DialogHeader className="p-6 pb-4 border-b">
          <DialogTitle>{t("orders.details")}</DialogTitle>
        </DialogHeader>
        <OrderDetailsContent orderId={orderId} onOpenChange={onOpenChange} />
      </DialogContent>
    </Dialog>
  );
}

function OrderDetailsContent({
  orderId,
  onOpenChange,
}: {
  orderId: string | null;
  onOpenChange: (open: boolean) => void;
}) {
  const t = useTranslations("admin");
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;
    if (orderId) {
      const fetchOrder = async () => {
        // Use a slight delay or just let it be async to avoid sync setState in effect
        // but actually, we can just check if we really need to set it here.
        // If we initialize loading based on orderId change, it might be better.
        setLoading(true);
        setError(null);
        try {
          const result = await getOrderDetailsAction(orderId);
          if (isMounted) {
            if (result.data) {
              setOrder(result.data);
            } else {
              setError(result.error || t("error"));
            }
          }
        } catch (err: unknown) {
          if (isMounted) setError(err instanceof Error ? err.message : t("error"));
        } finally {
          if (isMounted) setLoading(false);
        }
      };
      fetchOrder();
    }
    return () => { isMounted = false; };
  }, [orderId, t]);

  return (
    <>
      <div className="flex-1 overflow-y-auto p-6">
        {loading && <div className="py-8 text-center">{t("loading")}</div>}

        {error && <div className="py-8 text-center text-red-600">{error}</div>}

        {order && !loading && (
          <div className="space-y-8">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-4">
                <h3 className="font-semibold text-lg border-b pb-2">
                  {t("orders.info")}
                </h3>
                <div className="grid grid-cols-[100px_1fr] gap-2 text-sm">
                  <span className="font-medium text-gray-500">
                    {t("orders.idLabel")}:
                  </span>
                  <span className="font-mono">{order.id}</span>

                  <span className="font-medium text-gray-500">
                    {t("orders.dateLabel")}:
                  </span>
                  <span>{new Date(order.createdAt).toLocaleString()}</span>

                  <span className="font-medium text-gray-500">
                    {t("orders.statusLabel")}:
                  </span>
                  <span>
                    <Badge>{t(`orders.statusMapping.${order.status}` as any)}</Badge>
                  </span>

                  <span className="font-medium text-gray-500">
                    {t("orders.totalLabel")}:
                  </span>
                  <span className="font-semibold text-lg">
                    {formatCurrency(Number(order.totalAmount))}
                  </span>
                </div>
              </div>

              <div className="space-y-4">
                <h3 className="font-semibold text-lg border-b pb-2">
                  {t("orders.customerInfo")}
                </h3>
                <div className="grid grid-cols-[100px_1fr] gap-2 text-sm">
                  <span className="font-medium text-gray-500">
                    {t("orders.nameLabel")}:
                  </span>
                  <span>{order.recipientName || order.user?.firstName}</span>

                  <span className="font-medium text-gray-500">
                    {t("orders.emailLabel")}:
                  </span>
                  <span>{order.user?.email}</span>

                  <span className="font-medium text-gray-500">
                    {t("orders.phoneLabel")}:
                  </span>
                  <span>{order.phoneNumber}</span>

                  <span className="font-medium text-gray-500">
                    {t("orders.addressLabel")}:
                  </span>
                  <span>{order.shippingAddress}</span>
                </div>
              </div>
            </div>

            <div>
              <h3 className="font-semibold text-lg mb-4">{t("orders.items")}</h3>
              <div className="border rounded-lg overflow-hidden">
                <Table>
                  <TableHeader className="bg-gray-50">
                    <TableRow>
                      <TableHead>{t("orders.productLabel")}</TableHead>
                      <TableHead>{t("orders.skuLabel")}</TableHead>
                      <TableHead className="text-right">
                        {t("orders.priceLabel")}
                      </TableHead>
                      <TableHead className="text-right">
                        {t("orders.qtyLabel")}
                      </TableHead>
                      <TableHead className="text-right">
                        {t("orders.totalLabel")}
                      </TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {order.items?.map((item: OrderItem) => (
                      <TableRow key={item.id}>
                        <TableCell className="font-medium">
                          <Link
                            href={
                              `/products/${item.sku?.product?.id}?skuId=${item.sku?.id}` as any
                            }
                            target="_blank"
                            className="hover:underline text-primary"
                          >
                            {item.sku?.product?.name ||
                              t("orders.unknownProduct")}
                          </Link>
                        </TableCell>
                        <TableCell className="font-mono text-xs text-gray-500">
                          {item.sku?.skuCode}
                        </TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(Number(item.priceAtPurchase))}
                        </TableCell>
                        <TableCell className="text-right">
                          {item.quantity}
                        </TableCell>
                        <TableCell className="text-right font-medium">
                          {formatCurrency(Number(item.priceAtPurchase) * item.quantity)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            </div>
          </div>
        )}
      </div>

      <div className="p-6 pt-4 border-t flex justify-end bg-gray-50">
        <Button onClick={() => onOpenChange(false)}>{t("close")}</Button>
      </div>
    </>
  );
}

