import { useTranslations } from "next-intl";
import { useState } from "react";

/**
 * =====================================================================
 * NEWSLETTER FORM - Form đăng ký nhận tin
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. FORM HANDLING:
 * - Sử dụng `useState` để quản lý `email` và `status` (idle, loading, success, error).
 * - `noValidate`: Tắt validation mặc định của trình duyệt để dùng custom validation bằng JS.
 *
 * 2. API INTEGRATION:
 * - Sử dụng `httpClient` để gửi request POST lên server.
 * - Hiển thị `Loader2` (spinner) khi đang gửi request để báo hiệu cho người dùng.
 *
 * 3. SUCCESS STATE:
 * - Khi đăng ký thành công, ẩn form và hiển thị thông báo cảm ơn với hiệu ứng `animate-in`.
 * =====================================================================
 */

export function NewsletterForm() {
  const t = useTranslations("newsletter");
  const tToast = useTranslations("common.toast");
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState<
    "idle" | "loading" | "success" | "error"
  >("idle");
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Custom Validation
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email)) {
      toast({
        variant: "destructive",
        title: t("invalidInput"),
        description: t("invalidEmail"),
      });
      return;
    }

    setStatus("loading");

    try {
      const response = await fetch("/api/v1/newsletter/subscribe", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ email }),
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.message || "Failed to subscribe");
      }

      setStatus("success");
      setEmail("");
      toast({
        variant: "success",
        title: tToast("success"),
        description: t("successDesc"),
      });
    } catch (error: any) {
      setStatus("error");
      toast({
        variant: "destructive",
        title: tToast("error"),
        description: error.message || t("errorDesc"),
      });
    }
  };

  return (
    <div className="relative z-10 max-w-2xl mx-auto space-y-8">
      <div className="space-y-4 text-center">
        <h2 className="text-4xl md:text-5xl font-black tracking-tighter uppercase italic text-foreground">
          {t("title")}
        </h2>
        <p className="text-muted-foreground/80 text-lg font-medium max-w-lg mx-auto">
          {t("subtitle")}
        </p>
      </div>

      {status === "success" ? (
        <div className="bg-primary/5 border border-primary/10 text-primary p-8 rounded-[2rem] flex flex-col items-center justify-center gap-4 text-lg font-black animate-in fade-in zoom-in duration-500">
          <div className="h-16 w-16 rounded-2xl bg-primary/10 flex items-center justify-center mb-2">
            <CheckCircle2 size={32} />
          </div>
          <span className="uppercase tracking-widest">{t("thankYou")}</span>
          <span className="text-sm font-bold opacity-60 uppercase tracking-tighter">
            {t("checkInbox")}
          </span>
        </div>
      ) : (
        <form
          onSubmit={handleSubmit}
          className="flex flex-col sm:flex-row gap-4 max-w-xl mx-auto items-center"
          noValidate
        >
          <div className="w-full flex-1">
            <input
              type="email"
              placeholder={t("placeholder")}
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              disabled={status === "loading"}
              className="w-full bg-foreground/[0.03] dark:bg-white/[0.03] border border-foreground/5 dark:border-white/5 text-foreground placeholder:text-muted-foreground/40 rounded-full px-8 py-5 focus:outline-none focus:ring-2 focus:ring-primary/20 focus:border-primary/30 transition-all disabled:opacity-50 text-sm font-bold"
            />
          </div>
          <GlassButton
            type="submit"
            size="lg"
            className="w-full sm:w-auto font-black uppercase tracking-widest rounded-full px-12 py-5 bg-primary text-primary-foreground hover:opacity-90 transition-all duration-300 shadow-2xl shadow-primary/20"
            disabled={status === "loading"}
          >
            {status === "loading" ? (
              <Loader2 className="animate-spin" />
            ) : (
              t("subscribe")
            )}
          </GlassButton>
        </form>
      )}
    </div>
  );
}

/**
 * =====================================================================
 * BUY AGAIN BUTTON - Nút mua lại sản phẩm (Lịch sử đơn hàng)
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. QUICK RE-ORDER:
 * - Cho phép người dùng thêm nhanh sản phẩm từ đơn hàng cũ vào giỏ hàng.
 * - Sử dụng `useTransition` để xử lý trạng thái loading khi đang gọi API.
 *
 * 2. EVENT DISPATCHING:
 * - Sau khi thêm thành công, bắn ra event `cart_updated` để đồng bộ số lượng trên Header Badge.
 *
 * 3. NAVIGATION:
 * - Tự động chuyển hướng người dùng đến trang giỏ hàng (`/cart`) sau khi thêm thành công.
 * =====================================================================
 */

"use client";

import { addToCartAction } from "@/actions/cart";
import { Button } from "@/components/atoms/button";
import { useToast } from "@/hooks/use-toast";
import { ShoppingCart } from "lucide-react";
import { useTranslations } from "next-intl";
import { useRouter } from "next/navigation";
import { useTransition } from "react";

interface BuyAgainButtonProps {
  skuId: string;
}

export function BuyAgainButton({ skuId }: BuyAgainButtonProps) {
  const t = useTranslations("orders"); // Assumes 'buyAgain' key exists or will use generic
  const tToast = useTranslations("common.toast");
  const [isPending, startTransition] = useTransition();
  const router = useRouter();
  const { toast } = useToast();

  const handleBuyAgain = (e: React.MouseEvent) => {
    e.preventDefault(); // Prevent Link navigation if inside a Link
    e.stopPropagation();

    startTransition(async () => {
      try {
        const res = await addToCartAction(skuId, 1);
        if (res.success) {
          window.dispatchEvent(new Event("cart_updated"));
          toast({
            variant: "success",
            title: tToast("success"),
            description: t("addedToCart"),
          });
          router.push("/cart");
        } else {
          toast({
            variant: "destructive",
            title: tToast("error"),
            description: res.error || t("addToCartFailed"),
          });
        }
      } catch (error) {
        toast({
          variant: "destructive",
          title: tToast("error"),
          description: "Something went wrong",
        });
      }
    });
  };

  return (
    <Button
      variant="outline"
      size="sm"
      onClick={handleBuyAgain}
      disabled={isPending}
      className="gap-2 whitespace-nowrap"
    >
      <ShoppingCart size={14} />
      {isPending ? t("adding") : t("buyAgain")}
    </Button>
  );
}

/**
 * =====================================================================
 * PRODUCT IMAGE GALLERY - Bộ sưu tập ảnh sản phẩm
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. MAIN STAGE & THUMBNAILS:
 * - Hiển thị ảnh chính lớn và một dải ảnh nhỏ (thumbnails) bên dưới để người dùng chuyển đổi.
 * - Sử dụng `framer-motion` để tạo hiệu ứng chuyển ảnh mượt mà.
 *
 * 2. ZOOM & LIGHTBOX:
 * - Hỗ trợ zoom ảnh khi hover trên desktop.
 * - Click vào ảnh chính sẽ mở `ProductImageLightbox` để xem toàn màn hình.
 *
 * 3. SYNC WITH SKUS:
 * - Khi người dùng chọn một biến thể (màu sắc), gallery sẽ tự động chuyển đến ảnh tương ứng của biến thể đó.
 * =====================================================================
 */

"use client";

import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
  type CarouselApi,
} from "@/components/atoms/carousel";
import { Skeleton } from "@/components/atoms/skeleton";
import { cn } from "@/lib/utils";
import { AnimatePresence, motion } from "framer-motion";
import dynamic from "next/dynamic";
import Image from "next/image";
import { useEffect, useState } from "react";

const ProductImageLightbox = dynamic(
  () =>
    import("./product-image-lightbox").then((mod) => ({
      default: mod.ProductImageLightbox,
    })),
  { ssr: false }
);

interface ProductImageGalleryProps {
  images: string[];
  productName: string;
  activeImage?: string;
  onImageClick?: (image: string) => void;
  skus?: any[];
  options?: any[];
}

// ... (imports)

export function ProductImageGallery({
  images,
  productName,
  activeImage,
  onImageClick,
  skus,
  options,
}: ProductImageGalleryProps) {
  // ... (existing logic)
  const [api, setApi] = useState<CarouselApi>();
  const [isFirstLoadReady, setIsFirstLoadReady] = useState(false);

  // ... (useEffect for carousel)

  const [displayImage, setDisplayImage] = useState(activeImage || images[0]);
  const targetImage = activeImage || images[0];
  const isTransitioning = displayImage !== targetImage;
  const [isLightboxOpen, setIsLightboxOpen] = useState(false);
  const [isZoomed, setIsZoomed] = useState(false);

  // Preload initial image
  useEffect(() => {
    const img = new window.Image();
    img.src = images[0];
    img.onload = () => setIsFirstLoadReady(true);
  }, [images]);

  return (
    <div className="space-y-6 lg:sticky lg:top-24">
      {/* Main Image Stage */}
      <motion.div
        className="relative aspect-4/5 lg:aspect-auto lg:h-[70vh] w-full rounded-3xl overflow-hidden shadow-2xl border border-white/5 bg-neutral-900/50 group backdrop-blur-sm cursor-zoom-in"
        onMouseEnter={() => setIsZoomed(true)}
        onMouseLeave={() => setIsZoomed(false)}
        onClick={() => setIsLightboxOpen(true)}
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.5, ease: "easeOut" }}
      >
        {/* Initial Loading Skeleton */}
        <AnimatePresence>
          {!isFirstLoadReady && (
            <motion.div
              key="skeleton"
              initial={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 0.5 }}
              className="absolute inset-0 z-50"
            >
              <Skeleton className="w-full h-full" />
            </motion.div>
          )}
        </AnimatePresence>

        {/* 1. The Stable Display Image (Always Visible) */}
        <motion.div
          initial={{ opacity: 0, filter: "blur(20px)" }}
          animate={{
            opacity: isFirstLoadReady ? 1 : 0,
            filter: isFirstLoadReady ? "blur(0px)" : "blur(20px)",
          }}
          transition={{ duration: 0.8 }}
          className="absolute inset-0 w-full h-full"
        >
          <Image
            src={displayImage}
            alt={productName}
            fill
            sizes="(max-width: 1024px) 100vw, 50vw"
            className={cn(
              "object-cover transition-transform duration-700 ease-out-expo",
              isZoomed ? "scale-110" : "scale-100",
              "z-10"
            )}
            priority
            unoptimized
          />
        </motion.div>

        {/* 2. The Incoming Image (Loading in Background) */}
        {isTransitioning && (
          <Image
            key={targetImage} // Force new instance for reliable Load event
            src={targetImage}
            alt={productName}
            fill
            sizes="(max-width: 1024px) 100vw, 50vw"
            className={cn(
              "object-cover transition-transform duration-700 ease-out-expo absolute top-0 left-0",
              isZoomed ? "scale-110" : "scale-100",
              "opacity-0 z-20" // Hidden until loaded
            )}
            priority
            unoptimized
            onLoad={() => {
              // Image is ready! Promote it to displayImage.
              setDisplayImage(targetImage);
            }}
          />
        )}

        {/* Floating zoom hint */}
        <div className="absolute top-4 right-4 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500 z-30">
          <div className="bg-black/40 backdrop-blur-md text-white/90 text-[10px] uppercase tracking-wider font-bold px-3 py-1.5 rounded-full border border-white/10 shadow-lg">
            Zoom Ready
          </div>
        </div>
      </motion.div>

      {/* Thumbnails Carousel */}
      <div className="relative w-full">
        <Carousel
          opts={{
            align: "center",
            loop: true,
          }}
          className="w-full"
          setApi={setApi}
        >
          <CarouselContent className="-ml-4">
            {images.map((img, i) => (
              <CarouselItem key={i} className="pl-4 basis-1/4 lg:basis-1/5">
                <button
                  onClick={() => {
                    if (onImageClick) onImageClick(img);
                  }}
                  className={cn(
                    "relative aspect-square w-full rounded-xl overflow-hidden border transition-all duration-300",
                    targetImage === img
                      ? "border-primary ring-2 ring-primary/20 scale-95 opacity-100 shadow-[0_0_10px_rgba(var(--primary),0.3)]"
                      : "border-white/10 opacity-70 hover:opacity-100 hover:border-primary/50 hover:scale-105"
                  )}
                >
                  <Image
                    src={img}
                    alt={`${productName} thumbnail ${i + 1}`}
                    fill
                    sizes="100px"
                    className="object-cover"
                  />
                </button>
              </CarouselItem>
            ))}
          </CarouselContent>
          <CarouselPrevious className="left-2 bg-black/50 backdrop-blur-md border-white/10 hover:bg-black/80 hover:border-primary/50 text-white" />
          <CarouselNext className="right-2 bg-black/50 backdrop-blur-md border-white/10 hover:bg-black/80 hover:border-primary/50 text-white" />
        </Carousel>
      </div>

      <ProductImageLightbox
        isOpen={isLightboxOpen}
        onClose={() => setIsLightboxOpen(false)}
        images={images}
        activeImage={activeImage || images[0]}
        onImageChange={(img) => onImageClick?.(img)}
        skus={skus}
        options={options}
      />
    </div>
  );
}

"use client";

import { Button } from "@/components/atoms/button";
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
  type CarouselApi,
} from "@/components/atoms/carousel";
import { cn } from "@/lib/utils";
import { AnimatePresence, motion } from "framer-motion";
import { X, ZoomIn } from "lucide-react";
import { useTranslations } from "next-intl";
import Image from "next/image";
import { useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { TransformComponent, TransformWrapper } from "react-zoom-pan-pinch";

interface ProductImageLightboxProps {
  isOpen: boolean;
  onClose: () => void;
  images: string[];
  activeImage: string;
  onImageChange: (image: string) => void;
  skus?: any[];
  options?: any[];
}

export function ProductImageLightbox({
  isOpen,
  onClose,
  images,
  activeImage,
  onImageChange,
  skus,
  options,
}: ProductImageLightboxProps) {
  /**
   * =====================================================================
   * PRODUCT IMAGE LIGHTBOX - Xem ảnh phóng to
   * =====================================================================
   *
   * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
   *
   * 1. REACT PORTAL (`createPortal`):
   * - Lightbox cần hiển thị đè lên TOÀN BỘ trang web (z-index cao nhất).
   * - `createPortal` đưa component này ra khỏi DOM tree hiện tại và gắn trực tiếp vào `body`.
   * - Tránh bị ảnh hưởng bởi `overflow: hidden` hoặc `z-index` của component cha.
   *
   * 2. ZOOM & PAN INTERACTION:
   * - Sử dụng `react-zoom-pan-pinch` để xử lý thao tác zoom mượt mà trên cả Desktop và Mobile.
   * - Logic `watchDrag: !isZoomed`:
   *   - Khi chưa zoom: Cho phép vuốt sang trái/phải để đổi ảnh (Carousel).
   *   - Khi đang zoom: Tắt vuốt đổi ảnh để user có thể di chuyển (pan) vùng ảnh đang zoom.
   * =====================================================================
   */
  const t = useTranslations("product");
  const [api, setApi] = useState<CarouselApi>();
  const [mounted, setMounted] = useState(false);
  const [current, setCurrent] = useState(1);
  const [isZoomed, setIsZoomed] = useState(false);
  const lastClickTime = useRef<number>(0);
  const zoomRef = useRef<any>(null);

  useEffect(() => {
    setMounted(true);
  }, []);

  // Lock Body Scroll
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "unset";
    }
    return () => {
      document.body.style.overflow = "unset";
    };
  }, [isOpen]);

  // Sync Carousel with Active Image
  useEffect(() => {
    if (!api || !isOpen) return;
    const index = images.indexOf(activeImage);
    if (index !== -1 && api.selectedScrollSnap() !== index) {
      api.scrollTo(index, true);
    }
  }, [api, activeImage, images, isOpen]);

  // Sync Active Image with Carousel Slide
  useEffect(() => {
    if (!api) return;

    const onSelect = () => {
      const index = api.selectedScrollSnap();
      setCurrent(index + 1);
      const newImage = images[index];
      if (newImage !== activeImage) {
        onImageChange(newImage);
        // Reset zoom on slide change
        if (zoomRef.current) {
          zoomRef.current.resetTransform();
        }
      }
    };

    api.on("select", onSelect);
    return () => {
      api.off("select", onSelect);
    };
  }, [api, images, activeImage, onImageChange]);

  // Keyboard navigation
  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
      if (e.key === "ArrowLeft") api?.scrollPrev();
      if (e.key === "ArrowRight") api?.scrollNext();
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose, api]);

  // Track zoom state to disable Carousel drag
  const onTransformed = (ref: any) => {
    setIsZoomed(ref.instance.transformState.scale > 1);
  };

  // Find current SKU details
  const currentSku = skus?.find((s) => s.imageUrl === activeImage);
  const skuDetails = currentSku?.optionValues
    ?.map((ov: any) => {
      const option = options?.find((o) => o.id === ov.optionValue.optionId);
      const value = option?.values.find((v: any) => v.id === ov.optionValueId);
      return option && value ? `${option.name}: ${value.value}` : null;
    })
    .filter(Boolean)
    .join(" | ");

  if (!mounted || typeof window === "undefined") return null;

  return createPortal(
    <AnimatePresence>
      {isOpen && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/80 backdrop-blur-sm"
        >
          {/* Close Button */}
          <Button
            variant="ghost"
            size="icon"
            className="absolute top-4 right-4 z-50 text-white/70 hover:text-white hover:bg-white/10 rounded-full h-12 w-12"
            onClick={onClose}
          >
            <X className="h-6 w-6" />
          </Button>

          {/* Carousel */}
          <div className="w-full h-full flex items-center justify-center p-4 md:p-10">
            <Carousel
              setApi={setApi}
              className="w-full h-full max-w-7xl mx-auto [&_[data-slot=carousel-content]]:h-full"
              opts={{
                loop: true,
                align: "center",
                watchDrag: !isZoomed, // Disable drag when zoomed to allow panning
              }}
            >
              <CarouselContent className="h-full">
                {images.map((img, index) => (
                  <CarouselItem
                    key={index}
                    className="relative w-full h-full flex items-center justify-center"
                  >
                    <div className="w-full h-full flex items-center justify-center">
                      <TransformWrapper
                        ref={(ref) => {
                          if (index === images.indexOf(activeImage)) {
                            zoomRef.current = ref;
                          }
                        }}
                        initialScale={1}
                        minScale={1}
                        maxScale={8}
                        wheel={{ step: 0.2 }}
                        doubleClick={{ disabled: true }}
                        onTransformed={onTransformed}
                      >
                        {({ zoomIn, zoomOut, resetTransform, ...rest }) => {
                          // Manual double-click detection
                          const handleClick = (e: React.MouseEvent) => {
                            const now = Date.now();
                            if (now - lastClickTime.current < 300) {
                              // Double click detected
                              const scale = rest.instance.transformState.scale;

                              if (scale < 1.5) {
                                zoomIn(1, 300);
                              } else if (scale < 3.5) {
                                zoomIn(2, 300);
                              } else {
                                resetTransform(300);
                              }
                            }
                            lastClickTime.current = now;
                          };

                          return (
                            <TransformComponent
                              wrapperStyle={{ width: "100%", height: "100%" }}
                              contentStyle={{
                                width: "100%",
                                height: "100%",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                              }}
                            >
                              <div
                                className="relative w-full h-full flex items-center justify-center cursor-zoom-in"
                                onClick={handleClick}
                              >
                                <Image
                                  src={img}
                                  alt={`Product image ${index + 1}`}
                                  fill
                                  className="object-contain"
                                  priority={
                                    index === images.indexOf(activeImage)
                                  }
                                  unoptimized
                                  sizes="100vw"
                                />
                              </div>
                            </TransformComponent>
                          );
                        }}
                      </TransformWrapper>
                    </div>
                  </CarouselItem>
                ))}
              </CarouselContent>

              {/* Navigation Buttons */}
              <div className="absolute inset-x-0 top-1/2 -translate-y-1/2 flex justify-between px-4 pointer-events-none">
                <CarouselPrevious className="pointer-events-auto relative left-0 translate-y-0 h-12 w-12 border-white/10 bg-black/50 text-white hover:bg-black/80 hover:text-white" />
                <CarouselNext className="pointer-events-auto relative right-0 translate-y-0 h-12 w-12 border-white/10 bg-black/50 text-white hover:bg-black/80 hover:text-white" />
              </div>
            </Carousel>
          </div>

          {/* SKU Details & Zoom Hint */}
          <div className="absolute bottom-24 left-1/2 -translate-x-1/2 flex flex-col items-center gap-4 pointer-events-none w-full px-4 z-50">
            {skuDetails && (
              <div className="bg-black/60 backdrop-blur px-6 py-3 rounded-full text-white font-medium border border-white/10 shadow-lg text-center">
                {skuDetails}
              </div>
            )}

            <div className="bg-black/60 backdrop-blur px-4 py-2 rounded-full text-white/70 text-xs font-medium flex items-center gap-2 border border-white/10">
              <ZoomIn className="h-3 w-3" />
              <span>{t("zoomHint")}</span>
            </div>
          </div>

          {/* Thumbnails Strip */}
          <div className="absolute bottom-4 left-1/2 -translate-x-1/2 max-w-[90vw] overflow-x-auto flex gap-2 p-2 bg-black/40 backdrop-blur-md rounded-xl border border-white/10 no-scrollbar z-50">
            {images.map((img, idx) => (
              <button
                key={idx}
                onClick={() => api?.scrollTo(idx)}
                className={cn(
                  "relative w-12 h-12 rounded-lg overflow-hidden border-2 transition-all flex-shrink-0",
                  idx === current - 1
                    ? "border-primary opacity-100 scale-110"
                    : "border-transparent opacity-50 hover:opacity-100 hover:scale-105"
                )}
              >
                <Image
                  src={img}
                  fill
                  className="object-cover"
                  alt={`thumb-${idx}`}
                  sizes="48px"
                />
              </button>
            ))}
          </div>

          {/* Image Counter */}
          <div className="absolute top-4 left-4 bg-black/40 backdrop-blur-md px-3 py-1.5 rounded-full text-white/90 text-xs font-medium border border-white/10 z-50">
            {current} / {images.length}
          </div>
        </motion.div>
      )}
    </AnimatePresence>,
    document.body
  );
}

