"use client";

import {
  checkReviewEligibilityAction,
  getReviewsAction,
} from "@/actions/review";
import { Button } from "@/components/atoms/button";
import {
  ReviewItem,
  ReviewListSkeleton,
} from "@/components/molecules/review-item";
import { ReviewFormDialog } from "@/components/organisms/review-form-dialog";
import { motion } from "framer-motion";
import { Star } from "lucide-react";
import { useTranslations } from "next-intl";
import { useCallback, useEffect, useRef, useState } from "react";

/**
 * =====================================================================
 * PRODUCT REVIEWS - Danh sách đánh giá sản phẩm
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. ELIGIBILITY CHECK (`checkReviewEligibilityAction`):
 * - Không phải ai cũng được đánh giá. Chỉ những user đã mua sản phẩm (đã thanh toán) mới có quyền đánh giá.
 * - Hệ thống check dựa trên `productId` và trả về danh sách các SKU mà user đã mua.
 *
 * 2. REVIEW SUMMARY:
 * - Hiển thị điểm trung bình (`averageRating`) và tổng số đánh giá.
 * - Sử dụng `Math.round` để hiển thị số sao tương ứng.
 *
 * 3. DYNAMIC FETCHING:
 * - Dữ liệu được fetch ở Client (`useEffect`) để đảm bảo tính realtime và không làm chậm quá trình render trang sản phẩm chính.
 *
 * 4. PERFORMANCE OPTIMIZATIONS:
 * - useRef để prevent duplicate fetches in StrictMode
 * - useCallback để stabilize fetchData reference
 * =====================================================================
 */

interface ProductReviewsProps {
  productId: string;
  initialReviews?: any[];
  initialMeta?: any;
  initialPurchasedSkus?: any[];
}

export function ProductReviews({
  productId,
  initialReviews = [],
  initialMeta = null,
  initialPurchasedSkus = [],
}: ProductReviewsProps) {
  const t = useTranslations("reviews");
  const [reviews, setReviews] = useState<any[]>(initialReviews);
  const [meta, setMeta] = useState<any>(initialMeta);
  const [purchasedSkus, setPurchasedSkus] =
    useState<any[]>(initialPurchasedSkus);
  const [showReviewDialog, setShowReviewDialog] = useState(false);
  const [selectedSkuForReview, setSelectedSkuForReview] = useState<any>(null);
  const [loading, setLoading] = useState(initialReviews.length === 0);
  const [loadingMore, setLoadingMore] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const hasFetched = useRef(initialReviews.length > 0);

  const fetchData = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [reviewsRes, eligibilityRes] = await Promise.all([
        getReviewsAction(productId), // Initial fetch (limit 5)
        checkReviewEligibilityAction(productId),
      ]);

      if (reviewsRes.success && reviewsRes.data) {
        setReviews(reviewsRes.data);
        setMeta(reviewsRes.meta);
      }

      if (eligibilityRes.success && eligibilityRes.data) {
        setPurchasedSkus(eligibilityRes.data.purchasedSkus || []);
      }
    } catch (e) {
      console.error(e);
      setError("Failed to load reviews");
    }
    setLoading(false);
  }, [productId]);

  const loadMore = async () => {
    if (!meta?.nextCursor || loadingMore) return;
    setLoadingMore(true);
    try {
      const res = await getReviewsAction(productId, meta.nextCursor);
      if (res.success && res.data) {
        setReviews((prev) => [...prev, ...res.data]);
        setMeta(res.meta);
      }
    } catch (e) {
      console.error("Failed to load more reviews", e);
    }
    setLoadingMore(false);
  };

  useEffect(() => {
    if (hasFetched.current) return;
    hasFetched.current = true;
    fetchData();
  }, [productId]);

  return (
    <div className="space-y-8">
      {error && (
        <div className="bg-red-50 dark:bg-red-950/20 text-red-600 dark:text-red-400 p-5 rounded-2xl border border-red-200 dark:border-red-900/30 font-medium">
          {error}
        </div>
      )}

      {/* Purchased Items Section */}
      {purchasedSkus.length > 0 && (
        <div className="bg-primary/5 p-8 rounded-4xl border border-primary/20 shadow-lg shadow-primary/5">
          <h3 className="text-xl font-black mb-6 text-primary tracking-tight uppercase">
            {t("purchasedItems")}
          </h3>
          <div className="space-y-5">
            {purchasedSkus.map((sku) => (
              <div
                key={sku.id}
                className="flex items-center justify-between bg-background p-5 rounded-2xl shadow-sm border border-foreground/5"
              >
                <div>
                  <div className="font-bold text-base">
                    {sku.optionValues
                      ?.map((ov: any) => ov.optionValue?.value)
                      .join(" / ") || "Default Variant"}
                  </div>
                  {sku.review ? (
                    <div className="text-sm text-emerald-600 dark:text-emerald-400 flex items-center gap-2 mt-2 font-medium">
                      <span>✓ {t("reviewed")}</span>
                      <span className="text-foreground/20">•</span>
                      <div className="flex gap-0.5">
                        {[1, 2, 3, 4, 5].map((star) => (
                          <Star
                            key={star}
                            className={`w-3.5 h-3.5 ${
                              star <= sku.review.rating
                                ? "fill-amber-400 text-amber-400"
                                : "text-foreground/10"
                            }`}
                          />
                        ))}
                      </div>
                    </div>
                  ) : (
                    <div className="text-sm text-muted-foreground/60 mt-2 font-medium">
                      {t("notReviewed")}
                    </div>
                  )}
                </div>
                <Button
                  variant={sku.review ? "outline" : "default"}
                  size="sm"
                  onClick={() => {
                    setSelectedSkuForReview(sku);
                    setShowReviewDialog(true);
                  }}
                  className="font-bold uppercase tracking-wider text-xs"
                >
                  {sku.review ? t("editReview") : t("writeReview")}
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
        {/* Summary */}
        <motion.div
          className="md:col-span-1 space-y-6"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.5, delay: 0.2 }}
        >
          <div className="bg-foreground/2 p-8 rounded-4xl text-center border border-foreground/5 shadow-lg">
            <div className="text-5xl font-black text-primary">
              {meta?.averageRating?.toFixed(1) || "0.0"}
            </div>
            <div className="flex justify-center my-4 gap-1">
              {[1, 2, 3, 4, 5].map((star) => (
                <Star
                  key={star}
                  className={`w-6 h-6 ${
                    star <= Math.round(meta?.averageRating || 0)
                      ? "fill-amber-400 text-amber-400"
                      : "text-foreground/10"
                  }`}
                />
              ))}
            </div>
            <div className="text-sm text-muted-foreground/70 font-medium">
              {t("basedOn", { count: meta?.totalReviews || 0 })}
            </div>
          </div>
        </motion.div>

        {/* Reviews List */}
        <div className="md:col-span-2 space-y-8">
          {loading ? (
            <ReviewListSkeleton count={3} />
          ) : reviews.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground/60 font-medium">
              {t("noReviews")}
            </div>
          ) : (
            <>
              {reviews.map((review, index) => (
                <ReviewItem key={review.id} review={review} index={index} />
              ))}

              {/* Load More Button */}
              {meta?.nextCursor && (
                <div className="flex justify-center pt-4">
                  <Button
                    variant="outline"
                    onClick={loadMore}
                    disabled={loadingMore}
                    className="w-full md:w-auto"
                  >
                    {loadingMore ? "Loading..." : t("loadMore")}
                  </Button>
                </div>
              )}
            </>
          )}
        </div>
      </div>

      <ReviewFormDialog
        productId={productId}
        sku={selectedSkuForReview}
        open={showReviewDialog}
        onOpenChange={setShowReviewDialog}
        onSuccess={() => {
          fetchData();
        }}
      />
    </div>
  );
}

"use client";

import {
  createReviewAction,
  deleteReviewAction,
  updateReviewAction,
} from "@/actions/review";
import { Button } from "@/components/atoms/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/atoms/dialog";
import {
  Form,
  FormControl,
  FormField,
  FormItem,
  FormLabel,
  FormMessage,
} from "@/components/atoms/form";
import { ImageUpload } from "@/components/atoms/image-upload";
import { Textarea } from "@/components/atoms/textarea";
import { useToast } from "@/hooks/use-toast";
import { zodResolver } from "@hookform/resolvers/zod";
import { Star } from "lucide-react";
import { useTranslations } from "next-intl";
import Image from "next/image";
import { useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import * as z from "zod";

/**
 * =====================================================================
 * REVIEW FORM DIALOG - Form viết/sửa đánh giá
 * =====================================================================
 *
 * 📚 GIẢI THÍCH CHO THỰC TẬP SINH:
 *
 * 1. ZOD SCHEMA:
 * - Định nghĩa quy tắc: Rating từ 1-5 sao, nội dung tối thiểu 10 ký tự.
 * - Giúp validate dữ liệu ngay lập tức và hiển thị thông báo lỗi thân thiện.
 *
 * 2. UPSERT LOGIC (Update or Insert):
 * - Nếu `sku.review` đã tồn tại: Gọi `updateReviewAction` (Sửa).
 * - Nếu chưa có: Gọi `createReviewAction` (Thêm mới).
 * - Giúp tái sử dụng 1 Dialog cho cả 2 mục đích.
 *
 * 3. INTERACTIVE RATING:
 * - Các ngôi sao có thể click được. Khi click, giá trị `rating` trong form sẽ được cập nhật.
 * =====================================================================
 */

interface ReviewFormDialogProps {
  productId: string;
  sku: {
    id: string;
    optionValues?: { optionValue: { value: string } }[];
    review?: {
      id: string;
      rating: number;
      content: string;
      images?: string[];
    };
  };
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
}

export function ReviewFormDialog({
  productId,
  sku,
  open,
  onOpenChange,
  onSuccess,
}: ReviewFormDialogProps) {
  const t = useTranslations("reviews");

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>
            {sku?.review ? t("form.edit") : t("form.write")}
          </DialogTitle>
          <DialogDescription>
            {sku?.optionValues
              ?.map(
                (ov: { optionValue: { value: string } }) =>
                  ov.optionValue?.value
              )
              .join(" / ") || "Product Variant"}
          </DialogDescription>
        </DialogHeader>
        <ReviewForm
          productId={productId}
          sku={sku}
          onOpenChange={onOpenChange}
          onSuccess={onSuccess}
        />
      </DialogContent>
    </Dialog>
  );
}

function ReviewForm({
  productId,
  sku,
  onOpenChange,
  onSuccess,
}: {
  productId: string;
  sku: {
    id: string;
    optionValues?: { optionValue: { value: string } }[];
    review?: {
      id: string;
      rating: number;
      content: string;
      images?: string[];
    };
  };
  onOpenChange: (open: boolean) => void;
  onSuccess: () => void;
}) {
  const t = useTranslations("reviews");
  const tCommon = useTranslations("common");
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [files, setFiles] = useState<File[]>([]);

  // ... onSubmit logic
  const onSubmit = async (values: z.infer<typeof formSchema>) => {
    if (!sku) return;

    setLoading(true);

    let imageUrls: string[] = [];
    if (files.length > 0) {
      const formData = new FormData();
      // files.forEach((f) => formData.append("images", f)); // Old server logic

      try {
        // Use Client-Side Signed Upload
        const { uploadToCloudinary } = await import("@/lib/cloudinary");

        // Parallel uploads
        const uploadedUrls = await Promise.all(
          files.map((file) => uploadToCloudinary(file))
        );

        imageUrls = uploadedUrls;
      } catch (e) {
        console.error("Upload failed", e);
        toast({
          title: tCommon("toast.error"),
          description: "Upload failed: " + (e as Error).message,
          variant: "destructive",
        });
        setLoading(false);
        return;
      }
    }

    let result: { success: boolean; error?: string };
    if (sku.review) {
      // Update existing review
      result = await updateReviewAction(sku.review.id, {
        rating: values.rating,
        content: values.content,
        images: imageUrls.length > 0 ? imageUrls : sku.review.images, // Append or replace? Logic decision: Replace usually, or UI logic?
        // Current UI: "Add Image". If I support existing images, I need to load them.
      });
    } else {
      // Create new review
      result = await createReviewAction({
        productId,
        skuId: sku.id,
        rating: values.rating,
        content: values.content,
        images: imageUrls,
      });
    }
    // ...
  };

  const formSchema = z.object({
    rating: z.number().min(1).max(5),
    content: z.string().min(10, t("form.atLeast10")),
  });

  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      rating: sku?.review?.rating || 5,
      content: sku?.review?.content || "",
    },
  });

  // Re-initialize form when sku changes (if the dialog stays open but sku changes)
  useEffect(() => {
    if (sku) {
      form.reset({
        rating: sku.review?.rating || 5,
        content: sku.review?.content || "",
      });
    }
  }, [sku, form]);

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        <FormField
          control={form.control}
          name="rating"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="flex items-center gap-2 text-base font-semibold">
                {t("form.rating")}
              </FormLabel>
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map((star) => (
                  <Star
                    key={star}
                    className={`w-8 h-8 cursor-pointer transition-colors ${
                      star <= field.value
                        ? "fill-yellow-400 text-yellow-400"
                        : "text-gray-300 hover:text-yellow-200"
                    }`}
                    onClick={() => field.onChange(star)}
                  />
                ))}
              </div>
              <FormMessage />
            </FormItem>
          )}
        />

        <FormField
          control={form.control}
          name="content"
          render={({ field }) => (
            <FormItem>
              <FormLabel className="text-base font-semibold">
                {t("form.review")}
              </FormLabel>
              <FormControl>
                <Textarea
                  placeholder={t("form.placeholder")}
                  className="min-h-[120px] resize-none text-base"
                  {...field}
                />
              </FormControl>
              <FormMessage />
            </FormItem>
          )}
        />

        <div className="space-y-3">
          <FormLabel className="text-base font-semibold block">
            {t("form.images")}
          </FormLabel>

          <div className="grid grid-cols-4 gap-4">
            {files.map((file, idx) => (
              <div
                key={idx}
                className="relative aspect-square border rounded-lg overflow-hidden group"
              >
                <Image
                  src={URL.createObjectURL(file)}
                  alt="preview"
                  fill
                  className="object-cover"
                  unoptimized
                />
                <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                  <button
                    type="button"
                    onClick={() =>
                      setFiles((prev) => prev.filter((_, i) => i !== idx))
                    }
                    className="bg-red-500 hover:bg-red-600 text-white rounded-full p-1.5 transition-colors"
                  >
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="16"
                      height="16"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                      strokeLinecap="round"
                      strokeLinejoin="round"
                    >
                      <path d="M18 6 6 18" />
                      <path d="m6 6 12 12" />
                    </svg>
                  </button>
                </div>
              </div>
            ))}

            {files.length < 5 && (
              <div className="relative aspect-square">
                <ImageUpload
                  value=""
                  onChange={(f) => {
                    if (f) setFiles((prev) => [...prev, f]);
                  }}
                  onRemove={() => {}}
                />
              </div>
            )}
          </div>
          <p className="text-xs text-muted-foreground">
            {files.length}/5 images. PNG, JPG, WEBP up to 5MB.
          </p>
        </div>

        <DialogFooter className="flex gap-2 sm:justify-between pt-4 border-t">
          {sku?.review && (
            <Button
              type="button"
              variant="destructive"
              disabled={loading}
              onClick={async () => {
                setLoading(true);
                if (!sku.review) return;
                const result = await deleteReviewAction(sku.review.id);
                setLoading(false);
                if (result.success) {
                  toast({
                    variant: "success",
                    title: tCommon("toast.success"),
                    description: t("form.deleteSuccess"),
                  });
                  onOpenChange(false);
                  onSuccess();
                } else {
                  toast({
                    title: tCommon("toast.error"),
                    description: result.error,
                    variant: "destructive",
                  });
                }
              }}
            >
              {tCommon("delete")}
            </Button>
          )}
          <div className="flex gap-2 w-full sm:w-auto justify-end">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={loading}
            >
              {tCommon("cancel")}
            </Button>
            <Button type="submit" disabled={loading} className="min-w-[120px]">
              {loading ? (
                <>
                  <span className="animate-spin mr-2">⏳</span>
                  {t("form.submitting")}
                </>
              ) : (
                t("form.submit")
              )}
            </Button>
          </div>
        </DialogFooter>
      </form>
    </Form>
  );
}

